/* Persona 3: Equinox · Act IV story events, 9/25 to 12/21 (format: assets/femc/game/scene.js; events: core.js dueEvent).
   Loads after story-act3.js. Twenty-two dated events. Act III closed on 9/24 early and already showed the act card, so this
   file adds none. The three full moons are operations, as in Acts I-III: each has a { battle: { kind: 'operation' } } line
   whose op is listed in calendar.js `ops`, and the battle side plays it from battle.js SCRIPTS. Their ids are the Well's
   reserved ones ('eqx-1023' 10/23, 'eqx-1122' 11/22, 'eqx-1221' 12/21): assets/femc/equinox/battle/well.js opens the next
   block of the Well when each is beaten. The event that carries an op has the op's id, as in the earlier acts.
   Three late-night events in the Well are door scenes (one per world, the act's share), and three carry a party member's
   first night with a Persona: those end with a { join } line (config.js `party` lists the three with `flag: 'joined-<id>'`).
   Conditions: a few scenes read link ranks ({ ifRank }), flags ({ ifFlag } / { ifCount }) and Act IV's own flags. Where a scene
   needs one of the year's recorded answers (data/flags.js `choices`, kept in the save's route.choices), it writes it as an
   { ifChoice: { name: value } } line that only sets a flag; core.js reads ifChoice (added Nov 16), so that line
   sets its flag when the answer matches (see the private build notes). Helpers below only build those lines.
   Who's dating whom: `dating(id, then, else)` as story-act3.js (the link's route, or a kiss flag from its ranks or earlier acts).
   Speakers: the parents use their couple links' member ids (config.js `faces`); people without portraits speak in narration.
   Bookkeeping (data/flags.js): counters `cakes`, `choose`, `doors.R|S|H`; choices `asks.solar.christmas`, `red`; flags listed
   in flags.js `hooks` / `cosmetic` under "Act IV".
   Art still to make: `// CG: eqx-*` and `// BG: *` comments mark it; stand-in backgrounds are used until then. */
{
  const KISS = {
    haechan: ['eqx-hc-roof-kiss', 'eqx-hc-stayed-night'],
    jungwon: ['eqx-jw-council-kiss', 'eqx-jw-summer-kiss', 'eqx-jw-room-four', 'eqx-jw-both-names'],
    jihoon: ['eqx-jihoon-roof', 'eqx-jihoon-booth-kiss', 'eqx-jihoon-canal-kiss', 'eqx-jihoon-dark-kiss', 'eqx-jihoon-room'],
    akihiko: ['eqx-aki-lamp-kiss', 'eqx-aki-gate-kiss', 'eqx-aki-shallows-kiss', 'eqx-aki-room-kiss', 'eqx-aki-woke'],
    minji: ['eqx-minji-kiss'],
    shinjiro: ['eqx-shinji-sink-kiss', 'eqx-shinji-awning-kiss', 'eqx-shinji-stayed-night']
  };
  const dating = (id, then, els) => ({ ifRomance: id, then, else: KISS[id].length ? [{ ifCount: { of: KISS[id], min: 1 }, then, else: els || [] }] : (els || []) });
  // A recorded answer, read into a flag (see the header): sets `flag` when choices[name] is value (core.js branch reads { ifChoice }).
  const choiceFlag = (name, value, flag) => ({ ifChoice: { [name]: value }, then: [{ flag }], else: [] });
  // Sets `flag` if any of `ids` is at rank r or more.
  const anyRank = (ids, r, flag) => ids.reduceRight((inner, id) => [{ ifRank: { [id]: r }, then: [{ flag }], else: inner }], [])[0];
  // Every condition in `conds` (condition objects without then/else) must hold for `then` to play.
  const all = (conds, then) => conds.reduceRight((inner, c) => [Object.assign({}, c, { then: inner, else: [] })], then)[0];
  // The year's route deaths (Act IV's two) and the flags that mean somebody said "Stay. Please."
  const DEAD = ['dead.shinjiro', 'dead.aigis'];
  const ASKED = ['eqx-asked-hyein', 'eqx-asked-house', 'eqx-asked-akihiko', 'eqx-asked-hanni', 'eqx-asked-jaehyun', 'eqx-asked-fathers', 'eqx-asked-aigis',
    'eqx-asked-chaewon', 'eqx-asked-sakura', 'eqx-asked-mark', 'eqx-asked-danielle', 'eqx-asked-trio', 'eqx-asked-hateclub',
    'eqx-asked-parents-runners', 'eqx-asked-parents-hoax']; // + the summer arrivals' and parents' rank asks (Nov 16)
  const MINE = ['eqx-supper-mine', 'eqx-hill1-mine', 'eqx-hill2-mine', 'eqx-hill3-mine', 'eqx-choose-house', 'eqx-choose-hyein',
    'eqx-choose-jaehyun', 'eqx-ferry-mine', 'eqx-moon-mine', 'eqx-oka-night-mine', 'eqx-choose-fathers', 'eqx-xmas-mine',
    'eqx-oka-plums-mine', 'eqx-oka-persimmon-mine', 'eqx-oka-spring-mine', 'eqx-aigis-own-door', // ranks 4-6 (Nov 16)
    'eqx-choose-parents-runners', 'eqx-choose-parents-hoax'];
  // The names the three new Personas answer to (to be designed with Kat; change here only).
  const PERSONA = { yunjin: 'Bari', hanni: 'Âu Cơ', hyein: 'Jiknyeo' };

(window.FEMC_GAME_EVENTS ||= []).push(

  { id: 'eqx-house-without', date: '9/25', slot: 'evening', consumes: true, title: 'the house without them', place: 'The Oka Boarding House · The Long Table', time: 'Evening',
    cast: { solar: 'Solar', jaehyun: 'Jaehyun', 'jaesang-runners': 'Jaesang', 'taesang-strangers': 'Taejoon', 'kim-dad': 'Mr. Kim', mrsoka: 'Mrs. Oka', haechan: 'Haechan', shinjiro: 'Shinjiro' },
    scene: [
    { place: 'Iwatodai Dorm · Kitchen', time: 'Evening', bg: 'iwatodaidorm-kitchen-night', music: 'badfeeling' },
    { n: "Shinjiro had made enough stew for thirty people, which was the first thing he'd done since the bridge that anybody had seen him do, and he'd made it at four in the afternoon with the radio off and the kitchen door shut, and when Solar came down for water he was standing over the pot with the ladle in his left hand and his right hand flat on the counter, very still, the way you stand when you're waiting for something to stop hurting." },
    { s: 'shinjiro', f: 'neutral', t: "...It's for over there. Take it over there." },
    { s: 'solar', f: 'neutral', t: "She'll have cooked." },
    { s: 'shinjiro', f: 'neutral', t: "Yeah. I know she'll have cooked. Take it anyway. Put it on the table where they can see it and tell them a guy made it who doesn't put anything in his food but food." },
    { n: "He put the lid on. He put the whole pot in a cloth bag with a towel round it to keep it warm, and put the bag into her arms, heavy, hot against her ribs through her shirt, and then he didn't let go of the handles right away, and she looked at him, and he looked at the pot." },
    { s: 'shinjiro', f: 'sad', t: "Your dad. The American one. He didn't eat breakfast. Or lunch. Jaehyun called. Make him eat this." },
    { place: 'The Oka Boarding House · Front Hall', time: 'Evening', bg: 'eqx-oka-gate', music: 'eerie' },
    { n: "The shoes were in the front hall." },
    { n: "Somebody had brought them back from the bridge, and somebody had set them down in the genkan, on the stone step where you took your own shoes off, three pairs in a row, the heels and the embroidered slippers and the flat black ones, side by side, neat, their toes pointing at the front door. Facing out. So they'd be ready. So whoever came in through that door barefoot would find them waiting and wouldn't have to walk on the cold stone." },
    { n: "Solar stood in the open door with the pot in her arms and looked at them for a long time, and the evening came in round her, cool for the first time since June, and smelled of the river." },
    { n: "Haechan, behind her, on the step, didn't say anything. He took his shoes off very carefully and put them at the far end of the row, a good half meter away from the others, so they wouldn't touch." },
    { place: 'The Oka Boarding House · The Long Table', time: 'Evening', bg: 'eqx-oka-kitchen', music: 'tender' },
    // BG: oka-dining-room — the front room of an old Japanese house turned into a dining room, its sliding screens taken out, a long low table made of several tables pushed end to end, mismatched bowls, a hanging lamp, three middle-aged men sitting close together at one end.
    { n: "The long table was set for sixteen and there were five of them at it." },
    { n: "The three fathers sat together at the end nearest the kitchen, the way men sit at a hospital, close, not touching, as if the room were much bigger than it was. Jaesang in the middle, still in the suit from the bridge, the jacket off, his shirt the color of the walk at dawn. Mr. Kim on his left, in his fleece, with the flat black shoes' paper box from the bridge on the floor between his feet, empty, which he'd carried everywhere for two days. Taejoon on the right, in his shirtsleeves, his hands on his knees under the table, looking at the place across from him where nobody sat." },
    { n: "And Jaehyun, kneeling up beside his father, cutting fish." },
    { n: "That was what he was doing when Solar came in. He'd taken the grilled mackerel off his father's plate and he was taking the bones out of it with his chopsticks, one at a time, the long fine ones along the spine, and laying them on the edge of the plate in a row, the way Solji had done for both of them when they were small, at the kitchen island, on Sundays, while their father read the paper behind it and said *you two are spoiled* and didn't look up." },
    { n: "Jaesang wasn't reading anything. He was watching his son's hands." },
    { s: 'jaehyun', f: 'neutral', t: "...There. That's all of them. You can eat it now. You have to eat it now, Dad, I took all the bones out, you can't not eat it after I took all the bones out." },
    { s: 'jaesang-runners', f: 'sad', t: "I know." },
    { s: 'jaehyun', f: 'neutral', t: "So eat it." },
    { s: 'jaesang-runners', f: 'sad', t: "...She used to do that. Your mother. For you and your sister." },
    { s: 'jaehyun', f: 'sad', t: "I know she did. I was there. Eat it." },
    { n: "He didn't eat it. Jaehyun sat back on his heels with his chopsticks in his hand and looked at the plate and then at his father's face and then at the table, and Solar watched him not know what to do next, the way she'd watched him not know at the shrine steps in April and on the gate under the light in August; except that this time there was no plan and no procedure and no rule, there was only a man who'd taught him to run splits on a track at six in the morning, sitting in a borrowed house in borrowed slippers, being looked after by him, which neither of them had ever practiced." },
    { n: "She put the pot down on the table. Hard. All of them looked up." },
    { s: 'solar', f: 'neutral', t: "Shinjiro made this. He says he doesn't put anything in his food but food. He says you have to eat it. He says that specifically to you, Dad." },
    { n: "Her father looked at the pot. Then at her. Something in his face that had been somewhere else since the bridge came back from wherever it was, a centimeter, the way it came back on a Sunday when she'd said something clever across the island and he'd lowered the paper." },
    { s: 'jaesang-runners', f: 'neutral', t: "...The boy with the coat. The one who doesn't talk." },
    { s: 'solar', f: 'neutral', t: "That's the one." },
    { s: 'jaesang-runners', f: 'neutral', t: "He told me yesterday I was holding my chopsticks wrong. Unprompted." },
    { s: 'solar', f: 'neutral', t: "You are, though." },
    { n: "He ate it. Not much. Four spoonfuls and a piece of the potato. But he ate it, and Jaehyun watched every spoon go up and come down, and at the third one put his chopsticks down on the rest and put both his hands flat on his thighs and breathed out through his nose, very slowly, and looked at the ceiling." },
    { n: "Mr. Kim ate two bowls and said it was good, very good, it needed salt; Taejoon ate one bowl without a word, slowly, all of it, and then sat with the empty bowl in his hands, looking into it, until Haechan reached over and took it and filled it again and put it back in his hands, and he said, in Korean, without looking up, *thank you, son*, and ate that one too." },
    { n: "Mrs. Oka came in from the kitchen with a tray." },
    { s: 'mrsoka', f: 'happy', t: "Oh, you brought something. How kind. How very kind. That boy can cook, can't he. I'll have to get the recipe off him. No, no, eat it, eat it all, it's good for them to have something from home." },
    { n: "Home. Solar watched her say it. She watched her set the tray down at the end of the table, the teapot, five cups, a plate of rice cakes in a ring with one in the middle; watched her pour, and put a cup into each father's hands and close their fingers round it with her own, warm, gloved; watched her put her hand on the back of Mr. Kim's neck for a second as she passed, and his eyes close." },
    { s: 'mrsoka', f: 'sad', t: "They're not eating, you know. Not properly. I can't get anything into them but tea and these. Just these. I make them every morning and they eat them, bless them, and nothing else. But you've got to eat something, when it's like this. You've got to keep something in you." },
    { n: "Mr. Kim already had one in his hand. He ate it in two bites, with his eyes shut, like medicine, like the first good thing in days." },
    { n: "Solar's stomach turned over once, slowly, the way it had at the wake." },
    { n: "Mrs. Oka went back into the kitchen. The door between the rooms was a wooden sliding one, and she left it open a hand's width behind her, and from where Solar sat, at the corner of the table, at an angle nobody else at the table had, she could see through the gap into the kitchen, a strip of it: the counter, the end of the stove, the window over the sink black with evening." },
    { n: "There was a woman at the stove." },
    { n: "Not Mrs. Oka. Solar knew that before she knew anything else, the way you know your own name called across a crowded room. The woman at the stove was taller. Her back was to the door. She had her weight on one hip, the left, the way you stand when you've been on your feet all day at a party you're hosting and you think nobody's looking. Her hair was up in a clip, a tortoiseshell clip, coming loose at the side. She was wearing a cream cardigan, and over the cardigan a white apron, and the apron's strings were tied in a bow at the small of her back." },
    { n: "The bow sat on a line." },
    { n: "A line down the back of the cardigan, from the collar to the apron strings, straight as a seam, where the knit had been parted, and closed again, not quite; a finger's width open, in the lamplight, all the way down. And under it, where the line was open, something that wasn't a back. Something that moved when she lifted the kettle off the ring, the way a cat moves under a blanket." },
    { n: "She reached up for the shelf above the stove. On her toes. Her left hand flat on the edge of the counter for balance. The way Solji reached up for the good glasses in the kitchen on Seventy-Fourth Street, every single time, on her toes, her left hand on the marble, laughing at herself, *I married a tall man so I'd never have to do this*." },
    { n: "At the table, a meter from that door, with his back to it, Jaesang was holding his tea in both hands and listening to Mr. Kim explain the train lines." },
    { n: "Solar couldn't move. Her hands were in her lap. Her body had gone so still that she could hear the lamp ticking over the table, and her own blood, and the kettle beginning to sing on the ring behind the door, very softly, the way it sang in the kitchen by the river in the red; and the woman at the stove tipped her head a little to one side, as if she'd heard her name, and began to turn round." },
    { choose: [
      { t: "(Get up. Go to the kitchen door.)", flag: 'eqx-looked-kitchen', then: [
        { n: "She got up. Her knees didn't want to. She said *bathroom*, to nobody, and went round the end of the table, and put her hand on the wooden door, and slid it open." },
        { n: "Mrs. Oka was at the stove. Small. Gray kimono, sleeves tied back, white gloves. Lifting the kettle off the ring. She looked round at Solar with her face crinkling up, pleased, surprised." },
        { s: 'mrsoka', f: 'happy', t: "Oh! You gave me a fright. Did you want more tea, child? It's just coming." },
        { n: "There was nobody else in the kitchen. There was nowhere for anybody else to be. One small room, one window, black; one back door, bolted, the bolt dusty. The kettle. The cutting board. A bowl of white dough under a cloth." },
        { n: "On the edge of the shelf above the stove, caught on a splinter of the old wood, a single thread. Cream. Wool. A few centimeters of it, curled, moving a little in the heat coming up off the ring." },
        { n: "Solar looked at it. Mrs. Oka looked at Solar looking at it, and smiled, kind, patient, and reached up, without going on her toes at all, and picked it off the splinter with two gloved fingers, and dropped it into the stove." },
        { s: 'mrsoka', f: 'neutral', t: "The things that get caught on that shelf. I keep meaning to sand it." }
      ] },
      { t: "(Don't move. Don't let your face do anything.)", then: [
        { n: "She didn't move. She looked down at her own bowl, at the stew going cold in it, and made her face into the face she used at Foundation dinners when somebody's husband told her what she should study, pleasant, interested, nothing; and she held it there; and she didn't look up." },
        { n: "She didn't look up when the kettle stopped singing. She didn't look up when the door slid the rest of the way open and the tray came through it, and the gray kimono, and the white gloves, and Mrs. Oka said *here we are, more tea, who's for more tea*." },
        { n: "She didn't look up for the rest of the meal. When she did, at the end, through the door, the stove was a stove and the shelf was a shelf." }
      ] }
    ] },
    { n: "Jaehyun walked her to the gate afterward. Haechan had gone ahead to the corner to wait; he did that now, without being asked, stood a little way off so that two people could finish a thing without him." },
    { n: "Jaehyun stopped at the gate with his hands in his pockets and looked back at the house, at the lit front room, at the three shapes of the men at the table through the paper screen." },
    { s: 'jaehyun', f: 'sad', t: "He calls her. Every morning. Seven-fifteen. He sets an alarm. He sits on the edge of the futon and calls her number and holds the phone to his ear until it stops, and then he puts it down and gets dressed." },
    { s: 'jaehyun', f: 'sad', t: "It never connects. It never connected, here, not once since August. He knows that. He calls anyway. Seven-fifteen." },
    { s: 'jaehyun', f: 'neutral', t: "...I used to set my alarm for seven-sixteen. So I'd know he hadn't called me." },
    { n: "He laughed. It wasn't anything like a laugh. He put his forehead down on the top of the gate for a second, on the cold wood, and Solar put her hand on the back of his head, the way you'd hold a younger brother's head when he'd been sick, and he let her, and then he straightened up and wiped his face on his sleeve and was Jaehyun." },
    { s: 'jaehyun', f: 'neutral', t: "Go home. Twos. Haechan's waiting. I've got him." },
    { n: "She went. At the corner she looked back, the way you shouldn't, and the gate was shut, and over the wall the persimmon tree had gone orange all at once in the last week, every fruit on it, heavy, bright as lamps; and somewhere in the house a kettle had started to sing again." }
  ] },

  { id: 'eqx-pencil', date: '9/27', slot: 'after', consumes: true, title: 'a sound like a pencil', place: 'Paulownia Mall · Chagall Café', time: 'After School',
    cast: { solar: 'Solar', akihiko: 'Akihiko' },
    scene: [
    { place: 'Iwatodai Station · Steps', time: 'After School', bg: 'iwatodai-station', music: 'rain' },
    { n: "It rained on Monday. The first real rain of autumn, cold, coming in sideways off the bay in long gray sheets that made the station steps shine and the umbrellas go up all down the street at once like a field of something flowering." },
    { n: "Solar walked past her twice." },
    { n: "That was the thing she'd think about afterward, sitting in the café with her coat still dripping. Twice. Up the steps from the platform, and down again because she'd left her umbrella on the train and the train had already gone, and past her, both times, a woman sitting against the wall under the overhang at the side of the steps where the rain didn't reach, in a blue coat buttoned to the throat, with a black case standing beside her, and her head down, as if she were asleep." },
    { n: "It was the third time, at the bottom, turning back up into the rain with no umbrella, that Solar's body stopped before she'd told it to." },
    { n: "In Solstice she'd walked past her twice on these steps. In March. In another year. And never stopped." },
    { s: 'solar', f: 'surprised', t: "...Hanne." },
    { n: "The woman lifted her head." },
    { n: "Her face was very white. She was younger than Solar had remembered, or older; it was the kind of face that had stopped telling anyone which. Her eyes were red at the rims. Her hair was coming out of its pins. And her right hand, in her lap, on the blue wool of her coat, was in a splint: two flat metal strips taped along the back of it from the wrist to the knuckles, and the fingers in it swollen and dark, and bound together, and turned very slightly the wrong way, the way the fingers of a glove go when you've put it down on a table without thinking about how it lands." },
    { n: "*You said my name*, Hanne said. Her voice was hoarse. *You always say my name. You're the only one.*" },
    { place: 'Paulownia Mall · Chagall Café', time: 'After School', bg: 'chagall-cafe-inside', music: 'eerie' },
    { n: "The owner at Chagall didn't remember Solar. He never did, this year. But he looked at the two of them in the door, soaked, the girl in the school blazer and the woman in the blue coat with her hand held against her chest like something she'd been given to carry, and he put down the cup he was drying and said *sit, sit*, and turned the sign on the door to CLOSED, and put the kettle on, and went into the back to find them towels, and didn't come out again for a long time." },
    { n: "The kettle was on the ring behind the counter. It began, after a while, to hum." },
    { n: "Hanne sat in the corner booth with the case on the seat beside her, against the wall, between her and the window, the way you'd seat a child. She didn't take her coat off. She held the splinted hand in her lap with the other, her left hand, the long thin fingers wrapped round the metal very lightly, and she looked at the table." },
    { n: "*I did it*, she said." },
    { n: "Solar didn't say anything. Her coat was dripping on the floor. She sat across from her and waited the way she'd learned to wait for Hanni, for Yunjin, for Haechan on the stairs: the waiting that's a hand held out flat with nothing in it." },
    { n: "*All of it. The bridge. The red. You. I pulled you first. I'm sorry. I pulled you first because you were the only person who ever said my name, and I thought, if I could just have one person who'd stop for me, just one, I'd build the rest from there. I'd build a whole house from there. A long table. Everyone at it. Nobody on the platform. Nobody going home to a flat with nothing in it.*" },
    { n: "*I play, and it gets wider. It gets wider every time I play. I thought I was making room.*" },
    { n: "She looked up. Her eyes were very clear." },
    { n: "*I saw a hand*, she said. *On the night of the moon. I asked to see it and I saw it. It wasn't a hand.*" },
    { s: 'solar', f: 'serious', t: "Whose hand." },
    { n: "Hanne opened her mouth." },
    { n: "*It was*, she said; and *O*—" },
    { n: "There was a sound like a pencil snapping." },
    { n: "Small. Dry. Very clear, in the quiet café with the rain on the windows and the kettle humming on the ring. Solar didn't understand it at first. She looked at the table, for the pencil. Then she looked at Hanne's left hand, lying on the table between them, the long fingers spread a little on the wood; and at the little finger of it, which was lying at an angle to the others that a finger can't lie at, bent sideways at the middle joint, outward, the way you'd bend a twig to see if it was green." },
    { n: "Hanne didn't scream. Her whole body went rigid, and her mouth stayed open, and a sound came out of her throat that was barely a sound, a long thin breath like air going out of something, and her eyes filled and spilled over and she didn't close them." },
    { n: "Solar was already round the table. She didn't remember getting up. She was on the seat beside her with her arm round her shoulders, the wet blue wool, the case pushed into the corner, saying *don't, don't, stop, you don't have to, stop*—" },
    { n: "*I have to*, Hanne said, through her teeth. *Somebody has to. Nobody else has seen it. Listen. Listen to me. It was*—" },
    { n: "The ring finger went." },
    { n: "Solar saw it. That was worse. She was looking straight at the hand and she saw it go, by itself, with nothing touching it, as if an invisible thumb and forefinger had taken it at the knuckle and turned it, slowly, patiently, the way you'd turn a key: the skin over the joint going white, then stretching, then the sound, *snap*, and the finger lying back against the knuckles of the hand with its tip pointing at Hanne's wrist." },
    { n: "Hanne's head went back against the booth. She made the sound again. Longer. Her right hand, in its splint, was in Solar's lap; Solar didn't know when she'd taken it. She was holding it. Very lightly, round the metal, the way you'd hold a bird." },
    { n: "Behind the counter the kettle was humming. Steadily. A tune. Three up, two down, a long one." },
    { n: "Nobody had touched it. It wasn't boiling. It was humming." },
    { n: "*It's listening*, Hanne whispered. *It always listens. It likes it when I try. It hums along.*" },
    { s: 'solar', f: 'sad', t: "Then don't. Please. Hanne. I don't need the name. I don't need it." },
    { n: "*You do*, Hanne said. *You do. You're the one who needs it most. Oh*—" },
    { n: "She tried once more. Solar would think, later, that she'd known exactly what would happen and had tried anyway, the way you'd put your hand on a stove to prove to somebody else that it was hot. She drew a breath and her lips made the shape of the first sound, the same round sound, and held it—" },
    { n: "—and the middle finger went, and that one was loud, louder than the others, a crack like a branch in frost, and Hanne's whole left arm jerked off the table with it, and her forehead came down on Solar's shoulder, and she stayed there, shaking, with her breath going in and out of her in long ragged pulls, and Solar held her right hand in its splint in both of hers and held on." },
    // CG: eqx-pencil — a rainy café window at dusk, two women in a corner booth seen from across the empty room, one in a school blazer holding the splinted hand of the other in a blue coat buttoned to the throat, a black instrument case in the corner of the seat.
    { n: "When the kettle stopped humming, it stopped all at once. The room was very quiet. The rain went on." },
    { n: "Hanne lifted her head after a long time. Her face was gray and wet. She looked at her left hand on the table, at the three fingers bent back, the thumb and the first finger still straight. Then at her right in Solar's hands, splinted, the thumb and the first finger free of the metal." },
    { n: "*Four*, she said. *I've got four left. Two and two.*" },
    { n: "She laughed. It was a terrible sound. *It's enough to hold a bow. It's enough to stop a string. It knows that. It's very careful. It's not finished with me.*" },
    { n: "*I can't tell you. I can't tell anybody. But I can play. I can play it steady instead of wide. I can hold it. I can hold the bridge still so it doesn't get longer. I'll do that. I'll do that every night. With four.*" },
    { n: "She looked at Solar. *Don't let them come looking for me. Your people. The one with the red hair, the one with the board. If they come looking, it'll know they know about me, and it'll want to know what I've told them, and it'll ask.*" },
    { choose: [
      { t: "I won't tell them where you are. I promise.", flag: 'eqx-hanne-promised', then: [
        { n: "*Thank you*, Hanne said. She closed her eyes. *Thank you. Nobody's ever promised me anything.*" },
        { n: "Solar held on to her right hand and thought about the board in the lounge, the word in red marker, and the name under it with a question mark, and what she was going to say to Mitsuru instead, and how badly she was going to say it." }
      ] },
      { t: "I'm going to tell Mitsuru you're alive. Not where. Just that.", flag: 'eqx-hanne-reported', then: [
        { n: "Hanne looked at her for a long time. Then she nodded, once." },
        { n: "*Just that*, she said. *That I'm alive. That's all right. It knows I'm alive. It's the only one who's ever been sure of it.*" }
      ] }
    ] },
    { n: "She went before the owner came back with the towels. Solar never saw her go. She looked down at the hand in her lap, the splint, the cold metal, and it was her own two hands, empty, holding each other; and the booth beside her was empty, and the case was gone from the corner, and on the seat where Hanne had sat there was a damp shape on the vinyl and three long blue threads." },
    { flag: 'eqx-hanne-fingers' },
    { place: 'Paulownia Mall · Fountain', time: 'Evening', bg: 'paulownia-atrium-evening', music: 'night', soft: true },
    { n: "Akihiko found her by the fountain at seven. She'd texted him one word and he'd run from the pier, in the rain, in his training shirt, and he stood in front of her dripping and breathing hard and didn't ask anything." },
    { n: "She told him. Not where. Just the fingers. Just the sound. Just the kettle." },
    { n: "He listened with his taped hand closed at his side. When she got to the third finger he looked away, out at the rain on the glass roof, and his jaw moved." },
    { n: "Then he unzipped his jacket, and reached inside, to the inner pocket where he kept it, and took out the strip of white tape: the one from the bridge night in June, folded sticky-side in, the one he'd said she could have when he was sure." },
    { s: 'akihiko', f: 'neutral', t: "The night the hour jumped seventeen seconds. On the bridge. When she was playing. I wrote it before I knew anything. Before I knew who she was or what she was doing. I didn't know why I wrote it. I just heard it and wrote it down." },
    { s: 'akihiko', f: 'sad', t: "I'm sure now." },
    { n: "He put it in her hand. She unfolded it. The tape had gone gray at the edges from his jacket, and the marker had faded, and the letters were in his handwriting, square, pressed hard, the handwriting from the strips on the stopwatch." },
    { n: "*HELP*" },
    { s: 'akihiko', f: 'sad', t: "That's what it sounded like. The whole time she played. It didn't sound like a song. It sounded like somebody asking for that." },
    { flag: 'eqx-aki-word' },
    { n: "Solar folded the tape back up along its old creases, carefully, and put it in her blazer pocket over her heart, and Akihiko watched her do it and didn't say anything, and they stood by the fountain in the rain with the water going up and coming down and the mall shutting around them, light by light." }
  ] },

  { id: 'eqx-timetables', date: '10/2', slot: 'after', consumes: true, title: 'every station on the line', place: 'The Oka Boarding House · Front Room', time: 'Daytime',
    cast: { solar: 'Solar', jungwon: 'Jungwon', 'kim-dad': 'Mr. Kim', mrsoka: 'Mrs. Oka' },
    scene: [
    { bg: 'eqx-oka-kitchen', music: 'tender' },
    // BG: oka-front-room-day — the front room of an old Japanese house on a bright autumn afternoon, the paper screens open onto a garden with an orange-laden persimmon tree and a stone-capped well, a low table covered in train timetables and a map.
    { n: "Jungwon had brought the timetables in a plastic folder, labelled, because of course he had." },
    { n: "There were eleven of them. The Port Island line, the Iwatodai line, the two bus routes that ran along the river, the monorail, the ferry, and five more that went out of town in five directions, to places Solar had never heard anybody in this year say out loud. He'd got them from the station office on Thursday after school. He'd stood at the window for twenty minutes, the clerk told Haechan later, asking for them one at a time in very formal Japanese, bowing after each one." },
    { n: "Mr. Kim had asked him to." },
    { n: "They were spread out on the low table in the front room now with the screens open onto the garden, a Saturday afternoon, the light coming in long and gold and full of floating dust, and Mr. Kim was sitting cross-legged in front of them in his fleece with his reading glasses on the end of his nose and a pencil in his hand, and Jungwon was kneeling beside him, upright, with his own pencil, translating." },
    { s: 'jungwon', f: 'neutral', t: "This one is the express. It doesn't stop at the small stations. Here, and here, it goes straight through. If you want the small stations you take the local. The local is the one with the green line." },
    { s: 'kim-dad', f: 'neutral', t: "The green line. Local. Small stations. Right." },
    { n: "He wrote it in the margin. In Korean. *Green = slow = all the little ones.* He underlined *all*." },
    { n: "Solar sat at the end of the table with her knees up and watched them. She'd come because Jungwon had texted *I'm at the boarding house with Mr. Kim, if you want to come, you don't have to come*, which in Jungwon was the same as a person standing in the road waving both arms." },
    { n: "Mr. Kim was making a plan. She'd understood that in the first ten minutes. He was going to go to every station. Every station on every line in the folder, one a day, starting at the nearest and working out, and at every one of them he was going to get off the train and walk to the exit and stand there, and look, and wait for one train in each direction, and then get back on." },
    { s: 'kim-dad', f: 'neutral', t: "She's gone ahead. I told you. On the bridge. She always does that. Twenty years, she always goes ahead. Mall, airport, your grandmother's funeral. I'm parking the car and she's already gone ahead. And then she waits for me somewhere and gets annoyed I took so long. Somewhere obvious. She always picks somewhere obvious. The exit. Under the clock." },
    { s: 'kim-dad', f: 'neutral', t: "So I check the exits. Under the clocks. Every station. She'll be annoyed. She'll say what took you so long. I'll say there are a hundred and twelve stations in this prefecture, yeobo, you could have picked a smaller country." },
    { n: "He laughed. Jungwon didn't. Jungwon looked down at the timetable and drew a careful box round a station name and wrote the number of minutes beside it, small, neat, as if the number of minutes were the most important thing in the world, as if it would hold if he got it exactly right." },
    { n: "Mr. Kim had the car keys in his left hand. He'd had them in his left hand all afternoon. The keys Mrs. Kim had been holding in her fist on the night of the long table, when she'd come through the dark looking for her daughter with her handbag over her arm and her keys out, ready to drive. He turned them over and over without looking at them, the way you'd worry a stone in your pocket." },
    { s: 'kim-dad', f: 'neutral', t: "She'll want these. She hates it when I drive her car. She moves the seat back the second she gets in. Every time. Like I've done something to it." },
    { n: "Solar looked out of the open screens at the garden so she wouldn't have to look at his face, and that was how she saw it." },
    { n: "There was washing on the line in the garden. Mrs. Oka's line, strung between the persimmon tree and a post by the wall, past the well with its heavy cap. Sheets. Pillowcases. White, all of it, white, moving a little in the breeze off the river, the light coming through them gold." },
    { n: "A woman was taking it in." },
    { n: "Her back was to the house. She was reaching up to the line with a peg in her teeth. Short. Brisk. Quick, impatient hands, pulling the sheets off the line in one long yank each and folding them against her chest in the air without letting them touch the ground, the way you fold sheets when you've done it ten thousand times and resent every one. Black hair cut blunt at the shoulder. A navy quilted vest over a gray sweater; and over the vest an apron, white; and the apron's strings tied in a hard double knot at the small of her back, the way you tie something you never want to have to untie." },
    { n: "The knot sat on a line. Straight down the back of the vest. A seam. Open a finger's width." },
    { n: "She took the peg out of her teeth and shook her head at the sheet, irritated, and said something to it under her breath, and Solar knew the shape of that sentence without hearing a word. She'd heard it from the top of the stairs in a house on a hill in a different country every Saturday of her life. *Who washes a sheet like this. Who taught you to wash a sheet.*" },
    { n: "At the low table, with his back to the garden, Mr. Kim drew a circle round a station and said *this one has a clock, I can see it on the map, they put a little clock on the map*." },
    { n: "Solar didn't breathe. She sat with her knees up and her arms round them and watched the woman in the garden fold the last sheet against her chest, and turn round with the basket on her hip—" },
    { n: "—and it was Mrs. Oka, small, gray, gloved, in her kimono with the sleeves tied back, coming up the garden path toward the open screens with a basket of washing, smiling at the three of them." },
    { s: 'mrsoka', f: 'happy', t: "Look at you, all of you, so busy. Making plans. Isn't that nice. Isn't it nice to have a plan, Mr. Kim." },
    { s: 'kim-dad', f: 'happy', t: "Every station! I'm going to check every station." },
    { s: 'mrsoka', f: 'neutral', t: "Every one. Good. You'll come back here every night, though, won't you. After. You'll come back and tell me where you've been. I'll keep your supper warm." },
    { s: 'kim-dad', f: 'neutral', t: "Of course, of course." },
    { n: "She went past them into the house with the basket, and the smell of the washing went past with her, clean, sun-dried, and under it, very faintly, at the back, something sweet." },
    { n: "Jungwon's pencil had stopped. He was looking down at the timetable. He hadn't looked up the whole time; Solar had watched him not look up. His knuckles on the pencil were white." },
    { n: "He'd been facing the garden too. Across the table from her. The whole time." },
    { n: "He didn't say anything. He drew a very small, very neat box round the next station on the green line, and wrote the number of minutes, and then, under the table, where Mr. Kim couldn't see, he put out his left hand without looking and found her ankle, and held it, hard, the way you'd hold the rail of a boat." },
    { place: 'Iwatodai · River Street', time: 'Evening', bg: 'outside-daytime-neighborhood', music: 'badfeeling', soft: true },
    { n: "On the walk back he told her. Not much. He stopped at the corner by the post office where Koromaru always stopped and said it to the wall in front of him, in Korean, very quietly, as if he were reporting a minute to a meeting nobody had called." },
    { s: 'jungwon', f: 'serious', t: "I saw her. Mrs. Kim. In the garden. I know how she folds sheets. I've seen her fold sheets. I've— I've been in that house on a Saturday morning, in one of my lives, and seen her fold sheets and be angry at them." },
    { s: 'jungwon', f: 'serious', t: "And there was something wrong with her back." },
    { s: 'solar', f: 'neutral', t: "...Yeah." },
    { s: 'jungwon', f: 'neutral', t: "You've seen it before. You've seen it before today. Your face didn't do anything. Your face only does nothing when you've seen it before." },
    { n: "She told him about the bridge. Solji, under the last lamp, turning back. About Tuesday at the long table. The tortoiseshell clip. The cream thread on the shelf. He listened standing completely still at the corner with his blazer buttoned and his hands at his sides, and when she'd finished he didn't say anything for a while." },
    { s: 'jungwon', f: 'neutral', t: "...He's going to check every station. Every exit. Every clock. A hundred and twelve stations." },
    { s: 'jungwon', f: 'sad', t: "She's in the garden. She's in the garden, Solar, taking in the washing, and he's sitting with his back to her drawing boxes round clocks." },
    { n: "He took his watch off. The one that had stopped at the Lee house gate in June and that he'd put face down. He looked at it. It was running. He put it in his pocket." },
    { s: 'jungwon', f: 'neutral', t: "I'm going to keep translating the timetables. All eleven. I'm going to do every one properly. I'm not going to tell him." },
    { s: 'jungwon', f: 'sad', t: "Tell me that's right. You don't have to. I just want somebody to have said it." }
  ] },

  { id: 'eqx-seventh-stair', date: '10/6', slot: 'late', consumes: true, title: 'the seventh stair', place: 'The Oka Boarding House · Stairs', time: 'Late Night',
    cast: { solar: 'Solar', haechan: 'Haechan', 'taesang-strangers': 'Taejoon' },
    scene: [
    { bg: 'epi-s-stairs-night', music: 'night' },
    // BG: oka-stairs-night — a steep, narrow wooden staircase in an old Japanese house at night, lit from a single lamp in the hall below, a landing with a small high window, a man sitting halfway up with his back to the hall.
    { n: "Haechan texted her at eleven. *come to the boarding house. bring a sweater. it's not a question but you can say no.*" },
    { n: "She brought two." },
    { n: "The boarding house stairs were steep and narrow and old, the kind of stairs you went up with one hand on the wall, and they creaked; every one of them creaked, but the seventh from the bottom creaked louder than the others, a long low note like a cello, and Taejoon was sitting on it." },
    { n: "He'd been sitting on it every night since the bridge. Jaehyun had told Haechan; Haechan had told her. From about eleven until the hour came. With his back to the hall and his face to the landing and his forearms on his knees, the way he sat at the bottom of the stairs in a house on a hill above a harbor in another life, waiting for a door, saying nothing very loudly." },
    { n: "Haechan was sitting on the stair below him. The sixth. With his shoulder against Taejoon's knee." },
    { n: "Neither of them looked round when she came up. Haechan only reached back without looking and took the second sweater out of her hand and put it over Taejoon's shoulders, and Taejoon let him, and didn't say anything." },
    { n: "Solar went past them, carefully, close to the wall, up to the landing, and sat down at the top with her back against the wall under the little high window, where she could see both of them below her, the tops of their heads, and the lamp in the hall at the bottom of the stairs, and, through the open transom over the kitchen door at the end of the hall, a slant of the kitchen ceiling, lit." },
    { n: "For a long time nobody said anything. The house ticked. The river went by outside. Somewhere upstairs, behind one of the eight doors, one of the girls was laughing quietly on the phone, a long way away, in English." },
    { s: 'taesang-strangers', f: 'neutral', t: "...Sol-ah." },
    { s: 'solar', f: 'neutral', t: "Yes, Appa." },
    { s: 'taesang-strangers', f: 'neutral', t: "Did you eat." },
    { s: 'solar', f: 'neutral', t: "I ate." },
    { n: "He nodded. That was the whole conversation for another ten minutes." },
    { n: "Then Haechan said something to him in Korean. Low, the strangers Korean, the one with the harbor in it, the one he never used in front of anybody but her and this man. Solar didn't hear what. Taejoon's hand came down off his knee and settled on the top of Haechan's head, heavy, the way it settled on hers at the bottom of the stairs when she came home late, and stayed there." },
    { s: 'taesang-strangers', f: 'neutral', t: "...She used to sit here. Not here. You know. The other house. On the landing. When I sat at the bottom. She'd sit at the top and I'd sit at the bottom and we'd wait for you to come home and neither of us would say we were waiting." },
    { s: 'taesang-strangers', f: 'neutral', t: "Thirty years. She sat at the top of every staircase I ever sat at the bottom of." },
    { n: "He didn't look up at the landing. At Solar, sitting where Miseon sat. He looked at the wall." },
    { n: "Solar looked at the transom." },
    { n: "She hadn't meant to. Her eyes went there the way your eyes go to movement at the edge of a room. Through the narrow glass panel over the kitchen door, at the end of the hall below, from up here, at this angle, she could see a slice of the kitchen: the ceiling, the top of the shelf over the stove, the upper half of the window, black. And a woman's head and shoulders, moving across it. Slowly. Back and forth. At the sink." },
    { n: "Long hair. Not up. Down her back, black and straight, the way Solar had never once seen it; Miseon wore her hair up, always, in a knot, low, at the nape, every day, perfectly, so that you never thought about it at all. A house cardigan. The gray one, the one with the darned elbow. Over it, an apron's straps crossing at the shoulder blades." },
    { n: "Where they crossed, the cardigan was open. A finger's width. Down the middle." },
    { n: "The woman at the sink lifted her left hand out of the water and turned the ring on her finger, once, all the way round, the way Miseon turned it when the house went quiet at night and the kettle was on. Solar had watched her do it a thousand times across the kitchen in the morning, the ring catching the window. Once, round. Then the hand back into the water." },
    { n: "Below Solar, on the seventh stair, with his back to the hall and his eyes on the wall, Taejoon breathed out." },
    { n: "Haechan's head came up." },
    { n: "Not to the kitchen. To Solar. He'd felt her go still from two stairs down; she'd felt him feel it. He looked up at her face on the landing, and saw where her eyes were, and didn't turn his head to follow them. He held very, very still, with Taejoon's hand on his head." },
    { n: "Then he looked back down, at his own hands, and said something to Taejoon in Korean about the weather tomorrow, the forecast, rain in the afternoon, and Taejoon said *mm*, and the woman at the sink took her hands out of the water and dried them on her apron and walked out of the slice of glass, and the kitchen light went off." },
    // CG: eqx-seventh-stair — looking down a steep narrow staircase in an old house at night from the landing, a broad-shouldered man in shirtsleeves with a sweater round his shoulders sitting halfway up with one hand resting on the head of a young man sitting a step below him, a lamp in the hall below.
    { n: "Nobody came out of the kitchen. Solar listened for the door. It didn't open. The hall stayed empty. The lamp burned. After a while, from somewhere behind the house, toward the garden, toward the well, there was a sound like a heavy stone being moved, a long grinding scrape, once, and then nothing." },
    { n: "Taejoon didn't move. He didn't turn his head." },
    { s: 'taesang-strangers', f: 'neutral', t: "...Go home, both of you. The hour's coming. You'll be in the street when it comes." },
    { s: 'haechan', f: 'neutral', t: "We'll go when you go to bed, Abeonim." },
    { s: 'taesang-strangers', f: 'neutral', t: "I'm not going to bed." },
    { s: 'haechan', f: 'neutral', t: "Then we're not going home. That's how this works. You taught me that. That's literally the only thing you ever taught me on purpose." },
    { n: "Taejoon looked down at him. Then, for the first time that night, up at the landing, at Solar, where his wife used to sit." },
    { n: "Something happened in his face that Solar had never seen happen in it in either life. It didn't break. It didn't move. It just, for a second, let her see that it was holding still on purpose." },
    { s: 'taesang-strangers', f: 'neutral', t: "...Five more minutes. Then I'll go up." },
    { n: "They sat for forty. When he got up, finally, at five to twelve, he put his hand on the seventh stair as he stood, flat, the way you'd put your hand on the head of a dog that had kept watch, and the stair creaked its long low note under it, and he went up past Solar on the landing without a word and touched the top of her head on his way, once, and his door shut." },
    { n: "Haechan came up and sat on the landing beside her, against her side, the length of her, and she put the sweater she was still holding over both their knees." },
    { s: 'haechan', f: 'neutral', t: "...You saw something." },
    { s: 'solar', f: 'neutral', t: "In the kitchen." },
    { s: 'haechan', f: 'neutral', t: "Was it her." },
    { s: 'solar', f: 'sad', t: "It was her hair. It was her ring. It was her doing the ring." },
    { n: "He didn't say anything for a long time. Then he put his forehead against her temple, hard, and kept it there." },
    { s: 'haechan', f: 'sad', t: "Okay. Okay. We don't tell him. Not yet. Not like this. Not when there's nothing he can do with it but sit on a stair." },
    { s: 'haechan', f: 'sad', t: "We find her first. Then we tell him. We find her and then we tell him and then he never has to know about tonight. That's the only order I can stand." },
    { n: "The hour came at midnight. The lamp in the hall went red. In the room at the end of the landing, behind his door, Taejoon's coffin stood upright facing the window, and the window faced the garden, and the garden faced the well." }
  ] },

  { id: 'eqx-lease', date: '10/9', slot: 'after', consumes: true, title: 'the same hand', place: 'Iwatodai Dorm · Command Room', time: 'Daytime',
    cast: { solar: 'Solar', mitsuru: 'Mitsuru', aigis: 'Aigis', akihiko: 'Akihiko', fuuka: 'Fuuka' },
    scene: [
    { bg: 'iwatodaidorm-commandroom', music: 'mystery' },
    { n: "Mitsuru had two pieces of paper on the command room table, side by side, under the desk lamp, with a ruler laid across them both." },
    { n: "One was the lease for the Oka boarding house. Solar had never seen it, only heard about it: the Kirijo seal at the bottom, genuine; the three offices that had found nobody who'd drafted it; the signature on the landlord's line that nobody could read. The other was a photocopy of Solar's enrollment form from April. The one with her name on it in a hand nobody at the school recognised. The one with the empty surname box." },
    { n: "Mitsuru didn't say anything when Solar came in. She moved the lamp a little, so the light fell flat across both of them, and stood back." },
    { n: "It wasn't a matter of looking closely. That was the thing. Solar had expected to have to look closely. She'd expected a loop here, a slant there, something you'd need an expert for. She looked at the two pages under the lamp from the doorway and felt the hair on her arms stand up all at once, the way it did at the top of the Well." },
    { n: "The same hand. Heavy. Pressed so hard the paper had dented, so that you could see the shadow of every stroke under the lamp. The long hooked line at the end of every signature that went back on itself, like something that had started to leave and changed its mind. The same hand that had written *stay* on the back of every Tanabata strip in the shrine. The same hand in the margin of her page in the Velvet Room. The same hand on Mr. Hata's sign-in book, the one letter, O." },
    { s: 'mitsuru', f: 'serious', t: "I should have done this in April." },
    { s: 'solar', f: 'neutral', t: "You didn't have my form in April." },
    { s: 'mitsuru', f: 'serious', t: "I had the lease. I had the lease on my desk on the ninth of April and I had your name in that hand in front of me every morning at breakfast. I didn't put them side by side because I didn't want to. Because the boarding house was a solution and I liked having a solution." },
    { n: "She said it without any expression at all. The way she'd said three men's names and ages on the bridge." },
    { s: 'mitsuru', f: 'serious', t: "Whoever signed your form signed her lease. Whoever wanted you here wanted that house to have people in it. Wanted the overflow to go there. Wanted the girls to go there. Wanted the parents to go there." },
    { s: 'mitsuru', f: 'sad', t: "I sent the parents there. I phoned her myself, in August. I asked if she had room." },
    { n: "Aigis was standing by the window with her hands folded. She'd been very quiet since the bridge. She'd been very quiet in a particular way, Solar had noticed, the way a person is quiet when they're running the same sum again and again and getting the same wrong answer." },
    { s: 'aigis', f: 'neutral', t: "I took her reading on the twenty-fourth. On the bridge. At dawn. I told you. There was nothing. Not her heart, not anyone's. Everything was like the bridge." },
    { s: 'aigis', f: 'neutral', t: "I have taken it four more times since. At her gate. Through her window. At the shrine. In the shop by the station where she buys her rice." },
    { s: 'mitsuru', f: 'serious', t: "And?" },
    { s: 'aigis', f: 'sad', t: "Seventy-two. Seventy. Sixty-eight. Seventy-one. A small woman in her fifties, a little tired, a little sad. Exactly what she looks like." },
    { s: 'aigis', f: 'neutral', t: "It is exactly what she looks like every time. To the beat. I have never taken a reading of a living person that was exactly what they looked like every time. People are never exactly what they look like. Their hearts are always doing something their faces aren't." },
    { s: 'aigis', f: 'serious', t: "Hers is always doing exactly what her face is doing. As if somebody had read what a small sad woman's heart should do, and was doing it." },
    { n: "Nobody said anything. On the monitor behind Fuuka's chair, the green line of the town's map glowed; Fuuka had her headset round her neck and her hands flat on her knees." },
    { s: 'fuuka', f: 'sad', t: "...I've never been able to hear that house. Not once. Chenle can't either. It's the only quiet place in town. It's quiet like the bridge was. Like somebody's hand over your mouth." },
    { s: 'akihiko', f: 'serious', t: "Then we go in. Tonight. We go in and we look." },
    { s: 'mitsuru', f: 'serious', t: "And find what? A kitchen. A tin of rice cakes. Eight made-up rooms and four girls who think she's the kindest woman in Japan and three men who haven't slept since the equinox, who she's feeding by hand, who would die before they let us frighten her." },
    { s: 'mitsuru', f: 'serious', t: "I have a lease and a signature. I have a heart rate that's too correct. I have flour. Everyone in this town has flour, Akihiko. I can't put a widow who runs a boarding house on that board on a lease and a forty." },
    { n: "She looked at the whiteboard. At the word. At the names under it: three men with their ages beside them, three women with nothing beside them, and, if Solar had told her, one more with a question mark." },
    { s: 'mitsuru', f: 'sad', t: "...Not yet." },
    { n: "She picked up the red marker anyway. She uncapped it. She stood in front of the board with it for a long time, the cap in her other hand, and Solar watched her decide, and not decide, and decide; and in the end she didn't write anything under HUNTING. She went to the corner of the board instead, the bottom right corner, where she'd written *Cups (16)* in July, and under it, small, she wrote a date." },
    { n: "*4/9*" },
    { n: "The day the lease had been signed. The day the Group had found a boarding house for the overflow. The day Mrs. Oka had stood at her gate and waited to be asked in." },
    { s: 'mitsuru', f: 'neutral', t: "Aigis. You have my exception. Any reading, any time, any house, cause or no cause. Bring them all to me first." },
    { s: 'mitsuru', f: 'neutral', t: "Solar. When you're at that table. Watch her hands." },
    { s: 'solar', f: 'neutral', t: "I always watch her hands." },
    { s: 'mitsuru', f: 'sad', t: "I know you do. I'm asking you to watch them for me as well. I can't go there anymore. I'm afraid I'd ask her to take her gloves off." },
    { flag: 'eqx-lease-hand' },
    { n: "On the table under the lamp, the two papers lay side by side, and the long hooked lines at the end of the two signatures pointed at each other across the ruler like two hands reaching, and Mitsuru put the lease back in its folder, and the folder in her drawer, and locked it, and held the key in her fist a moment, and then put it on the cord round her neck, under her collar, against her skin." }
  ] },

  { id: 'eqx-fathers-go', date: '10/22', slot: 'late', consumes: true, title: 'with no Personas', place: 'Iwatodai Dorm · Lounge', time: 'Late Night',
    cast: { solar: 'Solar', mitsuru: 'Mitsuru', chenle: 'Chenle', fuuka: 'Fuuka', 'jaesang-runners': 'Jaesang', 'taesang-strangers': 'Taejoon', 'kim-dad': 'Mr. Kim',
      jaehyun: 'Jaehyun', shinjiro: 'Shinjiro', akihiko: 'Akihiko' },
    scene: [
    { bg: 'iwatodaidorm-livingroom-night-autumn', music: 'tension' },
    { n: "Chenle heard them first. On Wednesday, in the Well, on the last floor of the Third Hill, where the halls in static stopped at a wall of white light that wouldn't open until the full moon. He'd been calling shapes for Fuuka, *Bowl, Tube, left, left*, and then he'd stopped in the middle of a word and taken his headset off and held it out away from his head, at arm's length, as if it had bitten him." },
    { n: "Three women's voices. Far down. Under the floor of the Well, under the barrier, under the static. Telling a story." },
    { n: "That was what he told them in the lounge on Friday night, with the whole household there, the fathers on the couch, Jaehyun on the arm of it beside his. He told it in English and then in Korean and then, when he got to the end, in neither; he just stopped, and sat with his hands between his knees." },
    { s: 'chenle', f: 'sad', t: "It was the sun-and-moon one. The one with the tiger. I know it, my grandma told it, everybody's grandma told it. They were telling it together. Taking turns. A sentence each. And the voices were wrong." },
    { s: 'fuuka', f: 'sad', t: "Wrong how, Chenle-kun." },
    { s: 'chenle', f: 'sad', t: "They were swapped. Each one was using somebody else's. Like— like when you can't find your own coat at a party so you put on somebody's. The one with the English accent was talking in the Seoul one's voice. The Seoul one was doing the quiet one's voice, the low one. The low one was doing the English. And they kept going. They kept telling it. Like if they stopped telling it something would happen." },
    { n: "Nobody said anything. On the couch Mr. Kim had the car keys in his hand. He'd gone to twenty-six stations. Jungwon had told Solar the number; Jungwon kept the list. Twenty-six exits, twenty-six clocks, twenty-six times waiting for one train each way, and coming back to the boarding house every night to tell Mrs. Oka where he'd been while she kept his supper warm." },
    { n: "Taejoon stood up." },
    { n: "He didn't say anything. He walked to the front hall, where Koromaru was lying across the door the way he lay every night now, and Koromaru lifted his head and looked at him, and Taejoon looked down at the dog and the dog put his head back down; and Taejoon sat down on the step in the genkan and began to put his shoes on." },
    { s: 'mitsuru', f: 'serious', t: "Mr. Lee." },
    { n: "He tied the left one. Double knot." },
    { s: 'mitsuru', f: 'serious', t: "Mr. Lee, the Well is closed below the Third Hill until the full moon. Tomorrow night, when it opens, my people will go down. People who can defend themselves. You can't. None of you can. I'm sorry. I won't have you down there." },
    { n: "He tied the right one. Double knot. Then he sat on the step with his forearms on his knees and his back to the room and waited, the way he waited at the bottom of stairs, with the door in front of him." },
    { n: "Jaesang got up off the couch and went and sat on the step beside him and began to put on his own shoes. They were the black Italian ones from the bridge; he'd cleaned them every night since. Jaehyun said *Dad* in a voice like he'd been hit and Jaesang didn't look round." },
    { s: 'jaesang-runners', f: 'neutral', t: "I've been told no by people with considerably more to lose than you, Miss Kirijo. In rooms with much better lighting. I've never been very good at it." },
    { s: 'kim-dad', f: 'neutral', t: "Twenty-six stations. She wasn't at any of them. I looked under every clock." },
    { n: "Mr. Kim was standing by the couch. He'd put the car keys in his pocket and taken them out again. His voice was very reasonable." },
    { s: 'kim-dad', f: 'neutral', t: "She's not ahead. I've been wrong. She's not gone ahead. She's underneath. She's been underneath this whole time, telling a story in the wrong voice, and I've been checking exits." },
    { s: 'kim-dad', f: 'sad', t: "I'm not checking any more exits." },
    { n: "He went to the step. There wasn't room for three. He sat on the floor of the hall beside it, in his fleece, with his legs out, and started to put on his sneakers." },
    { n: "Mitsuru looked at Solar." },
    { n: "Everybody looked at Solar. That was the thing that happened, that she'd remember. Not Mitsuru alone. The whole room, at once, without meaning to: Akihiko from the window, Jaehyun from the arm of the couch with his face gone white, Shinjiro from the kitchen doorway with a dish towel over his shoulder; all of them turning to her, the way a room turns to the one person a man might listen to." },
    { n: "Three fathers on the front step putting their shoes on. Her fathers. All of them." },
    { choose: [
      { t: "Stay here. Please. All three of you. I'll bring them back. Please, Dad.", tally: { asked: 1, cakes: 1, 'asks.solar.fathers': 'yes' }, flag: 'eqx-asked-fathers', then: [
        { n: "It came out of her before she knew it was in her mouth. *Please.* She heard her own voice crack on it like a girl's." },
        { n: "Jaesang stopped with his hand on his shoelace. Mr. Kim looked up from the floor. Taejoon's back went very still." },
        { n: "For one long moment, she thought it had worked. She felt it work. Felt the three of them, at the door, lean back toward her, toward the room, the way a plant leans toward a lamp; felt the yes in them, *if she wants it, if she's asking*; and something in her chest that she didn't have a name for went warm and full and terribly satisfied, like a stomach after a meal." },
        { n: "Then Taejoon stood up, and opened the door, and the night came in." },
        { s: 'taesang-strangers', f: 'neutral', t: "...You've never asked me for anything in your life, Sol-ah. Not once. That's how I know it's not you asking." },
        { n: "He went out onto the step. The other two followed him. Solar stood in the lounge with her own word still in her mouth, tasting of sugar, and Mitsuru put a hand on her shoulder, and didn't say anything, and squeezed once." }
      ] },
      { t: "You can't come. You'll die down there. I'm not letting you.", tally: { 'asks.solar.fathers': 'no' }, then: [
        { n: "She said it hard. She said it the way Mitsuru said things. Jaesang looked round at her over his shoulder with his face perfectly calm and perfectly sad." },
        { s: 'jaesang-runners', f: 'sad', t: "I know you're not, sweetheart. That's not one of the things you get to decide." },
        { n: "Taejoon didn't turn round at all. He opened the door, and the night came in." }
      ] },
      { t: "(Go and sit down on the step with them. Put your own shoes on.)", tally: { choose: 1, 'asks.solar.fathers': 'choose' }, flag: 'eqx-choose-fathers', then: [
        { n: "She didn't say anything. She went to the hall and sat down on the step on Taejoon's other side, squeezed in, and took her shoes off the rack, and began to put them on." },
        { n: "Taejoon looked down at her. Jaesang looked at her over his shoulder. On the floor, Mr. Kim made a sound that might have been a laugh." },
        { s: 'solar', f: 'neutral', t: "It's yours. You're going. Fine. Then you walk where I tell you and you don't stop and you don't answer anything that talks to you. Not even if it's her. Especially if it's her." },
        { n: "It cost something to say. She could feel exactly what. Under her ribs, in the place where she kept the small warm things, the little hard shape of *please* that she'd swallowed instead of saying, sitting there, undigested, aching." },
        { s: 'taesang-strangers', f: 'neutral', t: "...Mm." },
        { s: 'jaesang-runners', f: 'neutral', t: "Understood." },
        { s: 'kim-dad', f: 'neutral', t: "Don't answer anything, even her. Yes. Fine. She'll be so annoyed." }
      ] }
    ] },
    { s: 'mitsuru', f: 'serious', t: "...Tomorrow night. Not tonight. Tomorrow, when the barrier's open, you'll go down with us. In the middle. Escorted. You'll do exactly what you're told, you won't stop for anything, and you won't answer anything that speaks to you. If you can't promise me that you'll stay here if I have to have you sedated." },
    { s: 'jaesang-runners', f: 'neutral', t: "Agreed." },
    { n: "Taejoon nodded at the door. Mr. Kim said *agreed, agreed*. Jaehyun got up off the arm of the couch, very slowly, and went and stood in the hall behind his father with his hand on the back of his father's collar, the way you'd hold a dog that might bolt." },
    { s: 'jaehyun', f: 'serious', t: "I'm going too. Don't. Don't even. I'm not asking." },
    { place: 'Iwatodai Dorm · Kitchen', time: 'Late Night', bg: 'iwatodaidorm-kitchen-night', music: 'night', soft: true },
    { n: "Shinjiro cooked at one in the morning. Nobody had asked him to. He made rice, and miso, and a rolled omelet with the pan in his right hand, his bad one, the one that had dropped forty cups and forty eggs since April, and didn't drop this one; and he put it all out on the counter in a row of bowls, nine bowls, and stood back with his arms folded." },
    { s: 'shinjiro', f: 'neutral', t: "Eat. All of you. The dads too. You go down tomorrow on an empty stomach you'll fall over." },
    { n: "Mr. Kim ate. Jaesang ate, which made Jaehyun put his face in his hands. Taejoon ate a bowl of rice standing up at the counter, the way you'd eat on a boat." },
    { n: "Akihiko came and stood beside Shinjiro by the stove. He didn't eat. He looked at the pan in Shinjiro's right hand." },
    { s: 'akihiko', f: 'neutral', t: "...You held it." },
    { s: 'shinjiro', f: 'neutral', t: "Yeah. Don't make it a thing." },
    { s: 'akihiko', f: 'neutral', t: "I'm walking behind the fathers tomorrow. The back. You walk in front with Ken." },
    { s: 'shinjiro', f: 'neutral', t: "No. I'm in the back. You've got the fists, you're in the front. Back's where the slow guy goes." },
    { s: 'akihiko', f: 'serious', t: "Shinji." },
    { s: 'shinjiro', f: 'neutral', t: "I'm in the back, Aki. Eat something." },
    { n: "He pushed a bowl along the counter at Solar without looking at her. She took it. He watched her lift the chopsticks, and watched the first bite go in, and only then turned back to the stove." },
    { s: 'shinjiro', f: 'neutral', t: "...Good." },
    { flag: 'eqx-fathers-down' }
  ] },

  { id: 'eqx-1023', date: '10/23', slot: 'evening', consumes: true, title: 'the fathers’ hill', place: 'The Well · The Road Home', time: 'The Red Hour',
    cast: { solar: 'Solar', mitsuru: 'Mitsuru', akihiko: 'Akihiko', shinjiro: 'Shinjiro', ken: 'Ken', haechan: 'Haechan', fuuka: 'Fuuka', chenle: 'Chenle', jaehyun: 'Jaehyun',
      'jaesang-runners': 'Jaesang', 'taesang-strangers': 'Taejoon', 'kim-dad': 'Mr. Kim' },
    scene: [
    { place: 'Gekkoukan High · Courtyard', time: 'Late Night', bg: 'eqx-courtyard-well-night', music: 'fullmoon' },
    { n: "The moon came up full over the school a little before eleven, white, enormous, the way it came up every month, as if nothing were wrong with it, and at midnight it went red, and the paving stones of the courtyard went red with it, and the well in the middle of them opened its stone mouth." },
    { n: "Eleven of them went down. Mitsuru counted them at the lip, out loud, touching each person on the shoulder as they passed her onto the rope, the way you'd count children onto a bus." },
    { n: "Solar. Akihiko. Shinjiro. Ken, with Koromaru. Haechan. Mitsuru herself. Jaehyun, in his running jacket, white to the lips. And the three fathers, in borrowed coats from the dorm's hall closet, too big or too small, Mr. Kim in one of Akihiko's training jackets with SANADA on the back, and over each of their shoulders a coil of climbing rope that Mitsuru had tied to her own belt." },
    { s: 'mitsuru', f: 'serious', t: "Akihiko, front. Solar, Ken, with him. The fathers in the middle, on my rope. Jaehyun and Haechan with them. Shinjiro, back." },
    { s: 'fuuka', f: 'neutral', t: "The barrier's open. I can feel it from here. The Third Hill's last floor goes down into... into a road. I can hear wind. And I can hear—" },
    { s: 'chenle', f: 'sad', t: "Them. I can hear them. Still telling it. They're further down." },
    { n: "Eighty-one minutes and forty seconds, Akihiko had said at the lip, looking at the stopwatch. The longest full moon yet. *It's still hungry.* He'd put the stopwatch in his pocket and taped the pocket shut." },
    { place: 'The Well · The Road Home', time: 'The Red Hour', bg: 'eq-well-6', music: 'eerie' },
    { dark: true },
    { n: "The Road Home was a road." },
    { n: "That was what nobody had been ready for. They came down the last stairs of the Third Hill, through the static and the white light at the bottom, and stepped off the stone onto packed earth, and they were outside. Under a sky. A night sky, enormous and starless, with the red moon in it, low, too big; and under the sky, hills. Long dark folded hills going away in every direction to the edge of the world, and over them, winding up and down, a road. A narrow country road of beaten earth, pale in the moonlight, going up over the first hill and down out of sight and up over the next one, and the next, and the next." },
    { n: "There were baskets on the road." },
    { n: "Rice-cake baskets. Round, woven, the kind with a lid, the kind you'd carry on your arm to a festival, set down at the side of the road every hundred meters or so, neatly, as if someone had been carrying them and had put them down one at a time to rest and never picked them up again. Every one of them had its lid off. Every one of them was empty, and dusted white inside." },
    { s: 'kim-dad', f: 'neutral', t: "...She carried a basket like that. On the hills. In the story. The mother. With the rice cakes." },
    { s: 'jaesang-runners', f: 'neutral', t: "Don't." },
    { s: 'kim-dad', f: 'neutral', t: "I'm just saying. That's the story. That's the road in the story." },
    { n: "They walked. Mitsuru's rope between the fathers went taut and slack and taut again. Koromaru walked pressed against Ken's leg with his head low and his hackles up the whole length of his back, and didn't make a sound." },
    { n: "On the second hill there were steps. Stone steps cut into the slope where the road got too steep, going down, worn hollow in the middle by a thousand years of feet, and on the steps there were shoes." },
    { n: "Pairs of them. On every third step, or every fourth. Set neatly side by side at the edge of the stone, toes pointing down the hill, the way you'd leave shoes at a door. Men's shoes, children's, sandals, boots, slippers. Old ones and new ones. Hundreds of them, going down the steps into the dark as far as the red light reached." },
    { n: "Ken stopped. He was looking at a pair of small sneakers. Blue, with a cartoon on the side, the velcro done up." },
    { s: 'ken', f: 'sad', t: "...There are feet in them." },
    { n: "There were. Solar saw it when she looked, and then couldn't stop seeing it, in every pair, all the way down. Feet. Just the feet, and an inch of ankle, cut off clean and bloodless above the shoe and standing there in their shoes on the stone, socks still on some of them, toes curled in some, as if the person they'd belonged to had been lifted straight up out of them in the middle of a step. Feet in sandals with the toenails painted. Feet in work boots, the laces double-knotted. An old woman's feet in white tabi and wooden geta, side by side, very small, very straight." },
    { n: "Jaehyun turned round and was sick on the road. Quietly. With one hand on his father's shoulder so his father wouldn't have to stop." },
    { n: "Then Mr. Kim made a sound." },
    { n: "Halfway down the second flight. He'd stopped dead and the rope had gone taut and Mitsuru had nearly gone over. He was looking at a pair of house slippers on the step. Pink. Terrycloth. One of them with the toe worn through, a white thread hanging off it." },
    { n: "Empty. These ones were empty." },
    { s: 'kim-dad', f: 'surprised', t: "Those are hers. Those are— they're from home. They're from by our door. The pink ones. She's had them six years, I keep buying her new ones and she keeps putting the new ones in the cupboard. That's the hole. That's the hole in the toe. How are they— they're at home. They're by our door at home—" },
    { n: "And further down, on the next step, a pair of rubber garden clogs, green, with dried mud on the heels. Taejoon looked at them and didn't say anything at all, and his hand closed on the rope until the fibers creaked." },
    { n: "And further down, a pair of white running shoes, expensive ones, the laces tucked in, the way you'd leave them by the back door of a house on Seventy-Second Street after an early run in the park." },
    { n: "Jaesang went down past Mitsuru on the rope. He didn't run. He walked, very fast, down three steps, and picked up the left running shoe, and held it, and turned it over, and looked at the sole." },
    { s: 'jaesang-runners', f: 'sad', t: "...Her shoes from home. From our doors. All three. She left them for us." },
    { s: 'mitsuru', f: 'serious', t: "Mr. Lee. Back on the rope. Now." },
    { s: 'fuuka', f: 'surprised', t: "Something's coming up the steps! Three— three signals. Coming up. They're— they're walking. Solar, they're walking up toward you, they're—" },
    { n: "They came up out of the dark at the bottom of the flight." },
    { n: "Clothes. Walking. A cream cardigan, buttoned. A gray house cardigan with a darned elbow. A navy quilted vest over a gray sweater. Each with a white apron tied over it. Coming up the steps one at a time with a slow even tread, filled out, the shape of a woman in each of them, the sleeves swinging. Above the collars, nothing. No heads. The collars open on the dark, and in the dark of each one, very low, something humming." },
    { n: "Behind them, much bigger, coming up the hill on all fours like a cloud of dust coming up a road, something that wanted to be the shape of the hill itself." },
    { s: 'akihiko', f: 'serious', t: "Mitsuru! Get them back up the steps! Ken, Shinji, with me—" },
    { s: 'haechan', f: 'serious', t: "*Dalnim.*" },
    { summon: 'haenim', name: 'Haenim', sub: 'Every hill.' },
    { battle: { id: 'eqx-1023', op: 'eqx-1023', kind: 'operation', title: 'Full Moon · The Fathers’ Hill', desc: 'A night road over endless hills, shoes on the steps going down, and three aprons walking up them with nobody inside and something behind them the size of the hill.', forced: true } },
    { music: 'night' },
    { n: "The clothes came down empty on the steps. The aprons, the cardigans, the vest: they folded down onto the stone like washing off a line, flat, nothing in them, and lay there. The thing behind them went out like dust settling on a road; a long low sigh up the hillside; then nothing but the wind." },
    { n: "Mr. Kim was on his knees on the step beside the navy vest, touching it. Just touching it. Its collar." },
    { s: 'kim-dad', f: 'sad', t: "It's not her. It's not even hers. It's the right one, it's the exact one, but it's not hers, it smells wrong. It smells of sugar." },
    { n: "Ken was holding Koromaru round the neck. Mitsuru was counting again, touching shoulders. Jaehyun had his hand fisted in the back of his father's borrowed coat." },
    { n: "Jaesang had the running shoe in his hand still. He'd held onto it all through the fight. He was standing at the side of the steps, a little below the rest of them, three steps down, holding his wife's running shoe and looking down the flight into the dark." },
    { n: "Somebody was standing at the bottom of it." },
    { n: "At the foot of the steps, where the red light gave out. A woman. Barefoot on the stone. In a cream cardigan, buttoned to the throat. Her hair in a tortoiseshell clip, coming loose at one side. Her face turned up the steps toward them, toward Jaesang; a face Solar knew better than her own, the face she'd looked up at from a car seat, from a hospital bed with her tonsils out, from the bottom of a staircase on the night of her first formal, *oh, honey, look at you*." },
    { n: "Solji smiled." },
    { n: "Her face did it slowly. As if the face were learning it. The mouth going wide, wider, too wide, the skin at the corners of it pulling, and at the jaw, at the hinge of the jaw on the left side, something loose; a fold, a slip, where the face didn't quite sit on what was under it, the way a mask slips when you smile too hard inside it. Her eyes were Solji's eyes. Inside them, behind them, something else was looking out, enormously fond." },
    { n: "She opened her arms." },
    { n: "*Honey*, she said, in Solji's voice, exactly, the little lift at the end of it. *Oh, honey. There you are. You came all this way. Come here. Come down here. It's only me.*" },
    { n: "Jaesang went down a step." },
    { s: 'solar', f: 'surprised', t: "Dad! *Dad*, no—" },
    { n: "He went down another. The running shoe fell out of his hand. Mitsuru's rope round his waist had come off in the fight; it was lying on the step behind him in a coil. Jaehyun lunged and caught air. Solar was moving, they were all moving, too slow, up the steps behind him, like running in water; and Jaesang went down a third step with his arms coming up, open, the way they'd come up at the airport at JFK every single time she'd ever come home to him, and the woman at the bottom of the steps opened hers wider, and wider, the arms of the cardigan stretching past where arms should stop—" },
    { n: "—and somebody went past Solar on the steps. Fast. A long coat. From the back of the line, where the slow guy goes." },
    { ifRank: { shinjiro: 8 }, then: [], else: [{ flag: 'eqx-shinji-falls' }] },
    choiceFlag('asks.shinjiro', 'yes', 'eqx-shinji-falls'),
    { ifFlag: 'eqx-shinji-falls', then: [
      { n: "Shinjiro got between them." },
      { n: "He came down the last two steps in one stride and put himself in front of Jaesang with his back to him, his arms out, the way you'd step in front of a car, and the woman at the bottom of the steps was already there, already closing her arms, and her arms closed round Shinjiro instead." },
      { n: "For a second it looked like a hug." },
      { n: "Then the right hand came up out of the cardigan's sleeve. Not a hand. The thing Hanne had seen, the thing from under the glove, huge, coarse, striped under its dusting of flour, unfolding out of the knit cuff the way a foot comes out of a shoe that was always too small for it, the long curved yellow points sliding out of it. It went to Shinjiro's left shoulder, almost gently. To the hollow under the collarbone. And it went in." },
      { n: "And down." },
      { n: "One stroke. Unhurried. The way you'd draw a knife down the seam of a sack. From the collarbone, through the coat and the shirt and everything under them, down across his chest and his stomach to his right hip, and the sound it made was a sound Solar would hear for the rest of her life at the edges of quiet rooms: a long wet tearing, like heavy cloth, and under it, separate, small, a run of clicks like someone running their thumb down a comb, which were his ribs." },
      { n: "He didn't make a sound. His head went back. The front of him opened, the coat falling apart in two flaps, and what was inside him came forward into the red light all at once, red, shining, steaming in the cold, and spilled down over the woman's cream cardigan, down the front of it, over the apron, and she held him up against her by the shoulder with her other hand, gently, while it did, and looked over his shoulder up the steps at Solar." },
      { n: "*There, there*, she said. In Solji's voice. *There, there.*" },
      { n: "Then she let him go, and he fell down the steps at her feet, and she stepped over him, barefoot, and patted Jaesang's cheek once with a hand that was a hand again, a woman's hand, Solji's, with the wedding ring on it, *another time, honey*, and turned and walked away down the steps into the dark, humming, three up, two down, a long one, the cream cardigan dark to the hem with Shinjiro." },
      { n: "Akihiko got to him first." },
      { n: "He came down the steps on his knees, Solar thought afterward; he couldn't have been on his feet, he was just there, on the stone, with Shinjiro across his lap, holding him, one arm under his shoulders and the other hand flat on the front of him, on the opening, pressing, as if you could press that closed, as if there were anything to press. The blood came up between his fingers and over the tape on his knuckles and down his wrists. He didn't look at it. He was looking at Shinjiro's face." },
      { s: 'akihiko', f: 'surprised', t: "Shinji. Shinji. Look at me. Hey. *Hey.* Look at me. Yukari— get Yukari— somebody get—" },
      { n: "Yukari wasn't there. Yukari was at the top of the Well with Fuuka. There was nobody to get. Mitsuru was on the radio saying a name in a voice Solar had never heard her use. Haechan had Jaesang by both arms, holding him up; her father's face was a white sheet, his shirt red down the front where it had splashed. Jaehyun had his back to all of it and was holding his father's coat." },
      { n: "Ken was standing on the step above them. Very straight. Eleven years old again. Exactly where he'd stood once, in another October, in another year, in the rain, in front of this same coat. He had his spear in his hand and he wasn't holding it, it was just in his hand. He didn't make a sound. Koromaru pressed against his legs and whined, high and thin, once, and Ken put his hand down on the dog's head without looking." },
      { n: "Shinjiro's eyes moved. Not to Akihiko. Past him. Up the steps. To Solar, who'd come down and was kneeling on his other side with her hands out and nothing to do with them." },
      { n: "His mouth moved. There was blood in it. He swallowed. He tried again." },
      { s: 'shinjiro', f: 'neutral', t: "...You eat. Tonight." },
      { s: 'solar', f: 'sad', t: "I ate. I ate, Shinjiro, you watched me, you made me—" },
      { s: 'shinjiro', f: 'neutral', t: "...Yeah. I did." },
      { n: "His eyes went to Akihiko. He looked at him for a long time. A second. A long time." },
      { s: 'shinjiro', f: 'happy', t: "...Don't make it a thing, Aki." },
      { n: "And that was all. His eyes stayed open on Akihiko's face, and Akihiko went on saying his name, *Shinji, Shinji, Shinji*, quieter and quieter, the way you'd say it to wake somebody up gently on a train, for a long time after there was no one to wake." },
      { flag: ['dead.shinjiro', 'eqx-true-closed'] },
      { n: "It was Ken who closed his eyes. In the end. He came down the last step and knelt and did it, carefully, with two fingers, the way you'd been shown at a funeral and never thought you'd do, and then he sat back on his heels in the blood on the stone and put both his hands over his face." },
      { n: "They carried him up. Akihiko wouldn't let anybody else. He carried him up the steps and up the road over two hills, past the empty baskets, past the shoes with the feet in them, past the ones with no feet, with his coat open and his arms locked and his face like a closed door, and nobody spoke to him the whole way, and at the bottom of the rope he tied Shinjiro to himself with Mitsuru's climbing line and climbed, by himself, with the weight of him, the whole height of the Well, and nobody tried to stop him." },
      { n: "At the top, in the courtyard, in the red, Yukari was waiting by the lip with her bow. She saw what was on Akihiko's back. She dropped the bow." },
      // CG: eqx-road-home — a narrow pale country road winding over endless dark hills under a huge low red moon, round woven baskets with their lids off set at the roadside, stone steps going down a slope lined with pairs of shoes.
      { n: "Up the hill, at the boarding house, in the kitchen, a light went on." }
    ], else: [
      { n: "Shinjiro got to him." },
      { n: "He came down the last two steps in one stride and didn't get between them; there wasn't time to get between them. He reached past Solar, past the coil of rope, and took Jaesang by the back of the collar. With his right hand. The bad one. The one that had dropped forty cups and forty eggs since April and had held a pan at one o'clock that morning without dropping it. It closed on the collar of the borrowed coat and held, and he threw his whole weight backward up the steps." },
      { n: "Jaesang went over backward onto the stone. The arms of the cream cardigan closed where he'd been." },
      { n: "And the hand came up out of the sleeve. The thing from under the glove, huge, striped, floured, the long yellow points sliding out of it, swinging after him: and it caught Shinjiro instead, as he went back, across the front. Not deep. The points went through the front of his long coat like paper and opened it in three ribbons from the shoulder to the hip, and the shirt under it, and drew three lines across his chest under the shirt, and he grunted and sat down hard on the steps with Jaesang's collar still in his fist." },
      { n: "The woman at the bottom of the steps looked at him. Solji's face, with something behind it. Fond. Disappointed. Patient." },
      { n: "*Oh*, she said, in Solji's voice. *Oh, you naughty boy. Another time, then.* And the hand was a woman's hand again, with Solji's wedding ring on it; and she blew Jaesang a kiss with it, the way Solji blew kisses through the car window when she dropped Solar at school; and turned and walked away down the steps into the dark, barefoot, humming." },
      { n: "Nobody moved for a moment. Then everybody moved." },
      { n: "Akihiko was on his knees beside Shinjiro with his hands on his chest, on the three red lines coming up through the torn shirt, pressing; the blood was real, there was a lot of it, but it was the blood of something that would close." },
      { s: 'akihiko', f: 'surprised', t: "Shinji. Shinji. Look at me. Are you— how bad— *look at me*—" },
      { s: 'shinjiro', f: 'neutral', t: "...Get off. I'm fine. It's a scratch. It's three scratches. Get off me, you're kneeling on my coat." },
      { s: 'akihiko', f: 'serious', t: "Your coat's in *ribbons*—" },
      { s: 'shinjiro', f: 'neutral', t: "Yeah. I liked that coat." },
      { n: "He still had Jaesang's collar in his right hand. He looked down at it as if he'd only just noticed. His fingers were locked on it, white, the knuckles standing up. He looked at them for a long time. Then he opened them, one at a time, on purpose, and every one of them opened when he told it to." },
      { s: 'shinjiro', f: 'neutral', t: "...Huh. Look at that." },
      { n: "Jaesang sat up on the stone. He looked at the hand that had been on his collar. He looked at the young man in the shredded coat, with the blood coming through his shirt, who'd told him two days ago that he held his chopsticks wrong. Then down the steps, at the dark, where his wife's face had gone, still smiling." },
      { n: "He didn't say anything. He reached out and took Shinjiro's right hand in both of his and held it, very hard, the way you'd hold the hand of a man who'd signed something for you, and Shinjiro let him, and looked away, embarrassed, at the shoes." },
      { flag: 'eqx-shinji-lived' },
      // CG: eqx-road-home — a narrow pale country road winding over endless dark hills under a huge low red moon, round woven baskets with their lids off set at the roadside, stone steps going down a slope lined with pairs of shoes.
      { n: "They went back up the road over the two hills. Ken carried Jaesang's running shoe. Jaehyun walked with his arm through his father's and didn't let go once. At the top of the Well, in the red, Yukari took one look at Shinjiro's coat and said a word Solar had never heard her say, and put her hands on his chest, and Io's light came down green over the red, and the three lines closed to three pink seams, and he said *ow* about it, at last, as if he'd been saving it." }
    ] },
    { place: 'Iwatodai Dorm · Lounge', time: 'The Red Hour', bg: 'darkhour-dorm-lounge', music: 'darkhour', soft: true },
    { n: "The fathers knew now." },
    { n: "That was the other thing that came up out of the Well that night. They'd seen her face. All three of them had seen it, at the bottom of the steps, Solji's face with the slip at the jaw and the other thing looking out of her eyes; and Mr. Kim had seen it, and understood what it meant for the woman in the garden taking in the washing, though he'd never seen her; and Taejoon had seen it, and understood the sink." },
    { n: "Taejoon sat on the floor of the lounge with his back against the couch. He'd been holding the green garden clogs the whole way up. He set them down on the floor in front of him. Side by side. Toes to the door." },
    { s: 'taesang-strangers', f: 'neutral', t: "...Something is wearing my wife." },
    { n: "He said it in Korean, to the clogs, very evenly, the way you'd read a line out of a newspaper. Nobody answered him. There wasn't anything in any language to answer him with." }
  ] },

  { id: 'eqx-morning-after', date: '10/24', slot: 'early', consumes: true, title: 'nine bowls', place: 'Iwatodai Dorm · Dining Room', time: 'Early Morning',
    cast: { solar: 'Solar', akihiko: 'Akihiko', ken: 'Ken', junpei: 'Junpei', mitsuru: 'Mitsuru', shinjiro: 'Shinjiro', 'jaesang-runners': 'Jaesang', yukari: 'Yukari', haechan: 'Haechan' },
    scene: [
    { bg: 'iwatodaidorm-diningroom', music: 'tender' },
    { ifFlag: 'dead.shinjiro', then: [
      { n: "The hour ended at one-twenty-one. Akihiko didn't look at the stopwatch. Mitsuru did. She took it out of his pocket while he sat on the lounge floor with his back to the wall and his arms on his knees and his hands hanging, red to the wrist, and she looked at it and put it back in his pocket and didn't tell anyone the number. Solar found out later from Fuuka. Eighty-one forty, at the lip. When the hour ended, eighty-one fifty-eight." },
      { n: "Eighteen seconds. Fed." },
      { n: "The Group came for him at two. Men in gray coveralls with a stretcher and long faces, the same men from the bridge, and Akihiko stood up when they came in and stood between them and the couch where they'd laid him under a sheet, and didn't say anything, and didn't move, and Mitsuru went and stood beside Akihiko and said *they'll take care of him, Akihiko, I've told them who he is*, and after a long time he stepped aside." },
      { n: "He stays here. That was what the doctor said, in the hall, to Mitsuru, in a low voice, and Solar heard it. Whatever happens here stays here. He'll be buried here. In this town." },
      { n: "In the morning there were nine bowls on the counter." },
      { n: "Nobody had put them there. They were the bowls from the night before last, from the one o'clock rice, washed and dried and stacked by the sink, and somebody, coming down at six, not thinking, had taken them off the stack and set them out in a row on the counter the way he always set them, nine, one for everybody who'd go down, and then stood looking at them." },
      { n: "It was Junpei. He was standing in front of them in his pajamas when Solar came down. He'd set out nine. He was looking at the ninth." },
      { s: 'junpei', f: 'sad', t: "...I did it without thinking. I just. He always did nine. I was gonna make toast. I was gonna make toast for Ken because Shinjiro-senpai burns it on purpose so Ken eats it and I thought, I'll do it today, I'll burn it, I'll—" },
      { n: "He stopped. He picked up the ninth bowl very carefully in both hands and held it." },
      { n: "Ken came down at seven. He was dressed for school, on a Sunday. His uniform, buttoned to the top, his hair combed wet. He walked past the counter and the bowls and Junpei and went to the kitchen door and stood in it, the doorway to the kitchen, where there was a chair by the door that nobody but Shinjiro sat in; a plain chair, nearest the hall, where he could see the stove and the door at the same time." },
      { n: "Ken didn't sit in it. He looked at it. Then he went and stood by the stove with his back to the room and said, very clearly, to the stove, *I'd like some toast, please*, and Junpei put the bowl down and went and made him some, and burned it, on purpose, all the way through, and Ken ate every bite of it standing up, with his eyes shut." },
      { n: "Akihiko didn't come down." },
      { n: "Mitsuru brought Solar the coat at nine. In a bag. The long coat, what was left of it, washed by the Group's people, which was worse, folded, in a paper bag from the hospital. She didn't say why she was giving it to Solar instead of Akihiko. She didn't have to." },
      { s: 'mitsuru', f: 'sad', t: "There were papers in the pocket. I didn't read them. They're his." },
      { n: "Two. Folded small, soft at the creases from being carried, one in each inside pocket. Hospital forms. The therapist's goal sheets. Solar unfolded the first one at the table with her hands not quite steady." },
      { n: "*What do you want to be able to do by summer?*" },
      { n: "And under it, in pencil, in a hand like a fist, two words. The letters huge and shaking and dug into the paper, written with a right hand that couldn't close round the pencil, that had held it the way you'd hold a spoon in your fist when you were two." },
      { n: "*hold a pan*" },
      { n: "She looked at it for a long time. She thought about one o'clock in the morning, two days ago. Nine bowls. The pan in his right hand. The rolled omelet coming out of it perfect, gold, without a tear in it. *You held it. Yeah. Don't make it a thing.*" },
      { n: "She didn't unfold the second one. It was his. She put them both back in the coat, in the pockets where they'd been, and folded the coat, and put it in the bag, and took it upstairs, and knocked on Akihiko's door, three times, and said who it was, and when he didn't answer she put the bag down outside his door and sat down beside it in the hall with her back against the wall." },
      { n: "She was there at noon when the door opened. He looked down at the bag, and at her. His hands were washed. The tape was gone off his knuckles; there was nothing on them at all, for the first time since April, just his hands." },
      { s: 'akihiko', f: 'sad', t: "...My hand didn't close. Last night. I've been waiting all night for it to close. On anything. It closes every night. It didn't close." },
      { s: 'akihiko', f: 'sad', t: "I think it was waiting to hold him. I think that's what it was for." },
      { n: "He sat down beside her in the hall, on the floor, with the bag between them, and put his face in his open hands, and she put her arm round his shoulders and held on, and neither of them said anything for an hour." },
      { n: "Downstairs, Koromaru had dragged the folded blanket off the couch in the lounge, the one they'd laid Shinjiro on before the Group came, and pulled it to the kitchen door, and lay down on it, by the chair, and wouldn't be moved." }
    ], else: [
      { n: "The hour ended at one-twenty-one. Eighty-one forty at the lip, Akihiko said; eighty-one forty-one at the end. One second. *It didn't get anything*, Akihiko said, and laughed, once, a strange cracked sound, and sat down on the lounge floor with his back against Shinjiro's knees." },
      { n: "In the morning there were nine bowls on the counter and Shinjiro was standing over the stove with his shirt buttoned wrong over the bandages, making eggs." },
      { n: "Right-handed. The pan in his right hand. He'd been there since five, Junpei said; Junpei had come down at six to make Ken's toast and found him there and been told to sit down and shut up." },
      { s: 'shinjiro', f: 'neutral', t: "Sit. All of you. Rolled or fried, I'm not taking requests, you're getting rolled." },
      { s: 'yukari', f: 'neutral', t: "You're supposed to be lying down. I told you. I healed it, I didn't *fix* it, you're supposed to lie down for two days—" },
      { s: 'shinjiro', f: 'neutral', t: "I lay down for eight months. Sit." },
      { n: "Jaesang came over from the boarding house at seven. Alone. Jaehyun had walked him to the gate and then, at Jaesang's request, gone back. He came into the dining room in yesterday's clothes with the red still on the cuff of his shirt and stood in the doorway and looked at Shinjiro at the stove." },
      { n: "Shinjiro didn't look round." },
      { s: 'shinjiro', f: 'neutral', t: "...Sit down, Mr. Lee. It's rolled." },
      { s: 'jaesang-runners', f: 'neutral', t: "I came to say—" },
      { s: 'shinjiro', f: 'neutral', t: "Yeah. I know. Sit down and eat it and then it's said." },
      { n: "Jaesang sat down. Shinjiro put a plate in front of him, a rolled omelet, gold, perfect, and stood back with his arms folded, and Jaesang looked at the plate, and picked up his chopsticks." },
      { s: 'shinjiro', f: 'neutral', t: "...You're still holding them wrong." },
      { n: "Jaesang laughed. It came out of him like something breaking. He sat at the table in the Iwatodai dorm at seven in the morning with his wife's blood, or what had worn his wife, dried on his cuff, and laughed until he had to put the chopsticks down, and then he put his hand over his eyes, and Shinjiro went back to the stove and made another omelet for nobody in particular, loudly, banging the pan." },
      { n: "Akihiko came and stood beside him at the stove. Close. Their shoulders touching. He didn't say anything. He looked at the right hand on the pan handle." },
      { s: 'akihiko', f: 'neutral', t: "...You held it." },
      { s: 'shinjiro', f: 'happy', t: "Don't make it a thing, Aki." },
      { n: "Akihiko's own right hand came up, the taped one, and closed. On Shinjiro's shoulder. By itself. Hard. And this time Akihiko didn't pry it off. He let it stay." }
    ] }
  ] },

  { id: 'eqx-empty-chair', date: '10/26', slot: 'evening', consumes: true, title: 'out of that house', place: 'The Oka Boarding House · Gate', time: 'Evening',
    cast: { solar: 'Solar', mitsuru: 'Mitsuru', mrsoka: 'Mrs. Oka', 'kim-dad': 'Mr. Kim', 'taesang-strangers': 'Taejoon', 'jaesang-runners': 'Jaesang', akihiko: 'Akihiko', ken: 'Ken', chaewon: 'Chaewon' },
    scene: [
    { ifFlag: 'dead.shinjiro', then: [
      { place: 'Iwatodai · Funeral Hall', time: 'Evening', bg: 'naganaki-shrine-night', music: 'tender' },
      // BG: eqx-funeral-hall — (as Act III) a small plain funeral hall in a Japanese residential street at dusk, white and black striped curtains over the entrance, paper lanterns, wreaths on stands.
      { n: "They buried him on Tuesday." },
      { n: "The same small hall two stops down the line, the same black and white curtains, the same street of shuttered shops; the man at the desk recognised Mitsuru and bowed very low and didn't say anything. There was no photograph. Nobody had one. In the end Minji gave them a frame from her camera, from June, from the dorm kitchen: Shinjiro at the stove with his back half turned, the ladle in his left hand, looking over his shoulder at something off the edge of the frame with an expression that wasn't quite a smile. She'd printed it at the konbini at midnight. It was a little blurred. It was the most like him of anything." },
      { n: "There was no family. There'd never been, in this year or the last. There was the dorm. All of it, in a row, in their school uniforms and borrowed black; and the guesthouse; and the girls from the boarding house, in black dresses Hyein had found somewhere; and the parents, the three fathers in a row at the back, in borrowed suits, Jaesang in the middle with his hands folded in his lap." },
      { n: "Ken lit the incense. He'd asked to. He'd stood in front of Mitsuru and asked in his politest voice and she'd said yes before he'd finished. He went up to the altar in his uniform with his back very straight and lit it and stood with his hands together and his eyes shut for a long time, much longer than anyone else, and then he did something nobody had seen him do at the last one. He reached into his pocket and took out a piece of toast. Burnt. Black all the way through. In a paper napkin. And put it on the altar in front of the photograph, beside the oranges." },
      { n: "Junpei made a sound at the back of the hall and walked out." },
      { n: "Akihiko didn't cry. He sat in the front row with his hands open on his knees, palms up, the tape gone, and looked at the photograph the whole way through, the sutra, the incense, the bowing, and when it was over and everyone stood he went on sitting, and the hall emptied round him, and he sat." },
      { n: "Solar sat beside him. Haechan stood in the doorway, keeping it, the way he kept doors now." },
      { s: 'akihiko', f: 'sad', t: "...He knew. I think he knew. On Friday night, at the stove. *I'm in the back.* He knew where the back was going to be." },
      { s: 'akihiko', f: 'sad', t: "He never asked anybody for anything. Not once in his life. He'd have asked for that. He'd have asked to be the one in the back. That's the only thing I ever heard him ask for." },
      { n: "He looked at his hands. Open on his knees. They didn't close." },
      // CG: eqx-burnt-toast — a small plain altar in a quiet funeral hall, oranges and incense smoke in front of a slightly blurred printed photo of a figure at a kitchen stove, a single piece of burnt toast on a paper napkin set among the offerings.
      { n: "Mrs. Oka had sent rice cakes. A dozen white boxes, tied with string. *For the mourners. With love.* They were on the table by the guest book when the household came in, and they were gone when it went out, all twelve, and nobody saw who took them; and that night, behind the dorm, in the bins at the end of the alley, Haechan found all twelve boxes, unopened, under the lid, stacked very neatly, the way somebody stacks things who has been taught, once, by someone who's gone, how to do it." }
    ] },
    { place: 'The Oka Boarding House · Gate', time: 'Evening', bg: 'eqx-oka-gate', music: 'badfeeling' },
    { n: "Mitsuru moved the fathers out that week." },
    { n: "She did it the way she did everything, with paper. A letter to the boarding house on Kirijo letterhead, regretting that the Group required the rooms to be vacated for its guests' security, effective Tuesday. A van. Two men in gray coveralls to carry the suitcases. Rooms on the dorm's third floor, made up by Fuuka and Yukari on Monday after school with the good sheets from Mitsuru's own closet." },
    { n: "She did it, Solar knew, because of what the fathers had seen on the steps, and what they'd understood about the kitchen, and the sink, and the garden; and because three grown men who'd seen their wives' faces worn by something couldn't go on eating supper in a house where something had been wearing them." },
    { n: "She did it without ever once saying Mrs. Oka's name." },
    { n: "Mrs. Oka cried at the gate." },
    { n: "She stood in the open gate in her gray kimono and her white gloves with the persimmon tree behind her, every fruit on it orange, the ground under it soft with the ones that had fallen and split, and watched the men carry the suitcases out to the van, and cried. Quietly. Openly. Her small face crumpled and wet, the way it had been on the bridge at dawn, the way it had been on the twenty-seventh of July." },
    { s: 'mrsoka', f: 'sad', t: "Of course. Of course, you must. The Group knows best. It's only that I'd got used to them. You get used to people, don't you. You get used to setting a place." },
    { s: 'mrsoka', f: 'worried', t: "Mr. Kim. You'll come by. You'll come by and tell me where you've been. You won't stop telling me." },
    { n: "Mr. Kim was carrying his own suitcase. He stopped in front of her at the gate. He looked down at her, at her small kind wet face, for a long time; and Solar, standing at the van with Mitsuru, watched him look, and didn't breathe." },
    { s: 'kim-dad', f: 'neutral', t: "...Thank you for keeping my supper warm." },
    { n: "He said it very politely. He bowed. Then he went past her to the van and put the suitcase in, and didn't look back, and his hands were shaking." },
    { n: "Taejoon didn't say anything to her at all. He came out of the house with his one bag and the green clogs in his other hand and walked past her and bowed to her exactly as deeply as you bow to a stranger at a funeral, and she bowed back exactly as deeply, and something passed between them in that, Solar thought, something nobody else at the gate could have read, two people who said nothing very loudly recognising each other." },
    { n: "Jaesang came last. He stopped at the gate. He looked up at the persimmon tree." },
    { s: 'jaesang-runners', f: 'neutral', t: "Mrs. Oka. When the Group's finished with the boarding house, I'd like to buy it." },
    { s: 'mrsoka', f: 'surprised', t: "Buy it? Oh— why ever would you want to buy it?" },
    { s: 'jaesang-runners', f: 'neutral', t: "I'd like to have the well filled in. With concrete. And the tree taken down. I've always wanted a garden with nothing in it." },
    { n: "Mrs. Oka looked at him. She stopped crying. It didn't stop slowly, the way crying stops; it stopped all at once, the way a tap is turned off. Her wet eyes on his face were very bright and very still." },
    { s: 'mrsoka', f: 'happy', t: "...What a thing to say. Isn't that a funny thing to say. I'll keep it in mind, Mr. Lee." },
    { n: "Then she was crying again, softly, waving them off with one gloved hand as the van pulled away down the river street, and the girls at the upstairs window were waving too, and Chaewon was counting them out under her breath; and Solar, in the back of the van with her father's knee against hers, looked back through the rear window the whole way to the corner." },
    { n: "Mrs. Oka didn't go inside. She stood in the open gate and watched them, getting smaller, until the corner; and the whole time, she wasn't waving anymore. She was knocking. Gently. On the gatepost. Twice, and a pause. Twice, and a pause. Twice." },
    { flag: 'eqx-fathers-moved' }
  ] },

  { id: 'eqx-culture-stage', date: '10/30', slot: 'after', consumes: true, title: 'five, six, seven, eight', place: 'Gekkoukan High · Gym', time: 'Culture Festival',
    cast: { solar: 'Solar', hanni: 'Hanni', yunjin: 'Yunjin', chaewon: 'Chaewon', sakura: 'Sakura', kazuha: 'Kazuha', eunchae: 'Eunchae', junpei: 'Junpei', jungwon: 'Jungwon',
      haechan: 'Haechan', jihoon: 'Jihoon', akihiko: 'Akihiko', minji: 'Minji', shinjiro: 'Shinjiro', 'kim-dad': 'Mr. Kim' },
    scene: [
    { place: 'Gekkoukan High · Courtyard', time: 'Culture Festival', bg: 'gekkoukan-culture-festival', music: 'school' },
    { n: "The culture festival happened anyway. That was Gekkoukan. Somebody had died on a staircase at the bottom of a well under the courtyard a week ago and the courtyard was full of stalls, takoyaki and yo-yo fishing and a haunted house in 2-B with a sign out front that said ABSOLUTELY TERRIFYING!! in dripping red paint, and the well itself had a festival banner tied round its plank lid like a ribbon on a present, because the committee had needed somewhere to tie it." },
    { n: "Mitsuru's man on the gate at four had taken the banner off twice. It was back on by noon both times. Nobody on the committee remembered putting it there." },
    { ifFlag: 'dead.shinjiro', then: [
      { n: "3-F had a yakisoba stall. Junpei ran it. He'd insisted, at the class meeting, standing up on his chair, and nobody had had the heart to tell him he couldn't cook. He had a recipe on an index card taped to the griddle in somebody else's handwriting, square, careful, the letters dug into the card: *more cabbage than you think. Don't drown it. Taste it before you serve it, idiot.* He tasted every batch. He served every one. It was the best yakisoba at the festival, and he stood behind the griddle all day in a headband with his eyes red and told every customer it was a family recipe." }
    ], else: [
      { n: "3-F had a yakisoba stall. Shinjiro ran it, from a folding chair behind the griddle with his shirt buttoned over the bandages and Junpei doing the actual standing up, and told every customer who came by that if they wanted it with less cabbage they could go to 2-D, and every customer stayed, and it was the best yakisoba at the festival and he wouldn't say so." }
    ] },
    { place: 'Gekkoukan High · Gym', time: 'Culture Festival', bg: 'gekkoukan-gym', music: 'joy' },
    // BG: gekkoukan-gym-festival — a school gym dressed for a culture festival afternoon, folding chairs in rows, a low stage at the far end with paper decorations and a hand-painted banner, the lights dimmed for a performance.
    { n: "The girls had a slot at three." },
    { n: "Jungwon had got it for them. He wasn't on Gekkoukan's council; Gekkoukan's council was a nervous second-year who was afraid of him. He'd gone to the festival committee with a one-page proposal and a timetable and asked, very formally, for fifteen minutes on the gym stage for *an international exchange dance unit*, and the committee had said yes before he'd finished bowing." },
    { n: "Five of them. Chaewon, Sakura, Kazuha, Eunchae. And Yunjin, at the end of the line, in black, with her hair up, and the space on her left." },
    { n: "Solar sat in the third row between Hanni and Mr. Kim. Mr. Kim had brought his camera, a real one, a heavy black one he'd bought at a pawn shop by the station on Wednesday with Jaesang's money because he'd said that somebody in this family has to film things that aren't terrible for once. The other two fathers were at the end of the row. Taejoon with his arms folded. Jaesang with a program open on his knee, reading it as carefully as a contract." },
    { n: "The lights went down. The music came up, tinny out of the gym's old speakers, too loud, distorting on the bass; and Chaewon counted them in, out loud, *five, six, seven, eight*, and they moved, and the gym went quiet." },
    { n: "It wasn't a school festival act. Everybody in the gym knew it in the first eight counts. The kids in the front rows who'd come to laugh stopped laughing. The teachers at the back stopped talking. Five girls on a plywood stage in a high school gym in a town where people were dying in their sleep, moving like one thing, every head turning at once, every arm; the floor going *hush, hush* under their feet on the beat, the way it had in the tatami room in July." },
    { n: "On the bridge part Yunjin turned to her left. To the space. Her arm went out to it, palm up, the way it went out every time, for somebody who was supposed to be there and wasn't." },
    { n: "Solar's left foot moved on the gym floor under her chair. On the beat. By itself." },
    { n: "Hanni, beside her, saw it, and put her own foot on top of Solar's, gently, and left it there." },
    { n: "When it ended the gym didn't clap for a second. Then it came apart: everyone on their feet, the kids in the front screaming the way kids scream at real ones, the teachers clapping with their hands up over their heads, Mr. Kim on his feet with the camera still running and tears running down into his collar, saying *again, again, encore, do it again* in Korean to nobody. Taejoon clapped four times, slowly, and unfolded his arms to do it." },
    { n: "On the stage, in the light, Yunjin looked out over the gym and found Solar in the third row and looked at her for a long time. She didn't smile. She looked lost, the way she'd looked lost in the tatami room, as if she'd just remembered something that hadn't happened yet." },
    // CG: eqx-five-girls — five young women mid-dance in a single line on a small school gym stage under dimmed festival lights, the end dancer reaching out an open palm to an empty space at her side, a crowd of students on their feet in the dark.
    { place: 'Gekkoukan High · Roof', time: 'Culture Festival', bg: 'rooftop-evening', music: 'tender' },
    { n: "Hanni found her on the roof after. The festival was going on below them, the lanterns coming on along the stalls in the dusk, someone on the PA reading out raffle numbers. Hanni sat down beside her on the bench with two cans of hot corn soup from the machine, the way she'd come and sat down beside her on a hundred benches in two countries, and put one into Solar's hands." },
    { n: "She didn't say anything for a while. Then she did." },
    { s: 'hanni', f: 'neutral', t: "I've been having a dream. Since the equinox. The same one." },
    { s: 'hanni', f: 'neutral', t: "I'm in a classroom. It's not ours. It's not Syracuse, it's not here. It's in Korea, there's Korean on the board, it's a high school, there's a girl in front of me with her hair in a red tie, and the window's got snow on it. And I'm wearing a uniform I've never seen. Plaid skirt. A blazer with a crest. And I know where my locker is." },
    { n: "Solar didn't say anything. The soup can was very hot in her hands." },
    { s: 'hanni', f: 'neutral', t: "I know where the vending machine on the second floor is that eats your coins. I know which stair on the east stairs is cracked. I know the vice president's name. Kim Solar. She's in 3-something. Everybody talks about her." },
    { s: 'hanni', f: 'sad', t: "I've never been there, Sol. I've never been to that school in any life I've got. And I know where my locker is." },
    { n: "She turned the can round and round in her hands." },
    { s: 'hanni', f: 'sad', t: "The girls have three. Chaewon told me. They woke up with three lives each. And now it's— it's like it's looking for a third one in me. Like it's reaching." },
    { s: 'solar', f: 'neutral', t: "What's it?" },
    { s: 'hanni', f: 'sad', t: "I don't know. Whatever's making rope." },
    { n: "Below them on the courtyard the festival banner had come off the well's lid again and was lying on the paving, and nobody had put it back, and the plank lid had moved: Solar could see it from the roof. A few centimeters. The way it had moved for Jungwon in April. From below." },
    { s: 'hanni', f: 'neutral', t: "...Don't tell Hyein. She's got enough. She's got her mom's voice in her phone, she doesn't need me waking up in a different school." },
    { n: "Solar put her head on Hanni's shoulder. Hanni let her, and drank her soup, and the PA read out the last raffle number, and nobody had it." },
    { place: 'Gekkoukan High · Gym', time: 'Evening', bg: 'gekkoukan-gym', music: 'romance', soft: true },
    dating('haechan', [
      { n: "Haechan was in the dark gym afterward, alone, on the edge of the stage with his legs hanging over, plugging his phone into the old speakers. When she came in he didn't say anything. He put on a song. Not one of theirs. One of his, from home, from a session in Brooklyn in a life that hadn't happened to her yet, with a gap in bar four shaped like a voice." },
      { s: 'haechan', f: 'neutral', t: "...Your foot went. On the bridge part. I saw it from the back." },
      { s: 'solar', f: 'neutral', t: "Hanni stood on it." },
      { s: 'haechan', f: 'smirk', t: "Good for Hanni." },
      { n: "He held out his hand from the stage, not to pull her up, just held out. She took it and climbed up herself, and they sat on the edge of the stage in the dark gym with the song going and the folding chairs in their rows in front of them like an audience that had gone home, and at the gap in bar four he didn't fill it, and neither did she, and they let it go by." }
    ], [dating('jungwon', [
      { n: "Jungwon was in the dark gym afterward, stacking folding chairs. Alone. Fourteen to a stack, exactly. He'd volunteered. When she came in he didn't stop; she picked up a chair and handed it to him and he took it and stacked it, and they did forty chairs like that, in silence, and on the forty-first he put it down and turned round and kissed her, in the dark, against the stack, very carefully, the way he did everything, and then stood back and straightened his blazer." },
      { s: 'jungwon', f: 'flustered', t: "...That was not on the agenda. I'm noting that it wasn't on the agenda." }
    ], [dating('jihoon', [
      { n: "Jihoon was under the bleachers. Of course he was. He'd taken a can of something from the teachers' cooler and a festival pennant from 2-B and was sitting on the floor under the folded seats with his back against the wall, waiting, the way he waited for her anywhere there was a door that shouldn't have been open. He held up the pennant. ABSOLUTELY TERRIFYING!!" },
      { s: 'jihoon', f: 'happy', t: "For you. I stole it. I'm a menace to this school." },
      { n: "She got down on the floor under the bleachers with him. He kissed her the way he did, like he was getting away with something, and when he pulled back he put his forehead against hers in the dark under the seats." },
      { s: 'jihoon', f: 'neutral', t: "...Nobody's watching. That's still the best thing about this place. And I keep thinking about the guy in the long coat on those stairs and it's the worst thing too." }
    ], [dating('akihiko', [
      { n: "Akihiko was in the dark gym afterward, running lines. Baseline to baseline. In his festival shirt. When she came in he stopped at the far wall with his hands on his knees and looked at her across the whole length of the empty floor." },
      { s: 'akihiko', f: 'neutral', t: "...I can't stand still today. I keep thinking if I stand still I'll— never mind." },
      { n: "She walked across the gym to him. He met her halfway. He didn't kiss her. He put his forehead down on her shoulder and stood there, breathing hard, and his hand came up and closed on the back of her blazer, by itself, and he let it, and she let it." }
    ], [dating('minji', [
      { n: "Minji was in the dark gym afterward, on the edge of the stage, rewinding. She'd filmed the whole thing from the side of the stage. She held the camera out so Solar could see the screen: the five of them, the bridge part, Yunjin's arm going out to the space." },
      { s: 'minji', f: 'neutral', t: "Watch. On the bridge. Look at the third row." },
      { n: "On the little screen, in the third row, in the dark, Solar's left foot moved. On the beat. Minji paused it there." },
      { s: 'minji', f: 'happy', t: "I'm keeping that one. That's my one second today. That's the best second I've got." },
      { n: "Then she put the camera face down on the stage, and kissed her, quickly, off the record." }
    ], [{ n: "The gym was empty afterward. Solar stood in the doorway and looked at the stage in the dark, and the folding chairs, and on the stage, at the end of the line where they'd stood, a piece of tape on the floor marking a sixth place nobody had danced in. She hadn't noticed it before. Somebody had put it there. Chaewon, probably. She didn't take it up." }])])])])]),
    { flag: 'eqx-culture-stage' }
  ] },

  { id: 'eqx-door-runners-3', date: '11/3', slot: 'late', consumes: true, title: 'you could just sit down', place: 'The Well · The First Hill', time: 'The Red Hour',
    cast: { solar: 'Solar', haechan: 'Haechan', minji: 'Minji', akihiko: 'Akihiko', fuuka: 'Fuuka', chenle: 'Chenle' },
    scene: [
    { bg: 'eq-well-3', music: 'mystery' },
    { dark: true },
    { n: "The doors had started in October." },
    { n: "Not every night. Not every block. Chenle had found the first one on the Second Hill a week after the equinox: a plain door in the mud with a brass knob, standing on its own in the tide, and behind it a kitchen. A real one. Someone's. He'd called it out and Fuuka hadn't been able to see it at all. Since then there'd been one on the Third Hill, and two on the First, and every one of them opened onto somewhere from home. Somewhere from one of their homes. Empty." },
    { n: "Fuuka called them home bleeds. Mitsuru called them a problem. Akihiko called them nothing; he'd been in one, the Wednesday after the funeral or the Wednesday after the steps, Solar didn't know which, she didn't ask, and when he came out he'd sat on the stairs of the First Hill for twenty minutes without a word." },
    { n: "Tonight the First Hill had snow on it again. The black ice. The campus upside down in it, dark, the coffins in their rows in the quad with their lids shut. And at the end of the long path, where the stage-light hall stood, a door had opened in the side of the hall that hadn't been there in July. A back door. Wooden. With a porch light over it, yellow, and a mat in front of it that said WELCOME in letters worn half away by boots." },
    { s: 'chenle', f: 'surprised', t: "...That's the Sigma house. The back door. That's the kitchen door. I've puked off that porch." },
    { s: 'haechan', f: 'neutral', t: "Yeah. Everybody's puked off that porch. That's what the porch is for." },
    { n: "He was very calm. He was standing very still at the foot of the porch steps with his hands in his pockets, looking at the door of the house where he'd lived, in one of his lives, for three years." },
    { s: 'fuuka', f: 'sad', t: "Solar, there's nothing inside it. I can't hear anyone. I can't hear anything. It's like the bridge." },
    { place: 'The Well · A Kitchen in Syracuse', time: 'The Red Hour', bg: 'epi-r-sigma-kitchen-night', music: 'eerie' },
    { n: "Inside it was the Sigma Chi kitchen at two in the morning on a Saturday in December, with nobody in it." },
    { n: "Everything else was there. The red solo cups on every surface. The keg in the corner in its bucket of melted ice. A pizza box on the island with three slices left in it, the cheese gone stiff. Somebody's hoodie over a barstool. The speaker on top of the fridge with its little blue light on, playing nothing. A string of Christmas lights round the window, blinking, on, off, on, off. The radiator knocking. Snow on the window." },
    { n: "It was warm. That was the worst part. It was warm the way that house was warm in winter, too warm, everybody in T-shirts, the windows sweating. After the cold of the Well it hit Solar in the chest like a hand and she wanted to sit down so badly her knees went." },
    { n: "Minji had her camera up. She lowered it. She stood in the kitchen doorway with her mouth a little open." },
    { s: 'minji', f: 'sad', t: "...It's so quiet. It was never quiet. In two years I never once heard this kitchen quiet." },
    { n: "Akihiko stood with his back against the door frame and didn't come in. He was looking at the hoodie on the barstool. Somebody's. Gray. A size too big for whoever had worn it." },
    { n: "And Haechan walked to the island and pulled out the barstool, the one with the hoodie on it, and put his hand on the back of it, and stood there." },
    { n: "It said it then. The kitchen. Not out loud; it didn't have a voice; it said it the way a warm room says it at the end of a long night, through the soles of your feet and the backs of your knees, through your eyes stinging in the heat after the cold. *You could just sit down. Nobody's talking about you here. Nobody's ever going to talk about you again. Sit down. Have a slice. Somebody'll put on a song.*" },
    { n: "Haechan's hand was on the back of the stool. Solar watched it. It was the hand with the guitar pick in its pocket, the hand with the straight pink scar across the palm from the rope. It tightened on the back of the stool." },
    { s: 'haechan', f: 'neutral', t: "...Sol." },
    { s: 'solar', f: 'neutral', t: "Yeah." },
    { s: 'haechan', f: 'neutral', t: "I'm not going to ask you to sit down with me. I want you to know I'm not going to. I want it on the record that I could have and I'm not." },
    { s: 'haechan', f: 'sad', t: "Because I want to. I want to so bad. I want to sit on this stool and you sit on that one and we eat this terrible pizza and nobody ever finds us. That's what I want. I'm saying it out loud. I'm wanting it so loud you can hear it. And I'm not asking." },
    { n: "He took his hand off the stool. One finger at a time, the way Akihiko had taken his off her wrist on the ice in July. He put it in his pocket with the pick." },
    { n: "Behind them, in the door frame, Akihiko breathed out." },
    { n: "The radiator stopped knocking. The Christmas lights stopped blinking, on, and stayed on. The kitchen was a degree colder; Solar felt it on the back of her neck; disappointed, and patient." },
    { n: "And the back door was there. Across the kitchen. The kitchen door to the back porch, the one they'd come in by, except that now there was snow on the other side of its little window, real snow, coming down in the porch light, and the light was on, and through the glass, at the bottom of the porch steps, a path going away across a yard in the snow toward the street, toward the corner where you turned for Walnut Avenue. Home. The long way round." },
    { flag: 'eqx-door-R3' },
    { n: "Haechan looked away. Out of the window over the sink. Akihiko looked at the floor. Minji lowered her camera and turned it off and put the lens cap on, and held it against her chest." },
    { choose: [
      { t: "(Open the back door. Go out onto the porch.)", tally: { 'doors.R': 1 }, flag: 'eqx-home-R3', then: [
        { n: "She went across the kitchen and opened the door and the cold came in round her like water, real cold, Syracuse cold, the kind that made the inside of your nose hurt, and she stepped out onto the porch in her school shoes into the snow." },
        { n: "It was snowing on her. Real snow. On her hair, on her face. The porch light buzzed. Down the street, very faint, somebody's car alarm. Somebody laughing a long way off. A bus." },
        { n: "She stood on the porch with her hand on the rail and the snow coming down, for three breaths, four; and on the fifth she was standing at the foot of the stage-light hall in the Well on the black ice with her hand on nothing, and her hair was wet, and there was snow on her shoulders, melting." },
        { n: "Behind her the three of them were standing exactly where they'd stood. In the snow. On the ice. Haechan looked at her shoulders, at the snow on them. He didn't say anything. He brushed it off, carefully, with the back of his hand, the left shoulder, then the right, the way you'd brush snow off somebody you'd waited for at a bus stop." }
      ] },
      { t: "(Go and stand with Haechan. Put your hand in his pocket, over his.)", flag: 'eqx-away-R3', then: [
        { n: "She went round the island and stood beside him at the window and put her hand in his jacket pocket, over his hand, over the pick. He didn't look at her. His fingers turned over under hers and held on." },
        { n: "When the door was gone they were standing on the ice in the snow, the two of them, with their hands in one pocket, and Minji, behind them, had her camera up again and wasn't filming anything." }
      ] },
      { t: "(Look at the snow through the little window. Just look.)", flag: 'eqx-watch-R3', then: [
        { n: "She looked. The porch light. The snow. The path. The corner. She let it all go into her and sit there, the way she'd let Hanni's laugh go into her through the door in July, and she didn't go to it, and she didn't turn away from it." },
        { n: "When it faded it faded slowly, the way a window fades when the lights come on inside a room, the snow going first, then the path, then the porch light last of all." }
      ] }
    ] },
    { n: "On the way up the rope Akihiko climbed last. At the top, in the red courtyard, he stopped beside her, breathing hard, and looked back down the dark shaft." },
    { s: 'akihiko', f: 'neutral', t: "...Mine was the boxing gym. In this town. The one by the station. Shinji was on the bench by the ring with his coat on, the way he used to sit. Except he wasn't. The bench was just there. With the dent in the cushion." },
    { ifFlag: 'dead.shinjiro', then: [
      { s: 'akihiko', f: 'sad', t: "I sat down on it. I sat there for twenty minutes. It was so warm. It said I could stay. Fuuka had to call me out three times." },
      { s: 'akihiko', f: 'sad', t: "I saw his face when he took his hand off that stool. I want you to know I saw it. I couldn't have done it. I didn't." }
    ], else: [
      { s: 'akihiko', f: 'neutral', t: "It said I could stay there. With him on the bench forever. I nearly did. Then I came up the rope and he was in the kitchen burning Ken's toast, and I didn't need the bench." },
      { s: 'akihiko', f: 'neutral', t: "I saw his face when he took his hand off that stool. Don't tell him. He'd make it a thing." }
    ] }
  ] },

  { id: 'eqx-low-tide', date: '11/6', slot: 'late', consumes: true, title: 'where nobody dies', place: 'The Well · The Second Hill', time: 'The Red Hour',
    cast: { solar: 'Solar', yunjin: 'Yunjin', haechan: 'Haechan', jungwon: 'Jungwon', fuuka: 'Fuuka', chenle: 'Chenle' },
    scene: [
    { place: 'Port Island · Harbor', time: 'Evening', bg: 'harbor', music: 'night' },
    { n: "Yunjin had been going to the harbor every night since the bridge." },
    { n: "Not to watch the tide stop. She'd done that in April, in May, in the red, a dozen times, climbing out the laundry window with her tide table folded in her back pocket. She went now in the evening, before the hour, at the low water, and stood on the end of the pier where the last fisherman used to stand before he wasn't there anymore, and looked at the mud." },
    { n: "Solar found her there on Saturday at nine. Hanni had told her where. Hanni knew where everybody was, all the time, now; she kept it in her head the way she used to keep the rota on the corkboard." },
    { s: 'yunjin', f: 'neutral', t: "Low water's at eleven-fifty tonight. Here. At home it's twelve-forty. Same as always. Fifty minutes behind." },
    { s: 'yunjin', f: 'neutral', t: "Chenle says there's a door on the Second Hill. Since Tuesday. On the mud. He says it goes to a garden." },
    { n: "She didn't look round. She didn't have to say whose garden. Solar knew from her shoulders." },
    { s: 'yunjin', f: 'serious', t: "I want to go down tonight. With you. I know where the tide is. I'm the only one who knows where the tide is. Mitsuru said yes if you say yes. Say yes, Sol." },
    { n: "She hadn't asked for anything for herself since April. Not really. Not once that she hadn't turned into a joke before it landed. Not when the girls came, not when they moved into the boarding house, not when Mrs. Oka asked them to stay together and she was the only one who didn't say *we will*. Solar looked at the back of her neck, at her hair scraped up, at her hands in the pockets of Haechan's old jacket, and said yes." },
    { place: 'The Well · The Second Hill', time: 'The Red Hour', bg: 'eq-well-4', music: 'eerie' },
    { dark: true },
    { n: "The Second Hill was the tide. It always would be. The mud going away forever under the red moon, ribbed and shining, the boats lying on their sides in it with their ropes slack, and on either side of the long road across it, a long way off, the sea standing up in two walls. Still. Glass. Red-lit from inside. And in the walls, far in, things hanging in the water that breathed." },
    { n: "Jungwon and Haechan walked on either side of Yunjin. Not her. Yunjin. They'd done it without being told, the way they did it on either side of Solar on the First Hill; the two of them who'd lived in the house at the top of the hill above a harbor like this one, a long time ago, in the life where she'd met them." },
    { n: "The door was a kilometer out on the mud. Chenle called them to it. A door in a stone wall. The wall going off in both directions for a few meters and then simply stopping, standing in the mud on its own, old gray stone with moss in the joins and a tiled cap along the top. And in the wall a garden door. Wooden. Low. Open." },
    { n: "Yunjin went through it first. Nobody stopped her." },
    { place: 'The Well · A Garden at Low Tide', time: 'The Red Hour', bg: 'epi-s-garden-night', music: 'world-strangers' },
    { n: "It was a garden at night above a harbor. A garden Solar had walked through in her socks at two in the morning, in another life, to sit on a stone at the bottom of it and look at the water. The pines. The stone lantern. The gravel raked in lines that nobody had walked on. The pond with the koi in it, asleep, white and orange shapes hanging very still in the black water. The lit windows of a house above, every one of them lit, yellow, warm. And below the garden wall, the harbor, at low tide, the mud going out under the lights of the city across the bay, the cranes, the long bridge." },
    { n: "Nobody was in it. Nobody was in the house. Every window was lit and every room behind every window was empty; Solar could see from the gravel path. The kitchen, the lamp on, the rice cooker's little red light, nobody at the table. The stairs. The landing. Her room, at the top, with the light on, and the bed made." },
    { n: "It was so quiet. There were no cars on the hill road. There were no men at the gate. There was no one counting anything. There was no one waiting at the bottom of the stairs for anyone to come home." },
    { n: "Yunjin stood in the middle of the gravel path with her hands at her sides and looked at it." },
    { n: "And the tide said it. It came up out of the mud below the garden wall the way warmth comes up out of a bath, soft, all at once, all round them. Not words. Just the shape of words, in the dark, pressing on them from every side the way water presses. *Stay. Stay here. Here, nobody dies. Nobody's ever going to die here. Sit down by the pond. Turn your light off. Sleep. Nobody will ever die again.*" },
    { n: "Yunjin's shoulders went down." },
    { n: "Solar saw it happen. Like a breath going out of her that she'd been holding since December. Since a riverside, in another life, with her hands closing on nothing. Her shoulders went down and her head went back a little, and her eyes closed, and she swayed, standing on the gravel, the way you sway at the edge of sleep on a train." },
    { s: 'yunjin', f: 'sad', t: "...It's true. Isn't it. Nobody dies here." },
    { s: 'yunjin', f: 'sad', t: "I can feel it's true. It's not lying. Nobody's going to die in this garden. Not ever. I could sleep with the light off every night for the rest of my life." },
    { n: "She sat down. On the stone by the pond. The flat one at the edge where you could sit with your feet over the water. Solar's stone. She sat down on it and drew her knees up and put her arms round them and looked at the koi asleep in the black water, and her face was the most peaceful thing Solar had seen in this year." },
    { n: "Haechan took a step toward her. Jungwon put a hand out across his chest without looking, and stopped him; and Haechan stopped; and both of them stood on the gravel and didn't go to her, and Solar understood, looking at their faces, that it was the hardest thing either of them had done since the rope." },
    { n: "Because it was hers. Whatever she did on that stone, it was hers." },
    { n: "Solar didn't go either. She stood on the path with her fists closed at her sides and her nails in her palms and let it be Yunjin's. It cost her. She felt exactly what it cost: the word, *please*, in her mouth, the shape of it, sweet, and her swallowing it." },
    { n: "Yunjin sat on the stone a long time." },
    { n: "Then she opened her eyes and looked at the house. At the lit windows. At every room with nobody in it." },
    { s: 'yunjin', f: 'neutral', t: "...Nobody dies here because nobody's here." },
    { n: "She said it to the koi. Very quietly. As if she'd been doing a sum for a long time and the answer had just come out right, and she didn't like it." },
    { s: 'yunjin', f: 'neutral', t: "That's why. That's the only reason. It's not safe. It's empty. Nobody dies in an empty house." },
    { s: 'yunjin', f: 'serious', t: "I don't want an empty house. I want the house with the people in it. I want the one where I'm scared every night and the light's on and somebody's counting and somebody's at the bottom of the stairs and somebody might not come home. I want them. I want all of them and I want to be scared." },
    { n: "She stood up off the stone." },
    { s: 'yunjin', f: 'serious', t: "No. You hear me? No. I'm not staying where nobody dies. I'm going where they are." },
    { n: "The garden went cold." },
    { n: "All at once, the way a bath goes cold when someone pulls the plug. The lit windows of the house went out, all of them, every one, from the top floor down, *click, click, click*, like someone walking through it turning off the lights behind them. The koi in the pond turned over, one by one, white bellies up, and floated. And below the garden wall the tide came back." },
    { n: "Not in. Up. The standing water out on the mud fell over at once, both walls, a long roar in the dark like a building coming down, and came across the flats toward the garden in a black wave with the red light in it, and in the wave, coming with it, hands. White masks. Mothers' faces. *Give me one, give me one, give me one.*" },
    { s: 'fuuka', f: 'surprised', t: "The water's moving! Solar, the whole hill— get out of there— get *out*—" },
    { s: 'jungwon', f: 'serious', t: "*Hyeonmu!*" },
    { s: 'haechan', f: 'serious', t: "*Dalnim!* Sol, behind me—" },
    { n: "The wave came over the garden wall. The pines went under. The stone lantern went under. Solar went under. Black, cold, salt, red light, and hands on her, white fingers on her wrists, her ankles, her hair, pulling, and she couldn't find the surface, and she couldn't find her temple with her fingers, and the voices in the water were all her mothers' voices at once saying *stay, stay, it's only me*—" },
    { n: "Somebody walked into the water after her." },
    { n: "Not swam. Walked. Solar felt it before she saw it: somebody walking, on the bottom, in the black, against the pull, the way you'd walk into the sea in winter to fetch a child back from it, step after step, not hurrying, the water to her waist and then her shoulders and then over her head. A hand found Solar's collar. Closed on it. Held." },
    { n: "Yunjin. Under the water, with her eyes open, her hair come loose and floating, and her other hand up at her own temple, two fingers, the way she'd seen Solar do it a hundred times on the stairs of the Well and in the courtyard and on the bridge. Her mouth moved. Under the water. A name." },
    { n: "Light came up through the black water like a lamp coming on at the bottom of a well." },
    { n: "Something stood behind Yunjin in it. A girl. Not a girl. Tall, taller than the water, in the plain undyed white of mourning, barefoot, her hair loose to the backs of her knees, and in one hand a staff of willow and in the other a sprig of three flowers, white and red and blue, held the way you'd hold a candle through a dark house. Her face was calm. It was the face of someone who had walked a very long way, down, into the place where nobody comes back, to bring somebody home, and was going to walk all the way back up carrying them." },
    { n: "*" + PERSONA.yunjin + "*." },
    { n: "The flowers opened. The water let go." },
    { n: "It let go all at once, the hands sliding off Solar's wrists and ankles like gloves pulled off, the masks falling away into the dark, and the wave went back, back over the wall, out across the mud, and lay down flat, and was a tide again; and Solar was on her knees on the gravel in the dark garden coughing salt water, and Yunjin was standing over her, soaked to the skin, with her hand still locked in the back of Solar's collar, and the tall white figure behind her was folding itself away into the red air like a sheet into a drawer." },
    // CG: eqx-bari — a young woman soaked to the skin standing in a dark seaside garden at night, two fingers raised to her temple, a tall serene figure in plain white mourning robes with a willow staff and three flowers rising behind her out of black water.
    { join: 'yunjin' },
    { s: 'yunjin', f: 'surprised', t: "...Oh." },
    { s: 'yunjin', f: 'neutral', t: "...Oh. Is that what it's like? That's what it's like? You've been doing that for two years?" },
    { s: 'solar', f: 'sad', t: "...Yeah." },
    { s: 'yunjin', f: 'happy', t: "That's insane. That's so insane, Sol. You're insane. All of you." },
    { n: "She sat down on the gravel beside her, hard, soaked, shaking, laughing, and put her head down on Solar's wet shoulder, and Solar put her arm round her, and Haechan and Jungwon stood over them dripping, with their Personas folding away behind them, and looked at each other over the two girls' heads, and Jungwon took off his blazer, which was soaked too, and put it round Yunjin anyway." },
    { n: "The house above them was dark. Every window. Across the dark garden, at the top of the gravel path, there was a back door standing in the dark wall of the house, a kitchen door; and in it, behind its frosted glass, one lamp was on. One. Low. The kind you leave on in a kitchen for someone who's going to come home late." },
    { flag: 'eqx-door-S3' },
    { n: "Haechan looked away, out at the harbor. Jungwon took his watch out of his pocket, and looked at it, and put it face down on the gravel. Yunjin, on Solar's shoulder, didn't lift her head." },
    { s: 'yunjin', f: 'neutral', t: "...Go on. It's your door, not mine. I already picked." },
    { choose: [
      { t: "(Go up the path. Put your hand on the kitchen door.)", tally: { 'doors.S': 1 }, flag: 'eqx-home-S3', then: [
        { n: "She went up the gravel path in her wet socks. The lamp behind the frosted glass didn't flicker. She put her hand flat on the wooden frame of the door, beside the glass, the way you'd put your hand on a horse." },
        { n: "It was warm. From the inside. As if somebody had been standing with their back against it." },
        { n: "From the other side, very faintly, the sound of a kettle. Not humming. Just on. Coming up to the boil the ordinary way, the way a kettle does at four in the morning in a kitchen where somebody can't sleep. Then a cupboard door. Then two cups set down on wood." },
        { n: "Two cups. She'd remember that. Then the lamp went out, and her hand was flat on a stone wall in the mud on the Second Hill under the red moon, cold, wet, with moss in the joins." }
      ] },
      { t: "(Stay on the gravel with Yunjin. Hold on to her.)", flag: 'eqx-away-S3', then: [
        { n: "She stayed. She held on. Yunjin's hair was wet against her neck and she was still shaking, and Solar held her until she stopped, and didn't look up at the lamp." },
        { n: "When she did look up it was gone, and they were sitting on the mud in the red with the wall standing alone beside them, and Yunjin was asleep on her shoulder, completely, the way you only sleep when somebody's holding on." }
      ] },
      { t: "(Watch the lamp. Just watch it.)", flag: 'eqx-watch-S3', then: [
        { n: "She watched it. The one lamp. Low. Left on. She didn't go to it and she didn't look away, and it didn't go out; it faded, slowly, the way a lamp fades in the morning when the window gets light, until it was the red moon on frosted glass, and then a wall." }
      ] }
    ] },
    { s: 'chenle', f: 'neutral', t: "...Sol. Yunjin. You're both on my screen again. You're both— there's two of you on my screen now. Yunjin's a dot now. She's a dot like you guys." },
    { s: 'yunjin', f: 'neutral', t: "I'm a dot. Chenle says I'm a dot." },
    { s: 'yunjin', f: 'happy', t: "...I'm going to sleep with the light on tonight. I'm going to sleep with every light on. I'm going to be so scared." }
  ] },

  { id: 'eqx-every-hill', date: '11/10', slot: 'after', consumes: true, title: 'on every hill', place: 'Gekkoukan High · Nurse’s Office', time: 'After School',
    cast: { solar: 'Solar', edogawa: 'Mr. Edogawa' },
    scene: [
    { bg: 'gekkoukan-nurse-office', music: 'mystery' },
    { n: "Mr. Edogawa had been reading the tale for weeks." },
    { n: "Everybody knew. He'd taught it in every one of his classes since September, the third-years and the first-years both, whether it had anything to do with the syllabus or not, which it didn't. The sun and the moon. The golden rope. The tiger. He'd chalked the hills on the blackboard in a row and numbered them and stood in front of them with his pointer for twenty minutes without saying anything while 3-F looked at each other." },
    { n: "He'd asked Solar to come by the nurse's office after school. Where he kept his things. The skulls on the shelf, the jars, the incense, the faint smell under everything of something dried and old." },
    { n: "He was sitting at the desk with five books open in front of him in a fan. Old ones. One of them in Korean, hand-copied, the paper gone brown. He didn't look up when she came in." },
    { s: 'edogawa', f: 'neutral', t: "Ah. Solar-kun. Sit, sit. Mind the jar. That one's only a lizard." },
    { s: 'edogawa', f: 'neutral', t: "You'll know this one, I think. The sun and the moon. You'll have heard it from your mother. Mothers always tell it. Ehehe. It's a mother's story. It's the story a mother tells to frighten the children into keeping the door shut." },
    { s: 'solar', f: 'neutral', t: "I've heard it." },
    { s: 'edogawa', f: 'neutral', t: "Everyone's heard it. Nobody's listened to it. That's the trouble with tales. You hear them so young you never actually listen." },
    { n: "He turned one of the books round on the desk so she could see. A woodcut. A road over hills. A woman with a basket on her arm. And on every hill, at the side of the road, a shape crouching, waiting, with its paws folded." },
    { s: 'edogawa', f: 'neutral', t: "Here. Listen. *Give me one rice cake and I won't eat you.* And she gives it. And on the next hill, *give me one rice cake and I won't eat you.* And she gives it. On every hill. Solar-kun. *Every* hill." },
    { s: 'edogawa', f: 'neutral', t: "Everybody thinks the story's about the tiger eating the mother. It isn't. The tiger could have eaten her on the first hill. Why didn't it? Why ask? Why wait for her to give it something, one at a time, over and over, hill after hill?" },
    { n: "He looked up at her over his glasses. For a second, the silly man was gone out of his face entirely, and what was left in it was someone very old and very interested, and frightened." },
    { s: 'edogawa', f: 'neutral', t: "Because it can't take. It can only be given. That's the rule of it. It can only have what she hands over. One at a time. Every rice cake makes her a little lighter and it a little heavier. And by the last hill there's nothing left in her to say no with, and she's already given it the habit of yes, and then it doesn't need to ask anymore." },
    { s: 'edogawa', f: 'neutral', t: "Every hill. Every yes. You see? The eating is the end of it. The asking is the story." },
    { n: "Solar's hands were cold on her knees. Outside the window, in the courtyard, the plank lid on the well sat crooked under its sign. *Maintenance. Do not lean.*" },
    { s: 'solar', f: 'neutral', t: "Why are you telling me this?" },
    { s: 'edogawa', f: 'neutral', t: "Because you're the only one in this school who's listening, Solar-kun. I can tell. Everyone else hears it like a bedtime story. You hear it like a set of instructions." },
    { n: "He shut the book. He patted it. And the silly man came back into his face, all at once, like a coat put back on." },
    { s: 'edogawa', f: 'neutral', t: "Ehehe. And now I've frightened a student. The principal will have words. Never mind. I've found someone who knows the old version. The very oldest. A lady down by the river, very kind, keeps a boarding house, has a persimmon tree. She says there's a part nobody tells. A part about the tree. The children in the tree." },
    { s: 'edogawa', f: 'neutral', t: "She's asked me to tea. To hear it. Isn't that marvelous? Tuesdays. She says I can come every Tuesday until I've heard all of it. She says it's a long part. She says I'll want to stay." },
    { n: "Solar's whole body went cold. From the scalp down. The way it went cold at the top of the Well." },
    { choose: [
      { t: "Don't go. Mr. Edogawa. Please don't go to that house.", flag: 'eqx-edogawa-warned', then: [
        { n: "He looked at her over his glasses. For a moment the old frightened interested face was back." },
        { s: 'edogawa', f: 'neutral', t: "...You've heard the tale, then. Properly. Ehehe. Good girl." },
        { n: "Then he smiled, and gathered his books, and patted her shoulder on the way past to the door, the way you'd pat a child who'd told you there was a monster under the bed." },
        { s: 'edogawa', f: 'neutral', t: "It's only tea, Solar-kun. It's only a story. What's the worst that could happen at tea?" }
      ] },
      { t: "Ask her what happens to the children in the tree.", then: [
        { s: 'edogawa', f: 'neutral', t: "Oh, I shall. I shall. That's exactly what I shall ask. I'll tell you on Wednesday." },
        { n: "He wrote it down. On a slip of paper. *Ask: children / tree.* He tucked it into the Korean book, between the brown pages, and put the book into his bag." }
      ] }
    ] },
    { n: "On the blackboard in the empty classroom across the hall, as she passed it on her way out, the row of chalk hills from September was still there. Somebody had drawn a tree beside the last one. A small one. In different chalk. With something hanging in it." }
  ] },

  { id: 'eqx-door-hoax-3', date: '11/13', slot: 'late', consumes: true, title: 'the seat moved back', place: 'The Well · The Third Hill', time: 'The Red Hour',
    cast: { solar: 'Solar', jungwon: 'Jungwon', jihoon: 'Jihoon', yunjin: 'Yunjin', fuuka: 'Fuuka', chenle: 'Chenle' },
    scene: [
    { bg: 'eq-well-5', music: 'mystery' },
    { dark: true },
    { n: "The static on the Third Hill was louder in November. It came out of the phones on the floor of the long hall and the windows full of white snow and the lockers with their vents still breathing flour, a constant hiss, so that you had to talk over it, and after an hour your throat hurt." },
    { n: "Jungwon and Jihoon walked on either side of her. One at her side, one at her back. Always. Solar had stopped noticing they did it, and then noticed again tonight, because of the way Yunjin, walking ahead with the new light in her, kept glancing back at the three of them and grinning to herself like she'd been let in on a joke." },
    { s: 'yunjin', f: 'happy', t: "You guys are like a little parade. You know that? A little very tense parade." },
    { s: 'jihoon', f: 'neutral', t: "We're a security detail." },
    { s: 'jungwon', f: 'neutral', t: "We're not anything. We're walking." },
    { n: "The door was in the gym." },
    { n: "Chenle called them to it, at the end of the hall, where the double doors to the Hanlim gym stood open, and through them, the gym. Hanlim's. With every light on. The bleachers pulled out. The flags of the classes hanging from the rafters. The scoreboard dark. The varnished floor shining under the long white lights, the court lines on it red and blue and yellow, and on the floor, at center court, a single folding chair." },
    { place: 'The Well · A Gym at Midnight', time: 'The Red Hour', bg: 'epi-h-gym-midnight', music: 'eerie' },
    { n: "Nobody was in it. Nobody in the bleachers. Nobody at the scorer's table. Nobody watching." },
    { n: "Jihoon stopped in the doorway. He stood there with his hands in his hoodie pocket, where he kept a rice ball gone to stone and a pharmacy bag with cough drops in it, and looked at the empty bleachers rising up into the lights, row after row, and Solar heard him breathe out." },
    { n: "It said it. Here, in the static. *Nobody's watching. Nobody's ever going to watch you again. Sit down in the chair. Fall all you like.*" },
    { s: 'jihoon', f: 'neutral', t: "...It's so good. That's the thing. Isn't it. That's what nobody tells you about this place. It's so good." },
    { s: 'jihoon', f: 'neutral', t: "No forum. No comments. No hearing. Nobody in the bleachers with their phone out. I could walk out there and sit in that chair and fall apart in the middle of the court and nobody would ever, ever see." },
    { n: "He took a step onto the floor. His sneaker squeaked on the varnish. The sound went up into the empty bleachers and didn't come back." },
    { n: "Jungwon didn't say anything. Solar watched him not say it. He was standing in the doorway with his hands at his sides and his face perfectly still, looking at Jihoon on the gym floor, and she could see the words in his throat, *come back*, and see him swallow them." },
    { n: "Jihoon took another step. Then he stopped, and turned round, and looked at the two of them in the doorway. At Jungwon." },
    { s: 'jihoon', f: 'neutral', t: "...You're not going to say it." },
    { s: 'jungwon', f: 'neutral', t: "No." },
    { s: 'jihoon', f: 'neutral', t: "You want to. I can see it. Your face is doing the thing." },
    { s: 'jungwon', f: 'neutral', t: "My face is not doing anything." },
    { s: 'jihoon', f: 'happy', t: "...Man. You're watching. You're standing right there watching me. Both of you." },
    { n: "He laughed. It came out of him surprised. He looked up at the empty bleachers, all those rows, all those lights, and then back at the doorway, at the two people standing in it, watching him with their faces doing nothing." },
    { s: 'jihoon', f: 'neutral', t: "Two's enough. Turns out. I don't need a whole gym. Two's a lot." },
    { n: "He walked back across the floor to the doorway and stood in it beside Jungwon, shoulder to shoulder, and turned round and looked at the chair at center court, alone, under the lights; and the static went quiet, sulky, the way a room goes quiet when someone's lost an argument." },
    { n: "And the doors on the far side of the gym opened." },
    { n: "The fire doors, at the end of the court, under the dark scoreboard. Pushed open from outside onto the night. Snow. A parking lot in the snow with the lamps on. And in the parking lot, close to the doors, a car. A silver one, a family car, with its engine running, its headlights on, the exhaust smoking white in the cold, and its passenger door open." },
    { n: "Solar knew the car. She'd ridden in it her whole life, in another life, in the back seat and then the front, with her mother at the wheel saying *seatbelt* before the engine was even on." },
    { flag: 'eqx-door-H3' },
    { n: "Jihoon looked at the floor. Jungwon looked at the bleachers. Yunjin looked at Solar, once, and then away, at the flags in the rafters." },
    { choose: [
      { t: "(Go across the court. Get into the car.)", tally: { 'doors.H': 1 }, flag: 'eqx-home-H3', then: [
        { n: "She walked across the court. Past the chair. Out through the fire doors into the cold, real cold, snow on her face, and across the lot to the car, and got into the driver's seat." },
        { n: "The seat was all the way back." },
        { n: "That was the thing she'd remember. Her feet didn't reach the pedals. The seat was pushed all the way back as far as it would go, the way her mother always pushed it the second she got in, every time, after Solar or her father had driven it, *what have you done to my seat*. Her mother's seat. Her mother had been in it. Her mother's handbag was on the passenger seat, open, the wallet showing, the phone face down, as if she'd only just put it down to drive out somewhere fast, to look for somebody." },
        { n: "The heater was on. The radio was on, low. A Korean station, a man reading the traffic, the way it was always on in that car. Solar put her hands on the wheel. It was warm where somebody's hands had been." },
        { n: "Then it was cold, and it was a wall of static, and she was standing on the Third Hill with her hands out in front of her holding nothing, and Jungwon was beside her, and he didn't say anything, he only took her two hands down from the air, gently, and held them in his." }
      ] },
      { t: "(Stay in the doorway with the two of them.)", flag: 'eqx-away-H3', then: [
        { n: "She stayed in the doorway between them. Jihoon's shoulder on one side, Jungwon's on the other. One at her side, one at her back. The engine ran, out in the snow; she could hear it; the radio, faint." },
        { n: "When it went, the headlights went first, and then the sound, and then the snow." }
      ] },
      { t: "(Watch the car. Just watch it.)", flag: 'eqx-watch-H3', then: [
        { n: "She watched it. The exhaust in the lamplight. The open passenger door. The handbag on the seat. She let it all sit in her, and didn't go, and didn't turn away." },
        { n: "Right at the end, before it went, somebody reached across from the driver's side, in the car, in the dark, and pulled the passenger door shut. Just an arm. A sleeve. Quick and annoyed. The way you shut a door somebody's left open in the cold." }
      ] }
    ] },
    { n: "On the way back along the hall, in the static, Jihoon walked a step behind her and Jungwon a step to her side, the way they always did, and after a while Jihoon reached forward without saying anything and touched the top of her head, once, passing, like a doorframe in a house you used to live in." }
  ] },

  { id: 'eqx-1122', date: '11/22', slot: 'evening', consumes: true, title: 'the tree by the well', place: 'The Well · The Tree', time: 'The Red Hour',
    cast: { solar: 'Solar', mitsuru: 'Mitsuru', akihiko: 'Akihiko', aigis: 'Aigis', yunjin: 'Yunjin', haechan: 'Haechan', hanni: 'Hanni', hyein: 'Hyein', fuuka: 'Fuuka', chenle: 'Chenle',
      'jaesang-runners': 'Jaesang', 'taesang-strangers': 'Taejoon', 'kim-dad': 'Mr. Kim', 'solji-runners': 'Solji', 'miyeon-strangers': 'Miseon', 'kim-mom': 'Mrs. Kim' },
    scene: [
    { place: 'Gekkoukan High · Courtyard', time: 'Late Night', bg: 'eqx-courtyard-well-night', music: 'fullmoon' },
    { n: "The fathers stayed at the top this time. They'd promised. Jaesang had promised for all three of them, standing in the lounge with his hand on Taejoon's arm, and Taejoon had let him, and Mr. Kim had said *we'll hold the rope, we'll hold the rope, somebody has to hold the rope*." },
    { n: "So they held it. The three of them, at the lip of the well in the red courtyard, in borrowed coats, with Mitsuru's climbing line round their waists and their hands on it and their feet braced on the paving, and every one of them looking down into the dark." },
    { n: "Hanni and Hyein were going down." },
    { n: "Mitsuru hadn't wanted it. Hanni had stood in front of her in the command room with her arms folded and said *you need people who can carry. Three people. On stretchers. Up a rope. You need hands. I carry. That's what I do.* And Hyein had stood beside her and hadn't said anything, and hadn't needed to; she'd brought the stretchers, rolled, three of them, sewn out of two Kirijo tarps and a bolt of canvas from the craft shop by the station, double-stitched at every seam, the handles wrapped." },
    { s: 'hyein', f: 'neutral', t: "I made them on Saturday. They'll hold. I tested them on Junpei." },
    { n: "Aigis walked beside Hyein to the lip. Close. She'd walked beside Hyein everywhere since April, every full moon; she'd asked Mitsuru to be in Hyein's building and Mitsuru had said yes at once, and nobody had ever said why out loud." },
    { s: 'aigis', f: 'neutral', t: "Hyein. If anyone falls into anything tonight, I would like to be asked first." },
    { s: 'hyein', f: 'neutral', t: "Nobody's falling into anything." },
    { s: 'aigis', f: 'happy', t: "Good. Then I won't need to be asked. But I would like you to know that I would like it." },
    { s: 'akihiko', f: 'neutral', t: "...Eighty-four twelve. At the lip." },
    { place: 'The Well · The Tree', time: 'The Red Hour', bg: 'eq-well-7', music: 'eerie' },
    { dark: true },
    { n: "The Tree grew down." },
    { n: "Below the Road Home, below the last hill and the last flight of steps with the shoes on them, the Well opened out into a dark so big it didn't have walls, and through the middle of it, from somewhere far above, from the floor of the world, a persimmon tree was growing down. Upside down. Its trunk going down into the dark as thick as a house. Its roots overhead, a ceiling of roots, hanging, dripping, so many and so tangled that they made a sky. Its branches spreading out below them in every direction, and on every branch, fruit." },
    { n: "The fruit were faces." },
    { n: "Orange. Ripe. Soft. Hanging by their stems from the branches the way persimmons hang in November when the leaves have gone, heavy, glowing, a thousand of them. Each one with a face on it. Eyes shut. Mouths moving. Whispering. And the ones that had fallen from the branches lay on the ground under the tree, split, soft, and the faces on those were still whispering too, into the dirt." },
    { n: "*Stay. Stay. It's warmer here. Stay one more day.*" },
    { n: "Solar stepped on one before she knew what it was. It went under her shoe with a soft wet give. It whispered her name." },
    { s: 'fuuka', f: 'sad', t: "Everything's talking. Everything down there is talking. I can't— Chenle, can you hear them? Can you hear the mothers?" },
    { s: 'chenle', f: 'sad', t: "Under the water. They're under the water first. There's water. There's a lot of water and then the tree goes into it." },
    { n: "There was water. The ground under the tree ended at the edge of it: a floor of water, still, black, perfectly flat, going away from the roots in every direction like a lake in a cave, so still it didn't look like water. It looked like glass. It looked like a floor. Chenle said it would hold them, it had held him in October; and it did; Solar stepped out onto it and it held, cold under her shoes, hard, and under her shoes, in it, looking up, was her own face." },
    { n: "Everyone's. Every one of them had a reflection in the black glass under their feet, walking upside down beneath them step for step, looking up at them. And the reflections were talking." },
    { n: "Akihiko's said *hold on* in Akihiko's voice, quietly, over and over, *hold on, hold on, don't let go*. Haechan's didn't say anything; it walked under him with its hands in its pockets and looked up at Solar's, under her, and smiled. Yunjin's looked away from her; it had nothing left to ask her. Solar's, under her own feet, said in her own voice, perfectly reasonably, *be who they need. Here. All of them at once. You can. You're so good at it.*" },
    { n: "And under Hyein, in the black glass, the reflection didn't have her face. It had a woman's. Older. Softer. The face from the voicemail. And it spoke in her mother's voice." },
    { n: "*Hyein-ah. Hyein-ah, it's Mom. Why do you never pick up. I'm right here. I'm right under you, sweetheart. It's so cold down here. Open the door. Open the door for Mom.*" },
    { n: "And there was a door. In the water. Under Hyein's feet. A plain white front door lying flat in the black glass like something seen through ice, with a brass latch on it, the latch turned up toward her, toward her hand." },
    { n: "Hyein stopped walking." },
    { ifRank: { hyein: 6 }, then: [], else: [{ ifRank: { hanni: 6 }, then: [], else: [{ flag: 'eqx-water-door' }] }] },
    choiceFlag('asks.hyein', 'yes', 'eqx-water-door'),
    { ifFlag: 'eqx-water-door', then: [
      { n: "Hanni was at the back. With the stretchers. Twenty meters back on the glass, carrying two of them rolled on her shoulder. She saw Hyein stop. She dropped the stretchers and ran, and the glass under her feet was too smooth to run on." },
      { n: "Hyein knelt down. On the glass. Over the door. Her hand went out to the latch the way it had gone out to the latch on the dorm's front door on the twenty-eighth of April, slowly, as if somebody else were moving it. Her fingers went through the surface of the black glass like it was water, because it was water, and closed on the brass." },
      { n: "*That's it*, said her mother, under her. *That's my girl. That's my good girl. It's only me.*" },
      { n: "She turned it. All the way. Nobody tackled her. Hanni was ten meters away and screaming her name and slipping on the glass." },
      { n: "The door opened downward, into the dark under the water. And something came up out of it and took Hyein by the wrist." },
      { n: "It wasn't a hand. Solar saw that much. White. Long. A sleeve with nothing in it, wet, and at the end of it something that closed on Hyein's wrist the way a trap closes. And Hyein went in. All at once. Headfirst, down through the open door into the black, with her other hand flung up, and the glass closed over the place where she'd been like a mouth closing, smooth, still, and under it Solar could see her, going down, her hair streaming up, her eyes open, her mouth open, the white thing on her wrist pulling her down and down into the dark under the tree." },
      { n: "Aigis didn't ask." },
      { n: "She'd said she'd like to be asked first. She didn't wait to be. She was already moving when the door opened; she went past Solar on the glass, and dove, straight down through the closing surface after Hyein, without breaking stride, her arms at her sides, as if she were stepping off a curb. She didn't need to breathe. It was the one thing she'd always been sure she was for." },
      { n: "Under the glass Solar watched her go down. Fast. Faster than Hyein, a blue-white shape in the dark water with her hair streaming, reaching; reaching Hyein; her left hand closing on a fistful of the back of Hyein's coat; her right hand on the white thing on Hyein's wrist, prying. Prying it off. One finger at a time. The way Junpei had prised Akihiko's hand off the banister in April. And it came off." },
      { n: "And Aigis turned in the water, and took Hyein in both arms, and threw her." },
      { n: "Up. With everything in her. Hyein came up through the black glass ten meters away like something shot out of the sea, and landed on the surface on her side, hard, and lay there coughing up water, black water, retching it, her whole body jackknifing with it." },
      { n: "Under the glass, the door closed on Aigis." },
      { n: "It closed down on her like a lid. They all saw it. The white door in the black water swinging shut from below with Aigis halfway through it, her arm still up toward the surface, her face turned up toward them, calm, interested, the way it was when she was counting heartbeats on the roof at midnight. And then the door was shut, and she was on the other side of it." },
      { n: "And then the sound." },
      { n: "It came up through the water and through the soles of their feet. Metal. Giving. Not breaking; giving, slowly, the long low groan of steel being folded the wrong way by something very patient, and then a shriek, high, like a car door torn off its hinges, and then the groan again. It went on for a long time. It went on so long that Yukari would have put her hands over her ears, if Yukari had been there. Akihiko did. Haechan had Solar by the arm and she didn't remember him taking it. The metal gave and gave under the black water, and somewhere in it, once, very faintly, Aigis's voice, perfectly level, said something none of them could hear." },
      { n: "Then it stopped." },
      { n: "Things came up through the glass. Slowly. Floating up, the way things float up from a wreck. A ribbon. A white one, gone gray with the water, hemmed so fine you couldn't see the stitches. It came up through the surface without breaking it and lay on top of the black glass, wet, limp, in a curl." },
      { n: "And a hand. Her left hand. Floating up palm first. Torn off at the wrist, the metal of the wrist folded and twisted into the shape of a fist, wires trailing out of it like roots; and the fingers of it still closed, locked, clenched white-knuckled on a fistful of dark wet cloth. A piece of Hyein's coat. The back of it, torn away. Still held." },
      { n: "And round it, coming up through the water and spreading on the surface of the glass, dark, slow, something that wasn't oil. It smelled of copper. It was warm." },
      { flag: ['dead.aigis', 'eqx-true-closed'] },
      { n: "Hanni got to Hyein. She fell to her knees on the glass and dragged her up into her arms, and Hyein was coughing, still coughing, water and something else coming out of her, her eyes wide and blind, and Hanni was holding her so hard Solar heard Hyein's ribs creak." },
      { n: "Hyein's hand found the thing on the glass beside her. Blind. Groping. It found Aigis's hand, locked in her coat, and closed on it, and held it." },
      { n: "And under her, in the black glass, her reflection looked up at her with her mother's face, and her mother's voice said, warmly, *come back in, Hyein-ah. It's warm in here. Your friend's in here. Come back in.*" },
      { n: "Hyein looked down at it. Water was running out of her nose, her mouth. She was holding a hand that had been her friend's." },
      { s: 'hyein', f: 'sad', t: "...No." },
      { n: "It came out of her like the water had. Torn up out of her chest." },
      { s: 'hyein', f: 'serious', t: "No. *No.* You're not her. You were never her. My mom never once sounded that sure I'd open. My mom left me a voicemail that said *why do you never pick up*. She knew I wouldn't. She *knew*. You don't. You don't know anything about her." },
      { s: 'hyein', f: 'serious', t: "I'm not opening it. I'm never opening anything for you again." }
    ], else: [
      { n: "Hyein knelt down. On the glass. Over the door. Her hand went out to the latch slowly, as if somebody else were moving it." },
      { n: "Aigis was at her shoulder. Not touching her. Close enough. Hanni, at the back with the stretchers, had stopped dead on the glass and dropped them and wasn't moving, wasn't running, was only watching, with both her hands over her mouth." },
      { n: "*That's it*, said her mother, under her. *That's my girl. It's only me.*" },
      { n: "Hyein's fingers stopped an inch from the surface." },
      { n: "Solar saw her remember. It went across her face like a light going across a wall. The dorm hall on the twenty-eighth of April. The latch under her hand. The metal warm as skin. A quarter turn. Hanni coming out of nowhere like a car and taking her to the floor and holding on. The sigh behind the door, fond, and then two more knocks." },
      { n: "*Why do you never pick up*, said her mother under the water. *Hyein-ah. Why do you never pick up.*" },
      { s: 'hyein', f: 'neutral', t: "...Because you'd ask me something. You'd ask me to come home." },
      { s: 'hyein', f: 'serious', t: "And I'm not. Not for you. You're not her. My mom never once sounded that sure I'd open. She knew I wouldn't. She left it on voicemail because she *knew*." },
      { n: "She took her hand back. All the way back. Into her lap." },
      { s: 'hyein', f: 'serious', t: "I'm not opening it. I'm not opening anything for you, ever." },
      { n: "Aigis's hand settled on her shoulder. Lightly." },
      { s: 'aigis', f: 'neutral', t: "...May I be asked now? Whether you'd like me here?" },
      { s: 'hyein', f: 'sad', t: "Yeah. Yes. Stay right there." },
      { flag: 'eqx-aigis-lived' }
    ] },
    { n: "The white door in the water began to rise." },
    { n: "Up through the black glass under Hyein, toward the surface, toward her, its latch turning by itself; and the water round it began to move, to boil, white hands coming up through it like weeds, reaching for her ankles, her coat, her hair—" },
    { n: "—and Hyein's hands came up." },
    { n: "Both of them. Empty. The way they came up over a sewing machine, over a bolt of cloth, over Hanni's cardigan in May. And from her fingertips, out of nothing, thread." },
    { n: "Light. Fine as hair. A hundred threads, a thousand, pouring out of her fingertips across the black water the way silk pours off a spool when you drop it, and behind her, out of the red air, a loom. Huge. Standing up out of the water. And at it, a woman, a girl, in a robe the color of the night sky with the stars woven into it, with a shuttle in her hand made of something that shone like the river of stars across a summer sky; and she threw the shuttle, and it went across the water, and the water was woven." },
    { n: "Shut. Like cloth. The door, the hands, the rising black, all of it woven over, under and over, under and over, tight, a weave you couldn't put a needle through, until the floor of water under Hyein was a floor of shining cloth, and the door was gone under it, and her mother's voice was gone under it, and it was quiet." },
    { n: "*" + PERSONA.hyein + "*." },
    // CG: eqx-jiknyeo — a soaked young woman kneeling on a floor of black still water, hands raised and pouring threads of light from her fingertips, behind her a vast loom rising out of the dark and a girl in a star-woven robe throwing a shining shuttle across the water.
    { join: 'hyein' },
    { n: "Hyein stared at her own hands." },
    { s: 'hyein', f: 'surprised', t: "...I sewed it shut. I just sewed a lake shut. With my hands." },
    { place: 'The Well · The Tree', time: 'The Red Hour', bg: 'eq-well-7', music: 'tension' },
    { n: "The Tree woke up." },
    { n: "They felt it before they saw it. The roots overhead shivering all at once like a ceiling about to come down, dripping, and every face on every branch opening its eyes. A thousand eyes. All of them on Hyein. On the one who'd said no." },
    { n: "And the roots came down." },
    { n: "Out of the ceiling. Long, pale, wet, as thick as an arm, as thick as a body, coming down out of the dark like the tentacles of something at the bottom of the sea, and every one of them reaching for Hyein, on her knees on her woven floor, exhausted, too slow to get up; and the faces in the branches whispering together now, all at once, a roar of whispering, and what they were whispering was Hanni's name." },
    { n: "*Hanni. Hanni Pham. They're talking about you. They're talking about you at home, did you know? Every day. Every post. The girl who ran away to the cult. The girl who left her best friend's bed empty. Stay here. Nobody here will ever talk about you. Be quiet. Be small. Stay down here where nobody can see you and nobody can say anything—*" },
    { n: "Hanni stepped in front of Hyein." },
    { n: "She didn't decide to. Solar saw it; it wasn't a decision. It was what her body did, the thing her body had been doing since April, since December, since the first night in a dorm in Syracuse when a freshman with a bad haircut and too much eyeliner had cried in the bathroom and Hanni Pham had gone in after her: she put herself between Hyein and the thing coming for her, with her arms out, the way she'd lain her futon across Hyein's doorway every night for seven months." },
    { n: "The roots stopped a meter from her face. Dripping. Whispering." },
    { n: "*Stay quiet. Stay here. Nobody will ever talk about you again.*" },
    { s: 'hanni', f: 'serious', t: "Let them talk." },
    { s: 'hanni', f: 'serious', t: "Let them talk about me. Let them post whatever they want. Let them say I ran away and let them say I'm in a cult and let them say I'm crazy. I'm taking her home. I'm taking her home and walking her up the front steps of that house in front of everybody and they can talk about it for the rest of my life." },
    { s: 'hanni', f: 'serious', t: "I'm not staying quiet for you. I've been quiet my whole life. I'm done." },
    { n: "Something stood up behind her." },
    { n: "Not out of the water. Out of the ground under the tree, out of the dark itself, the way a mountain stands up out of mist at dawn: a woman, vast, gentle, robed in cloud and green, with a mountain's slope for shoulders and her hair full of birds; and from her hands, from her open palms, a hundred cords of light ran out in every direction, gold, warm, and found every one of them, Solar and Haechan and Akihiko and Yunjin and Hyein on her knees, and tied on. Not tight. The way you tie a child's wrist to yours in a crowd. Holding." },
    { n: "*" + PERSONA.hanni + "*." },
    { n: "The roots touched the cords and pulled back like hands from a stove." },
    // CG: eqx-au-co — a young woman standing with her arms spread in front of a kneeling friend under a vast upside-down tree hung with glowing orange fruit, behind her a gentle giant figure of mountain mist and cloud with birds in her hair, golden cords running from her open palms.
    { join: 'hanni' },
    { s: 'hyein', f: 'sad', t: "...Unnie." },
    { s: 'hanni', f: 'neutral', t: "Get up. We've got three moms to carry." },
    { n: "And from the roots of the tree, from the dark at the heart of it, from somewhere inside the trunk that went down into the black water, a viola began to play." },
    { n: "One long note. Low. Held. The bow drawn so slowly across the string that you could hear the hair catch, and the note didn't waver, didn't rise, didn't widen. It held. It held the way a hand holds a door so it doesn't swing. Under it the whispering of the faces on the branches faltered, and stuttered, and went quiet, one branch at a time, the way a room goes quiet when someone stands up at the back of it." },
    { n: "She was standing on a root at the edge of the water. In the blue coat. Buttoned to the throat. The viola under her chin and the bow in her right hand, held in the splint between a thumb and one finger; her left hand on the neck with three fingers bent back wrong and taped, and the first finger, the only one, pressed down on the string, holding the note. Four fingers. Two and two. Playing." },
    { n: "*Go*, Hanne said, round the chin rest, without stopping. *I'll hold it still. I can't hold it long. Go.*" },
    { s: 'akihiko', f: 'serious', t: "...Hanne." },
    { s: 'haechan', f: 'serious', t: "*Dalnim!* Sol—" },
    { summon: 'haenim', name: 'Haenim', sub: 'Under and over.' },
    { battle: { id: 'eqx-1122', op: 'eqx-1122', kind: 'operation', title: 'Full Moon · The Tree by the Well', desc: 'A persimmon tree growing down through the dark into still water, its fruit all faces, its roots coming down; and somewhere at its heart, held under one long note, three women.', forced: true } },
    { music: 'night' },
    { n: "The Tree came apart." },
    { n: "Not like ash. Like fruit going over: the faces on the branches going soft all at once, all thousand of them, and dropping, *thud, thud, thud*, like rain on a roof, into the water, and sinking; the roots overhead going limp and hanging, dripping, still; and the trunk, the great upside-down trunk going down into the black, splitting. Down its length. Along a line, straight as a seam, the bark parting, opening a finger's width, then a hand's, then a door's." },
    { n: "The viola stopped. Hanne was sitting on the root with the instrument in her lap and her head down. When Solar looked again she was gone, and the root was empty, and there were three long blue threads caught on the bark." },
    { n: "Inside the split in the trunk, in the hollow of the Tree, the mothers." },
    { n: "Three of them. Sitting on the floor of the hollow in the dark, in the wet, back to back to back, the way you'd sit to keep warm. Barefoot. In their own clothes, the cream cardigan and the gray house cardigan and the navy vest, filthy, stiff with dried water and something darker. Their heads bowed. Their hair down, all three, loose, tangled with root." },
    { n: "And down each of their backs, from the nape of the neck to the small of the back, a seam." },
    { n: "Sewn. Closed. With sorghum. Long dry red stalks of it, split thin, threaded through the skin in big crude stitches a finger apart, pulled tight, knotted at the bottom, the skin puckered round every stitch, red and angry; the way you'd sew up a sack to carry something in it, and carry it, and open it again, and sew it again, and open it." },
    { n: "They were talking. Low. Taking turns. A sentence each. The same story. In each other's voices." },
    { n: "*And on the next hill*, said Solji, in Miseon's low quiet voice, *the tiger said, give me one rice cake and I won't eat you.*" },
    { n: "*And she gave it*, said Miseon, in Mrs. Kim's sharp Seoul one." },
    { n: "*And on the next hill*, said Mrs. Kim, in Solji's soft American English, *the tiger said*—" },
    { n: "Solar went down on her knees in the water at the mouth of the hollow." },
    { s: 'solar', f: 'sad', t: "Mom." },
    { n: "Three heads came up." },
    { n: "They looked at her. All three. Their faces were their own faces; gray, and thin, and the lips cracked, and the eyes enormous in them, but theirs, nothing else looking out. For a long moment none of them knew her. Solar watched them not know her. Then Solji's mouth moved, and what came out of it was Solji's own voice, cracked, a whisper, the little lift at the end." },
    { s: 'solji-runners', f: 'sad', t: "...Honey?" },
    { s: 'miyeon-strangers', f: 'sad', t: "...Sol-ah." },
    { s: 'kim-mom', f: 'sad', t: "...You took so long. Where have you *been*." },
    // CG: eqx-hollow — three barefoot women in worn cardigans sitting back to back inside the split hollow of a vast dark tree trunk above black water, their hair loose and tangled with roots, a girl kneeling at the mouth of the hollow reaching in.
    { n: "They carried them up." },
    { n: "Hyein's stretchers held. Double-stitched at every seam. Hanni at one end and Haechan at the other with Solji between them on her front because she couldn't lie on her back; Akihiko and Yunjin with Miseon; Solar and Mitsuru with Mrs. Kim, who complained the whole way up the Road Home that they were jolting her and that the stretcher was badly made and that she could walk, she could perfectly well walk, and didn't try to." },
    { ifFlag: 'dead.aigis', then: [
      { n: "Hyein carried nothing. She walked beside Solji's stretcher with Aigis's hand held against her chest in both of hers, still locked in its fistful of her coat, and the white ribbon wound round her own wrist, and she didn't speak the whole way up, and nobody asked her to." }
    ], else: [
      { n: "Aigis carried the head of Mrs. Kim's stretcher on the rope, alone, climbing with one hand, because she didn't need to breathe and didn't get tired, and Mrs. Kim looked up at her the whole way, at her calm face in the red, and at the top said *thank you, dear* in Korean, and Aigis said *you're very welcome* in Korean back, perfectly, and Mrs. Kim said *oh, your accent is wonderful*." }
    ] },
    { n: "Halfway up the rope Fuuka's voice came into Solar's ear, very small." },
    { s: 'fuuka', f: 'sad', t: "...Solar. Something's telling it. Below you. All of it. The whole story. I can hear it so clearly." },
    { n: "Solar could hear it too. Coming up the shaft from far below. From under the Tree. From the bottom of everything. The tale. All of it. In three voices. Solji's, telling it in English with the Korean names left in. Miseon's, low, with the lights off. Mrs. Kim's, doing the tiger's voice so well it would make a child cry." },
    { n: "Each in its own voice, now. Correctly. Perfectly. Every word each of them had ever said at the side of a bed in the dark." },
    { n: "And on the stretchers, on the rope, being carried up toward the red courtyard and the three men holding the line, the three women who'd said them lay with their eyes open, listening to it, and none of them knew the words." }
  ] },

  { id: 'eqx-seams', date: '11/23', slot: 'early', consumes: true, title: 'sewn', place: 'Gekkoukan High · Courtyard', time: 'The Red Hour',
    cast: { solar: 'Solar', 'jaesang-runners': 'Jaesang', 'solji-runners': 'Solji', 'taesang-strangers': 'Taejoon', 'miyeon-strangers': 'Miseon', 'kim-dad': 'Mr. Kim', 'kim-mom': 'Mrs. Kim',
      mitsuru: 'Mitsuru', hyein: 'Hyein', hanni: 'Hanni', junpei: 'Junpei', aigis: 'Aigis', jaehyun: 'Jaehyun' },
    scene: [
    { bg: 'eqx-courtyard-well-night', music: 'tender' },
    { n: "The fathers pulled them up out of the well." },
    { n: "Hand over hand on Mitsuru's line, the three of them, at the lip, with their feet braced on the paving and their faces running with sweat in the cold, Jaehyun behind his father with his arms round his waist; and the stretchers came up out of the dark one at a time into the red, and at the top of each one, a man let go of the rope and fell on his knees." },
    { n: "Mr. Kim first. Because Mrs. Kim's stretcher came up first. He didn't say anything. He knelt by it on the stone and took her face in both his hands, her gray thin face with its cracked lips, and looked at it, and she looked back at him." },
    { s: 'kim-mom', f: 'neutral', t: "...What took you so long." },
    { s: 'kim-dad', f: 'sad', t: "A hundred and twelve stations, yeobo. A hundred and twelve. I checked twenty-six exits. You weren't under a single clock." },
    { s: 'kim-mom', f: 'sad', t: "Of course I wasn't under a clock. Who meets under a clock. What kind of person meets under a clock." },
    { n: "He laughed. He put his face down on her shoulder and laughed into it until it wasn't laughing, and she put one hand up, slowly, shaking, and held the back of his head." },
    { n: "Then Taejoon. Miseon's stretcher. He knelt by it. He didn't touch her. He looked at her, at her hair loose over the canvas, which he'd seen, Solar thought, perhaps twice in thirty years; and she looked up at him; and they looked at each other for a long time, and said nothing, very loudly, the both of them." },
    { n: "Then he took off his borrowed coat and put it over her. Carefully. Tucking it at the sides. And she closed her eyes." },
    { n: "Jaesang knelt by Solji's stretcher. She was lying on her front, on her stomach, her cheek on the canvas, her face turned toward him. He put his hand out to her back. To touch it. The way he touched her back in doorways, at parties, a hand at the small of it, steering." },
    { n: "Solji flinched so hard the stretcher moved." },
    { n: "It wasn't a flinch. It was her whole body going rigid and away from his hand, a sound coming out of her through her teeth, high and thin, the way a dog makes a sound when you touch the leg it's broken." },
    { n: "Jaesang's hand stopped in the air. A centimeter from the seam." },
    { n: "He looked at it. At the stitches. The sorghum stalks through his wife's skin, a finger apart, all the way down, and the puckered red at every one. Solar watched him understand what they were for. What had been opened and closed, and opened, and closed, through October, while he sat at a long table with his back to the kitchen door." },
    { n: "He took his hand back. He put it on her face instead. Her cheek. Her hair. And kept it there, on the parts of her he could touch, and bent down and put his forehead on the canvas beside her face, and Solar had never once heard her father cry, in any year, and she heard it then." },
    { ifFlag: 'dead.aigis', then: [
      { place: 'Gekkoukan High · Courtyard', time: 'Dawn', bg: 'eqx-courtyard-well-day', music: 'tender' },
      { n: "They had to cut Hyein's coat." },
      { n: "In the end. At dawn, in the courtyard, after the Group's vans had come for the mothers and gone again. The hand wouldn't open. Hyein had held it the whole way up the rope and the whole way across the courtyard and she sat on the edge of the well's stone lip at five in the morning still holding it against her chest, the piece of her own coat locked in its fingers, and the fingers wouldn't open; they'd closed with everything Aigis had, and Aigis had had a great deal." },
      { n: "Mitsuru knelt in front of her. She'd sent for someone from the Kirijo labs; a woman in a white coat over pajamas, with a case of tools, who'd looked at the hand and then at Mitsuru and then hadn't said anything at all." },
      { s: 'mitsuru', f: 'sad', t: "Hyein. We have to take it now. We have to take her back to the lab. They'll take care of her. I'll take care of her. I'll— I built her a room. Did you know that? In the lab. Before you came. I built her a room with a window." },
      { s: 'hyein', f: 'sad', t: "It won't open. I've been trying. I've been trying all night. She won't let go." },
      { s: 'mitsuru', f: 'sad', t: "I know. She never did. That was the whole of her." },
      { n: "The woman in the white coat cut the coat. Not the hand. The coat. Round the fist, with a pair of shears, carefully, so that Hyein was left holding nothing and the hand was left holding a square of dark wool; and Hyein let go, at last, of the thing that had been holding her, and Mitsuru took it, the hand and the cloth in it, both, and held it in her lap, and bent over it." },
      { n: "Junpei was standing at the edge of the courtyard. In his pajamas and a jacket. He'd come down at four when Fuuka had told the dorm. He hadn't come any closer." },
      { s: 'junpei', f: 'sad', t: "...She asked me. In April. On the roof. She said, if anybody falls into anything, I'd like to be asked first. She said it like a joke. She didn't do jokes." },
      { s: 'junpei', f: 'sad', t: "I put it in my notebook. Her name. On my grid. I tick her every morning. I've ticked her every morning since April, I've never missed one." },
      { n: "He took the frog notebook out of his jacket. He opened it. He didn't tick anything. He held the pencil over the box for a long time, and then put the notebook away without making a mark, and walked back to the dorm alone in his pajamas in the dawn." },
      { n: "Hyein had the ribbon. The blue one. Round her own wrist, tied in a knot she'd made with her teeth on the rope. She sat on the lip of the well with Hanni's arm round her and her other hand empty in her lap, palm up, and looked at it." },
      { s: 'hyein', f: 'sad', t: "...It was a door. It was just a door. I knew. I knew the whole time. I knew in April. I knew it wasn't her." },
      { s: 'hanni', f: 'sad', t: "I know you did." },
      { s: 'hyein', f: 'sad', t: "I opened it anyway. She sounded so sure." },
      { n: "Hanni didn't say *it's not your fault*. She didn't say anything. She held on." },
      { flag: 'eqx-aigis-hand' },
      { n: "The rest of Aigis stayed down there. Behind the door in the water under the Tree. Mitsuru went down on the Thursday with the Group's divers and the Group's lights, and came up again after six hours, and said nothing about it to anyone, and the next week there was a small private service at the Kirijo chapel in Tatsumi, with a coffin no bigger than a box for a pair of shoes, and in it, wrapped in a square of dark wool, one hand." }
    ], else: [
      { place: 'Gekkoukan High · Courtyard', time: 'Dawn', bg: 'eqx-courtyard-well-day', music: 'tender' },
      { n: "Aigis stood at the lip of the well at dawn, after the Group's vans had come for the mothers and gone, and took a reading of the courtyard." },
      { s: 'aigis', f: 'neutral', t: "Three. Heart rates elevated, irregular, weak. Alive. All three. I wanted to say it out loud. I've been wanting to say it since the hollow." },
      { n: "Hyein was sitting on the lip of the well with her hands in her lap, looking at them. At her fingertips. Thread was still coming off them, very faintly, one gold hair at a time, and drifting away in the cold air, and she watched it go." },
      { s: 'hyein', f: 'neutral', t: "...You didn't have to be asked." },
      { s: 'aigis', f: 'neutral', t: "No. You didn't open it. So there was nothing to be asked." },
      { s: 'aigis', f: 'happy', t: "I would still like to be. Next time. If there's a next time. I find that I'd like that very much." }
    ] },
    { place: 'Kirijo Group · Tatsumi Ward', time: 'Morning', bg: 'hospital-room', music: 'tender' },
    { n: "The mothers were in the Kirijo ward in Tatsumi for nine days." },
    { n: "The doctors took the stitches out. All of them. It took a whole morning, with the three women lying on their fronts in a row of beds and the stalks coming out one by one with a long dry whisper each, and the fathers not allowed in the room, standing in the corridor in a row against the wall with their eyes on the door." },
    { n: "They didn't heal properly. That was the first thing anybody said, the second week. The seams closed. They closed red and ridged and wrong, the edges not meeting, as if the skin had forgotten which side was which. They'd ache in the cold, the doctor said. Probably always." },
    { n: "The second thing came out on the fourth day, by accident." },
    { n: "Solar was sitting by Miseon's bed. Holding her hand. Miseon was asleep, or nearly. Solar was talking to her the way you talk to someone asleep, nothing, the weather, the Well, and she said, without thinking, *do you remember the story? The one you used to tell me? With the lights off? You always stopped at the rope.*" },
    { n: "Miseon opened her eyes. She looked at the ceiling." },
    { s: 'miyeon-strangers', f: 'neutral', t: "...What story, Sol-ah?" },
    { n: "Solar asked Solji that afternoon. And Mrs. Kim, in the next bed, who said *what story? I never told you any stories, you had picture books, your father read you the picture books.* Solji only looked at her, puzzled, kind, and then at Jaesang, and said *did we have a bedtime story? I always meant to. I always meant to start one.*" },
    { n: "None of them remembered. Not one word. Not the hills, not the rice cakes, not the rope, not the voice at the door. It had been taken out of them, Solar understood, sitting very still between the beds; whole; clean; the way you take a stone out of a fruit. And it was below them now, at the bottom of everything, being told perfectly in all three of their voices to nobody." },
    { flag: 'eqx-mothers-back' }
  ] },

  { id: 'eqx-held-too-long', date: '11/27', slot: 'late', consumes: true, title: 'as long as it takes', place: 'The Velvet Room', time: 'Late Night',
    cast: { solar: 'Solar', elizabeth: 'Elizabeth', theodore: 'Theodore' },
    scene: [
    { bg: 'velvetroom-1', music: 'velvet' },
    { n: "Theodore had made tea." },
    { n: "He'd made it before she came in, which was a thing he did now; he knew, somehow, the way the Room knew things, the minute she'd put her hand on the blue door in the Paulownia passage, and by the time she was through it there was a cup on the little table by the chair, steaming, in a saucer, with a biscuit on the saucer, the kind she liked, the ones with the jam in the middle." },
    { s: 'theodore', f: 'happy', t: "Good evening. Do sit. My sister will be with you directly. She is— she has been standing in front of the door for some time." },
    { n: "Elizabeth was standing in front of the door." },
    { n: "The one at the back of the Room. The one with the line of gold light under it that had been there since April. She had her back to them and both her gloved hands flat on it, on the blue wood, the way you'd hold a door shut against a wind, or open against one; and her head was bowed, and she didn't turn round." },
    { s: 'elizabeth', f: 'neutral', t: "...You brought them up. The mothers. Three strands, back on the rope. I felt it. I felt the whole book shift on its spine." },
    { ifFlag: 'dead.aigis', then: [
      { s: 'elizabeth', f: 'sad', t: "And I felt a page close. On the night. Her page. The girl who didn't need to breathe. It closed very quietly. Somewhere, she's turning the next one without you." }
    ] },
    { ifFlag: 'dead.shinjiro', then: [
      { s: 'elizabeth', f: 'sad', t: "As I felt his. In October. On the stairs. I didn't tell you then. I didn't know how. I still don't." }
    ] },
    { n: "She took her hands off the door. Slowly. One, then the other. The door didn't move. The gold line under it went on burning. She turned round, and her face was a face Solar had never seen on her. Not delighted. Not curious. Tired, and guilty, and very young." },
    { s: 'elizabeth', f: 'sad', t: "I have to tell you something. I should have told you in April. I should have told you in March of last year, the night you went home through my doors. I'm going to tell you now, and then you may decide what you think of me. That will be yours." },
    { n: "She sat down. In the chair across from Solar's. She folded her gloved hands in her lap and looked at them." },
    { s: 'elizabeth', f: 'neutral', t: "You asked me in April why the bridge never closed. I told you about the holders. The ones who followed their own hands. That was true. It was the first page." },
    { s: 'elizabeth', f: 'neutral', t: "Here is the last." },
    { s: 'elizabeth', f: 'neutral', t: "The bridge never closed because you are the bridge." },
    { n: "Solar didn't say anything. Her tea was going cold in her hands." },
    { s: 'elizabeth', f: 'neutral', t: "One girl. Three lives. Gone from two of them at any one time, and from this one too, now and then. A gap. In each book. A space where a girl is supposed to be and isn't. I told you that once, I called you a lacuna, and I thought I was being clever. I wasn't being clever. I was being exact." },
    { s: 'elizabeth', f: 'neutral', t: "Every time you went home and became exactly what they needed you to be, the gap in the other two got a little wider. And every time, something paid a little more of you across it. One small thing. One at a time. Like a basket of rice cakes, carried over hills." },
    { s: 'elizabeth', f: 'sad', t: "And on the sixth of March, last year, when you went home through my doors, I said I'd hold them open for you. As long as it takes. Do you remember?" },
    { s: 'solar', f: 'neutral', t: "...You said you had quite a lot longer than that." },
    { s: 'elizabeth', f: 'sad', t: "I did. I said it so proudly. I've been thinking about it every night since April." },
    { s: 'elizabeth', f: 'sad', t: "I said I'd hold the doors as long as it takes. I didn't know how long that was." },
    { s: 'elizabeth', f: 'sad', t: "I'm still holding one." },
    { n: "She looked over her shoulder. At the door at the back of the Room. The gold line under it." },
    { s: 'elizabeth', f: 'neutral', t: "Hers. The violist's. Hanne's. I held it for her on the sixth of March so she could go home, and she went, and I didn't let go. I didn't know how to. I'd never been asked to let go of anything. I'd only ever been asked to hold. And so it never quite shut. A finger's width. That's all it ever was. A finger's width, open, for a year and a half." },
    { s: 'elizabeth', f: 'sad', t: "That's how it got its paw in." },
    { n: "Theodore had gone very still by the tea things. He didn't look at his sister. He looked at the door." },
    { s: 'elizabeth', f: 'neutral', t: "Something came through my crack, Solar. Something very old and very hungry that has been waiting at the bottom of a story for a long time for a rope strong enough to climb. And it found a woman alone in a flat with nobody to stop for her, and spoke to her in her mother's voice, and she opened her door. And it found you. And it's been braiding." },
    { s: 'elizabeth', f: 'neutral', t: "That's what the girls are. The five who came with three lives. That's what's happening to your Hanni in her sleep. It's making rope out of people. Three strands to a person. It wants the strongest rope there has ever been." },
    { s: 'elizabeth', f: 'sad', t: "And I held the door for it." },
    { n: "Nobody said anything. The Room hummed its long low note under everything, the one it had always hummed, and somewhere far off, through the door at the back, very faintly, two knocks." },
    { s: 'solar', f: 'neutral', t: "...Close it." },
    { s: 'elizabeth', f: 'sad', t: "I can't. Not yet. If I let it go now, all at once, I don't know what comes through or what's on the other side of it when it slams. Hanne is on the other side of it. Everyone she pulled is on the other side of it, in a way. You're on the other side of it." },
    { s: 'elizabeth', f: 'neutral', t: "I'm going to let it go slowly. The way you taught me. In April, at the café. Look both ways. Let go. It's not forever, it's just closed. I wrote it on my wrist." },
    { n: "She turned her gloved hand over and pushed the cuff of her sleeve back an inch. On the inside of her wrist, in blue ballpoint, faded, rewritten over and over until the skin was stained: *it's just closed.*" },
    { n: "Then she pulled the cuff down, and was Elizabeth again, almost; and smiled, almost." },
    { s: 'elizabeth', f: 'happy', t: "Oh, and I went to supper. At her house, down by the river. Did I tell you about it properly? I've been meaning to, it was the most extraordinary evening. The lady who keeps the boarding house. She'd heard about me, she said. She'd heard I'd never been asked out to supper in my life." },
    { n: "Solar's cup rattled in its saucer." },
    { s: 'elizabeth', f: 'happy', t: "It was wonderful. Fourteen dishes. She remembered how I take my tea before I'd told her. And at the end of it she held my hand at the door, and asked me if I wouldn't like to stay. Just one more day. Just to see what it was like, to be somewhere, and stay." },
    { s: 'elizabeth', f: 'happy', t: "And I said: I'm not allowed. Isn't that a shame?" },
    { s: 'elizabeth', f: 'neutral', t: "And she looked at me for the longest time. And she let go of my hand. She was so disappointed. I've never seen anyone so disappointed. It was almost flattering." },
    { n: "Theodore had come round the table. He stood behind his sister's chair with his hand on the back of it, and he was looking at Solar, and his face was doing something careful." },
    { s: 'theodore', f: 'neutral', t: "Sister. You haven't slept in a month. You haven't sat down. You stand at that door all night and you call it holding. Let me take it. For a night. I'm terribly heavy-handed with doors, you've always said so, but I can stand in front of one, surely." },
    { s: 'elizabeth', f: 'neutral', t: "...Perhaps. Perhaps for one night." },
    { n: "She looked at Solar." },
    { s: 'elizabeth', f: 'happy', t: "You're having a party. Aren't you. Your Junpei told me. On the twenty-first. To forget the year. I heard him tell the boy in the ramen shop. He was very loud about it." },
    { s: 'solar', f: 'neutral', t: "...It's not much of a party. It's the lounge and Junpei's banner." },
    { s: 'elizabeth', f: 'happy', t: "I've never been to one. A party to forget a year. What a thing. What a human thing, to throw a party for forgetting." },
    { n: "She looked so hopeful. Solar had seen her look a lot of things and never that." },
    { choose: [
      { t: "Come. I'm asking. Come to the party.", flag: 'eqx-eliz-invited', then: [
        { s: 'elizabeth', f: 'happy', t: "Oh. Oh, I shall. I shall come and I shall forget everything. Theo, you'll hold the door." },
        { s: 'theodore', f: 'happy', t: "I'll hold it. Go and forget things. Bring me back a description of the cake." }
      ] },
      { t: "It's up to you. You'd be welcome. It's yours to decide.", flag: 'eqx-eliz-invited', then: [
        { n: "Elizabeth looked at her for a long moment. Then her whole face changed, slowly, from the inside, the way a room changes when the sun comes round to its window." },
        { s: 'elizabeth', f: 'happy', t: "...Mine to decide. Do you know, nobody's ever said that to me about anything? Then I decide yes. Theo, you'll hold the door." },
        { s: 'theodore', f: 'happy', t: "I'll hold it. Go and decide things. Bring me back a description of the cake." }
      ] }
    ] },
    { flag: 'eqx-eliz-confessed' },
    { n: "On her way out Solar looked back. Theodore was helping his sister up out of the chair, his hand under her elbow, gently, the way you'd help someone who'd been standing too long; and behind them, at the back of the Room, the gold line under the door burned steady, a finger's width, the way it had all year; and on the velvet of the chair she'd sat in, where her hand had rested, there was a little fine pale dust, like flour." }
  ] },

  { id: 'eqx-healing', date: '12/4', slot: 'evening', consumes: true, title: 'they ache in the cold', place: 'Iwatodai Dorm · Lounge', time: 'Evening',
    cast: { solar: 'Solar', 'solji-runners': 'Solji', 'miyeon-strangers': 'Miseon', 'kim-mom': 'Mrs. Kim', 'jaesang-runners': 'Jaesang', 'taesang-strangers': 'Taejoon', 'kim-dad': 'Mr. Kim',
      mrsoka: 'Mrs. Oka', mitsuru: 'Mitsuru', hyein: 'Hyein', hanni: 'Hanni' },
    scene: [
    { bg: 'iwatodaidorm-livingroom-night-winter', music: 'tender' },
    { n: "The mothers came to the dorm on the first of December. Mitsuru gave up her own room on the fourth floor for Mrs. Kim and Mr. Kim, and Fuuka and Yukari moved in together so Solji and Jaesang could have one, and Taejoon and Miseon took the small room at the end of the third-floor hall, the one with the window over the street, which Taejoon had picked because he could see the front door from it." },
    { n: "By the fourth, everybody knew how they were." },
    { n: "Solji couldn't be touched on the back. Not by anyone. Not a hand on her shoulder blade in a doorway, not an arm round her shoulders on the couch. Jaesang had learned it in a day: he walked beside her with his hand an inch from her back, never on it, the way you'd walk beside someone carrying something full to the brim. She sat on the couch at the very front of the cushion so nothing touched her spine, and laughed at Junpei's jokes, and every so often, when someone moved behind her, went white." },
    { n: "Mrs. Kim slept sitting up. In the armchair in the lounge, with a blanket over her knees and the TV on low. She wouldn't lie down. She said she wasn't tired. She said it every night at two in the morning to whoever was on Hanni's rota, sitting bolt upright with her eyes open in the blue light, *I'm not tired, go to bed*, and Mr. Kim slept on the floor at the foot of the chair with his head against her feet, every night, because she wouldn't come to bed, so he'd brought the bed to her." },
    { n: "Miseon flinched at gloves." },
    { n: "Nobody would have noticed. That was Miseon. She did it so small. Mitsuru came in from her bike on the second with her riding gloves on, black leather, and peeled them off at the door, and Miseon, at the kitchen table with her tea, went still for one second, the cup an inch from her mouth; and didn't look; and put the cup down; and turned the ring on her finger once, all the way round. Mitsuru saw. Mitsuru put the gloves in her bag and zipped it and never wore them in the dorm again." },
    { n: "They were alive. That was the thing everybody kept saying. Junpei said it every morning at breakfast like grace. *They're alive.* They were alive, and in the cold the seams down their backs ached so that sometimes, in the middle of a sentence, one of them would stop, and put her hand back as far as she could reach, and not quite touch it." },
    { n: "On Saturday night Mrs. Oka came." },
    { n: "She came at seven, in the dark, in her shawl and her white gloves, with a pot. Wrapped in a cloth. Soup. She stood at the bottom of the dorm steps and didn't come up them. She never came up them. She waited, in the light from the door, with the pot held against her chest, to be asked." },
    { n: "Koromaru was across the inside of the door. He stood up when she came to the bottom of the steps and didn't growl. He didn't do anything. He stood with his legs set, looking at her through the glass, and the hair along his back stood up from his neck to his tail." },
    { n: "Taejoon went to the door. Nobody had asked him to. He opened it, a hand's width. He stood in the gap with his body in it." },
    { s: 'mrsoka', f: 'sad', t: "Oh, Mr. Lee. I heard. I heard they were home. I couldn't stay away. I've brought something. For them. For the three of them. You've got to keep something warm in them, when it's cold like this." },
    { s: 'taesang-strangers', f: 'neutral', t: "...Thank you." },
    { n: "He took the pot. Through the gap. He didn't open the door wider. He held the pot against his chest with both arms, the way Mrs. Oka had held it." },
    { n: "She looked past him. Into the lounge. Up at the lit window of the kitchen, where Miseon was sitting at the table with her tea." },
    { s: 'mrsoka', f: 'happy', t: "Miseon-ssi. When you're well. You'll come back to me, won't you. I miss you in my kitchen. I miss the way you fold the dumplings. Nobody folds them like you. You'll come back and stay." },
    { n: "At the kitchen table, behind the window, Miseon didn't turn her head. She didn't look out. She put her cup down, very gently, on the table. She turned her ring once. And kept turning it. Round. Round. Round. Without stopping." },
    { n: "Taejoon shut the door. Not hard. Exactly as hard as a door is shut on a cold night to keep the heat in." },
    { n: "Then he stood in the hall with the pot in his arms and looked at it. And walked through the lounge with it, past all of them, past Solji on the edge of the couch and Mrs. Kim in her armchair, into the kitchen, past his wife at the table, to the back door, and out of it, into the yard, to the bins, and poured it out. All of it. Into the bin. The soup steaming in the cold. And stood the empty pot upside down on the back step, and came back in, and washed his hands, for a long time, at the sink." },
    { n: "Nobody said anything about it. Miseon's ring stopped turning." },
    { s: 'kim-mom', f: 'neutral', t: "...Good. I didn't like the smell of it. Too sweet. Who puts sugar in soup." },
    { place: 'Iwatodai Dorm · Kitchen', time: 'Late Night', bg: 'iwatodaidorm-kitchen-night', music: 'night', soft: true },
    { n: "At midnight the mothers sat in the kitchen together, the three of them, while the household went up to bed. Solar came down for water and stopped in the doorway, because they were talking, and she didn't want to break it." },
    { n: "They were comparing their backs. Not looking. Talking. *Mine's worse at the bottom. Mine's worse at the top, by the neck. Mine pulls when I lift my arm.* The three of them round the table in their nightclothes, with tea, in three languages that weren't quite the right languages, Solji's Korean and Mrs. Kim's English and Miseon's quiet Japanese from the boarding house, doing their best." },
    { s: 'solji-runners', f: 'neutral', t: "I keep dreaming I'm telling somebody something. A story. I'm telling it and telling it and I can't remember the end. And somebody else keeps finishing it for me. In my voice." },
    { s: 'kim-mom', f: 'neutral', t: "Mm. Me too. Every night. I wake up and my mouth's dry, like I've been talking for hours." },
    { n: "Miseon didn't say anything. She reached across the table, and took Solji's hand, and then Mrs. Kim's, and held them both, and the three of them sat like that with their tea going cold, holding hands round the table in the dorm kitchen at midnight, three women who'd never have met in any world but this one; and none of them said what it was they'd been telling, because none of them knew." },
    // CG: eqx-three-mothers — three middle-aged women in nightclothes sitting at a dorm kitchen table late at night, holding hands across it over cooling cups of tea, seen from the dark doorway.
    { n: "Solar stood in the doorway in the dark and didn't go in. She knew the story. She could have told them. Every word, in each of their voices. She stood there and held it, all three versions, the way you hold something somebody's left with you to keep, and didn't say a word of it, and went back up the stairs without her water." }
  ] },

  { id: 'eqx-persimmon', date: '12/9', slot: 'early', consumes: true, title: 'the children in the tree', place: 'The Oka Boarding House · Garden', time: 'Early Morning',
    cast: { solar: 'Solar', kazuha: 'Kazuha', chaewon: 'Chaewon', mrsoka: 'Mrs. Oka', mitsuru: 'Mitsuru', yunjin: 'Yunjin', rio: 'Rio', saori: 'Saori', eunchae: 'Eunchae', sakura: 'Sakura' },
    scene: [
    { bg: 'eqx-courtyard-well-day', music: 'eerie' },
    // BG: oka-garden-dawn — the walled garden of an old Japanese house at a frosty winter dawn, a bare persimmon tree with a few last shriveled fruit, a heavy stone-capped well beneath it, a veranda with a small white saucer at its edge.
    { n: "Kazuha found him." },
    { n: "At twenty to six, on the Thursday, in the frost. She went out onto the veranda in her socks and her coat over her pajamas to take in the saucer, the way she did every morning, to see if the rice had been accepted; and the saucer was there at the edge of the boards, upside down in its ring of white; and she bent down to pick it up, and something touched the top of her head." },
    { n: "Lightly. The way a branch touches your head when you walk under a tree in the dark. Something cold. Something that swung away when it touched her, and came back, and touched her again." },
    { n: "She looked up." },
    { place: 'The Oka Boarding House · Garden', time: 'Dawn', bg: 'eqx-courtyard-well-day', music: 'eerie' },
    { n: "Solar got there at six-twenty. Chaewon had phoned the dorm. Not Mitsuru, not Hanni. Solar. Her voice on the phone perfectly calm and perfectly flat, the voice she used to count at the door of a club, *Solar, can you come. Can you come to the garden. Come by yourself first. Please.*" },
    { n: "She came with Yunjin, because Yunjin was on the rota with her and wouldn't be left, and they ran the river street in the dark with the frost cracking under their shoes and the persimmon tree over the wall coming up gray out of the gray dawn as they ran toward it, bare now, every leaf gone, a few last fruit on it shriveled to the size of fists, black." },
    { n: "And hanging from the lowest bough, upside down, by his ankles, Mr. Edogawa." },
    { n: "Somebody had tied him there. With a rope round his ankles, knotted, and the rope looped over the bough twice; tied the way you'd hang something to dry, a fish, a sheaf, a skin, so that he hung straight down from the branch with his arms hanging down past his head and his fingertips a hand's width off the frost. His lab coat had fallen down round his shoulders, inside out. His tie hung down over his face." },
    { n: "He was empty." },
    { n: "Solar knew it from the gate. You learned to know it, this year. The way a coat hangs when there's nobody in it. He hung from the persimmon bough the way his lab coat would have hung on the back of the nurse's office door: the shape of a man, the length of a man, and nothing in it. The skin of his face hanging down off his skull under the tie like a sleeve. His hands like gloves. And from the back of him, along the spine, from the nape of the neck to the belt, the line. Open. Dry. Neat." },
    { n: "Everything about him was white. Dusted. Fine and pale and even, all over, the way you'd dust a board before you rolled out dough on it. His lab coat. His trousers. His hands, his hanging hair. And on the frost under him, a fine white circle on the frozen grass, where it had fallen off him as he swung." },
    { n: "His glasses were on the ground in the middle of the circle. Folded. Neatly. As if somebody had taken them off him before, and set them down where he'd be able to find them." },
    { n: "Like the children in the tree, Solar thought. And then couldn't stop thinking it. The children in the tree. The ones who climbed up the persimmon by the well to get away from the thing at the door, and hid in its branches, and looked down." },
    { n: "Kazuha was sitting on the veranda with the saucer in her lap. She hadn't moved. Chaewon was beside her with her arm round her. Upstairs, at the window of the big room, the other two, Sakura and Eunchae, their faces white against the glass." },
    { s: 'kazuha', f: 'sad', t: "...He touched my head. When I bent down. His hand. His hand touched my head." },
    { s: 'chaewon', f: 'neutral', t: "Don't. Kazu. Don't." },
    { s: 'kazuha', f: 'sad', t: "I thought it was the tree." },
    { n: "Yunjin had stopped at the gate. She stood in it with her hands at her sides and looked at the man in the tree, and Solar watched her face do the thing it did on the riverside in another life, close up, very tight, and hold." },
    { s: 'yunjin', f: 'neutral', t: "...I said I wanted to be scared. I said I wanted the house with people in it where somebody might not come home." },
    { s: 'yunjin', f: 'sad', t: "I meant it. I still mean it. I didn't think it'd be him." },
    { n: "The scream came out of the house behind them. High, thin, long. Like a kettle." },
    { n: "Mrs. Oka came out onto the veranda in her nightgown. With her gloves on. She saw him, and screamed again, and put both her gloved hands over her mouth, and her small face crumpled, and she came down off the veranda barefoot onto the frost, and went toward the tree with her arms out, and stopped under him, and looked up." },
    { s: 'mrsoka', f: 'worried', t: "Oh— oh, no. Oh no, no, no. Not him. Not him. He was here last night. He stayed so late. He wanted to hear the end, he wanted to hear all of it, and it got so late, and the last train had gone. I said he could stay. I said, stay the night, sensei, I'll make up a room, you can hear the rest in the morning—" },
    { s: 'mrsoka', f: 'sad', t: "And he said yes. He said yes, how kind. He said he'd love to stay." },
    { n: "She put her gloved hand up. Gently. To his hanging hand, an inch above the frost. And took it. And held it, under the tree, crying. And when she let it go, her glove was white to the wrist." },
    { n: "Solar watched her do it. She watched her face. Wet, crumpled, devastated, kind. She watched the glove come away from his fingers, and the white on it, and the little smile, so small, at one corner of the crying mouth; and something under her ribs that had turned over on the bridge in September, once, like a card, turned over again, and lay face up." },
    // CG: eqx-persimmon — a frosty walled garden at a gray winter dawn, a bare persimmon tree with a few shriveled black fruits, a pair of folded spectacles lying in a pale circle of dust on the frozen grass beneath a low bough, a stone-capped well nearby.
    { n: "The Group came at seven. The doctor was sick in the hydrangeas again; the same doctor, the same hydrangeas. *Heart*, he said, when he could talk, and then looked at the tree and at the rope round the ankles and at Mitsuru, and stopped, and didn't say anything else. Mitsuru signed nothing. She stood in the garden in her coat with her hands in her pockets and looked at Mrs. Oka on the veranda being comforted by Kazuha, of all people, Kazuha with her arm round her, and Mitsuru's face did nothing at all, and Solar had learned by now what that meant." },
    { s: 'mitsuru', f: 'serious', t: "The girls are moving out. Today. All four. To the guesthouse." },
    { s: 'chaewon', f: 'neutral', t: "...She asked us to stay together." },
    { s: 'mitsuru', f: 'serious', t: "Then stay together. At the guesthouse." },
    { n: "Chaewon looked at Mrs. Oka on the veranda. At Kazuha holding her. At the man in the tree. She stood up." },
    { s: 'chaewon', f: 'neutral', t: "We'll stay together. That's ours. We were going to anyway. We don't need her to ask." },
    { s: 'chaewon', f: 'serious', t: "Kazu. Get your things. Sakura, Eunchae, get your things. Everything. Don't leave anything. Don't leave one sock in this house." },
    { flag: 'eqx-girls-left' },
    { place: 'Gekkoukan High · Classroom', time: 'Lunchtime', bg: 'gekkoukan-classroom-day', music: 'tender', soft: true },
    { n: "At school they said it was his heart." },
    { n: "The principal said it at assembly. In his sleep. At a friend's house, after a long evening. Peacefully. The students in the gym bowed their heads, and some of the first-years cried, and somebody at the back laughed nervously and was elbowed, and it was over in four minutes." },
    { n: "Rio and Saori found Solar at lunch. Saori had the brown Korean book. It had been in the garden, by the well, under the frost, Mitsuru's people had found it and given it to the school and the school had given it to the library and Saori had taken it off the returns trolley before anyone could shelve it." },
    { n: "She opened it. Between the brown pages, the slip of paper. In his handwriting." },
    { n: "*Ask: children / tree.*" },
    { n: "And under it, in pencil, smaller, shakier, in the same hand, written later, written fast:" },
    { n: "*They hid in the tree. It found them by their reflection in the well. It was never at the door. It was always under the water looking up.*" },
    { ifFlag: 'eqx-edogawa-warned', then: [
      { s: 'saori', f: 'sad', t: "...He told me, last week, a student had asked him not to go. He said it was the nicest thing a student had ever said to him. He said he was going to go anyway. He said, it's only tea." }
    ] },
    { s: 'rio', f: 'sad', t: "People keep dying in their sleep in this town." },
    { n: "Nobody laughed. Rio didn't mean it to be funny. She held Saori's hand on the desk, hard, in front of everybody, and didn't care who saw." },
    { n: "In 3-F's classroom, after school, the row of chalk hills was still on the blackboard from September. The tree beside the last one, in different chalk. Somebody had rubbed out what had been hanging in it. Badly. You could still see where." },
    { flag: 'eqx-edogawa-dead' }
  ] },

  { id: 'eqx-forget-the-year', date: '12/18', slot: 'evening', consumes: true, title: 'a party for forgetting', place: 'Iwatodai Dorm · Lounge', time: 'Evening',
    cast: { solar: 'Solar', junpei: 'Junpei', mitsuru: 'Mitsuru', yukari: 'Yukari', hanni: 'Hanni', mrsoka: 'Mrs. Oka', ken: 'Ken', 'kim-dad': 'Mr. Kim', 'solji-runners': 'Solji' },
    scene: [
    { bg: 'iwatodaidorm-livingroom-christmas', music: 'dorm' },
    { n: "Junpei had made a banner." },
    { n: "Six meters of butcher paper from the craft shop by the station, laid out down the length of the lounge floor, with Ken holding one end flat and Koromaru lying on the other, and Junpei on his knees in the middle of it with a paint pot, doing the letters. In red, because it was the only big pot left. FORGET THIS YEAR!!! Three exclamation marks. Then he'd sat back on his heels and looked at it and added a fourth." },
    { s: 'junpei', f: 'neutral', t: "Bonenkai. Forget-the-year party. It's a thing. It's a real thing. Every company in Japan does one. You eat a lot and you drink a lot and you forget the whole year happened." },
    { s: 'yukari', f: 'neutral', t: "Junpei, it's in *red*. It looks like a threat." },
    { s: 'junpei', f: 'serious', t: "It's festive! Red is festive! It's Christmas! Christmas is red!" },
    { s: 'yukari', f: 'sad', t: "...Yeah. Okay. Sure." },
    { n: "Nobody said it. Everybody thought it. Solar watched the whole lounge think it at once, looking at the six meters of wet red paint on the floor: that there was no forgetting this year. That this year had a body count you could read off a whiteboard. That half the people in this room were sleeping sitting up, or on the floor at the foot of a chair, or in a hall across a doorway, or not at all." },
    { n: "Junpei knew. Of course Junpei knew. He knelt in the middle of his banner with red paint to his elbows and looked up at all of them, at all their faces, and his own face did something brave and terrible." },
    { s: 'junpei', f: 'sad', t: "...I know. Okay? I know. I know you can't forget it. I can't either. I've got a notebook. I've got names crossed out in it. I'm not trying to forget anything. I just want one night. One night where we eat a lot of food and somebody does karaoke badly and nobody dies. That's it. That's the whole party." },
    { s: 'junpei', f: 'sad', t: "Tuesday. The twenty-first. After school. Everybody. Even the dads. Even Mitsuru-senpai. Please." },
    { n: "He'd said please. Solar looked at Mitsuru. Mitsuru was looking at the banner." },
    { s: 'mitsuru', f: 'neutral', t: "...Tuesday. The twenty-first. Before the hour. I'll order the food." },
    { s: 'mitsuru', f: 'neutral', t: "Iori. Red is not festive." },
    { s: 'junpei', f: 'happy', t: "It's festive *now*, senpai." },
    { n: "Ken read the calendar on the kitchen wall. The twenty-first. Somebody had written on it in pencil, in Fuuka's small hand: *total lunar eclipse, 5:17 p.m.* And under it, in Akihiko's square capitals, newer: *FULL MOON.*" },
    { n: "Ken didn't say anything. He put his finger on the square, and kept it there a second, and took it away." },
    { place: 'Iwatodai Dorm · Front Hall', time: 'Evening', bg: 'iwatodaidorm-front-night', music: 'badfeeling', soft: true },
    { n: "The phone in the front hall rang at nine. The dorm's landline. Nobody ever called it. Solar was nearest; she picked it up." },
    { s: 'mrsoka', f: 'happy', t: "Oh— is that Solar? Oh, I'm so glad it's you, child. I was hoping it would be you." },
    { n: "Solar's whole body went cold. From the scalp down." },
    { s: 'mrsoka', f: 'happy', t: "I hear you're having a party. On the twenty-first. To forget the year. Isn't that lovely. Isn't that just the loveliest idea. I'd have come, you know, if anyone had asked me. But never mind. That's not why I called." },
    { s: 'mrsoka', f: 'neutral', t: "It's Christmas I'm calling about. Christmas Eve. I've got the long table, haven't I, and nobody at it now, not since the girls went, and I can't bear it. All those places. I'd like to do a Christmas supper. A proper one. For all of you. The parents, the girls, your Hanni, the boys from the guesthouse. Everyone." },
    { s: 'mrsoka', f: 'sad', t: "Stay for Christmas, Solar. All of you. At my table. Just one more night. It's been such a sad year. Let me feed you all, just once more, all together, the way it should be. You'll ask them for me, won't you? They'll listen to you." },
    { n: "Behind her in the lounge, Junpei was laughing at something. Mr. Kim was singing, badly, under his breath, a Christmas song with the wrong words. Solji was sitting at the front edge of the couch, her back not touching anything, with her eyes closed, listening." },
    { choose: [
      { t: "We'll come. Of course we'll come. I'll tell everyone.", tally: { cakes: 1, 'asks.solar.christmas': 'yes' }, flag: 'eqx-xmas-oka', then: [
        { n: "It came out of her mouth in the Foundation-dinner voice. Warm. Pleasant. Agreeable. The voice that had said yes to every man who'd asked her to dance at every benefit on the Upper East Side since she was fourteen. She heard it come out and couldn't stop it." },
        { s: 'mrsoka', f: 'happy', t: "Oh, good girl. Good girl. I knew you would. I'll set every place." },
        { n: "The line went dead. Solar stood in the hall with the receiver in her hand and the dial tone in her ear, and something in her chest felt warm and full and terribly satisfied, the way it had in the lounge in October; and under it, very small, the taste of sugar." }
      ] },
      { t: "We're having Christmas here. Thank you. No.", tally: { 'asks.solar.christmas': 'no' }, then: [
        { n: "There was a silence on the line. Long. And something in it that Solar felt rather than heard; a degree of cold coming down the wire, the way the kitchen had gone a degree colder in April." },
        { s: 'mrsoka', f: 'sad', t: "...Of course. Of course you are. Never mind. I'll keep a place for you anyway. I always keep a place." }
      ] },
      { t: "Everyone can decide for themselves where they want to be on Christmas. I won't ask anyone for you.", tally: { choose: 1, 'asks.solar.christmas': 'choose' }, flag: 'eqx-xmas-mine', then: [
        { n: "Silence on the line. Then, very softly, a laugh. Fond. Delighted. The laugh of a woman who's just watched a child do something clever." },
        { s: 'mrsoka', f: 'happy', t: "...Isn't that a lovely thing to be able to say. Decide for themselves. My, my. You've grown up this year, haven't you, child. You've grown up so much." },
        { s: 'mrsoka', f: 'neutral', t: "Well. We'll see what they decide, then. We'll see." },
        { n: "The line didn't go dead. It stayed open. Solar stood with the receiver to her ear and listened to it stay open, the faint hiss of the line, and under the hiss, very low, somebody humming. She put the receiver down." }
      ] }
    ] },
    { n: "When she went back into the lounge Hanni looked up from the couch, from the rota on her knees, and looked at Solar's face, and put the rota down." },
    { s: 'hanni', f: 'neutral', t: "...Who was it?" },
    { s: 'solar', f: 'neutral', t: "Nobody. A wrong number." },
    { n: "Hanni looked at her for a long time. Then she picked up the rota again and wrote something in the box for the twenty-first, small, in pencil, beside the two names already there. A third name. Her own." }
  ] },

  { id: 'eqx-what-are-we', date: '12/19', slot: 'late', consumes: true, title: 'what are we, again', place: 'Iwatodai Dorm · Roof', time: 'Late Night',
    cast: { solar: 'Solar', haechan: 'Haechan' },
    scene: [
    { bg: 'iwatodaidorm-roof-night-snow', music: 'romance' },
    { n: "It snowed on Sunday night. The first snow. Not much. A few flakes coming down out of the dark over the roof at eleven, slow, the kind that doesn't settle, that lands on your sleeve and is gone before you can look at it." },
    { n: "Haechan was out there already. In his coat, on the old bench by the planters, with two cans of hot coffee from the machine downstairs, one in each pocket, the way he'd brought them to the strip in April. He took one out and held it out to her without looking round when the door opened." },
    { n: "She sat down beside him. She held the can. It was the system: she held hers till it wasn't hot. He'd invented it in April, at eleven at night on the strip, and they'd kept it all year." },
    { n: "For a long time neither of them said anything. The snow came down. The town below them was lit and quiet, the lights along the river, the station, the bridge. Down the hill, on the river street, a persimmon tree, bare, against a lit window." },
    { s: 'haechan', f: 'neutral', t: "...Can I ask you something." },
    { s: 'solar', f: 'neutral', t: "You don't ask things. That's your whole thing this year." },
    { s: 'haechan', f: 'neutral', t: "Yeah. I know. I'm aware. This isn't that kind. This isn't the kind where I want something from you. This is the other kind. The kind where I just don't know." },
    { s: 'haechan', f: 'neutral', t: "What are we, again?" },
    { n: "He said it to the town. Not to her. Very lightly. The way you'd ask what time it was." },
    { s: 'haechan', f: 'neutral', t: "Because I've lost track. Genuinely. I've been two people all year in one dorm and I've been the guy who climbed down and the guy who doesn't ask and the guy who sits on a stair with your dad. And I've kept every receipt. And I still don't know. In one of my lives we were a thing everybody talked about and in the other one we were a thing nobody was allowed to talk about, and here— here nobody talks about it at all. Here it's just us. And I don't know what it is." },
    { s: 'haechan', f: 'sad', t: "Somebody died on the stairs for your dad. Somebody's hanging in a tree. Your moms have stitches. And I'm sitting on a roof wanting to know what we are. That's insane. I know that's insane." },
    { s: 'haechan', f: 'neutral', t: "I still want to know." },
    dating('haechan', [
      { n: "She looked at him. At the side of his face in the snow. At the scar across his palm round the can, the straight pink line from the rope. At the receipts she knew were in his room on the corkboard, one for every night since April, the wall of them." },
      { n: "She took the can out of his hand. Put it down on the bench with hers. And took his face in her two cold hands and turned it toward her, and kissed him, in the snow, on the roof, slowly; not the way you kiss someone to answer a question; the way you kiss someone because the question was the most beautiful thing anyone had said to you all year." },
      { n: "When she pulled back he was looking at her with his eyes wide and dark and the snow on his eyelashes." },
      { s: 'solar', f: 'neutral', t: "...That's what we are." },
      { s: 'haechan', f: 'flustered', t: "...That's not an answer. That's a— that's a really good non-answer. That's the best non-answer I've ever gotten." },
      { s: 'solar', f: 'neutral', t: "It's an answer. You just don't have a word for it." },
      { s: 'haechan', f: 'neutral', t: "...Yeah. No. I don't." },
      { n: "He put his forehead against hers. The snow came down on both of them." },
      { s: 'haechan', f: 'sad', t: "I want you to stay. I'm saying it out loud. I want it so loud I'm scared you can hear it. I want you here, with me, on this roof, every night, forever, and I'm never going to ask you for it. Not once. Because if I ask you and you say yes, I'll never know if it was you." },
      { s: 'haechan', f: 'neutral', t: "So that's what we are. We're a guy who wants it and doesn't ask. And a girl who decides. Whatever you decide. That's what we are." }
    ], [
      { choose: [
        { t: "We're us. Whatever that is. I don't have a better word either.", flag: 'eqx-hc-what-us', then: [
          { n: "He laughed. It went up into the snow." },
          { s: 'haechan', f: 'happy', t: "*Us.* Okay. Okay, I'll take us. That's a word. It's a stupid word, it's the stupidest word, but I'll take it." },
          { n: "He leaned over and bumped his shoulder against hers. Left it there. The snow came down." }
        ] },
        { t: "(Don't answer. Lean your head on his shoulder.)", flag: 'eqx-hc-what-lean', then: [
          { n: "She didn't say anything. She leaned over and put her head on his shoulder, on the cold wool of his coat, and closed her eyes." },
          { n: "He went very still. Then she felt him breathe out, all the way, a long breath, and his cheek came down on top of her head, and stayed." },
          { s: 'haechan', f: 'neutral', t: "...Yeah. Okay. That's a pretty good answer, actually." }
        ] },
        { t: "You tell me. You're the one keeping receipts.", flag: 'eqx-hc-what-receipts', then: [
          { s: 'haechan', f: 'smirk', t: "...Oh, you know about the receipts." },
          { s: 'solar', f: 'neutral', t: "Everybody knows about the receipts. Junpei has odds on the receipts." },
          { s: 'haechan', f: 'neutral', t: "Okay. Fine. The receipts say: every night since April, I went and got two cans and one of them was yours. That's all they say. That's all I've got. Two cans." },
          { s: 'solar', f: 'neutral', t: "That's a lot." },
          { s: 'haechan', f: 'neutral', t: "...Yeah. It is, isn't it." }
        ] }
      ] }
    ]),
    { n: "At midnight the town went red under them. The snow kept falling through it, red now, slow, every flake a little ember. Down the hill, on the river street, behind the bare persimmon tree, the lit window of the boarding house didn't go red. It stayed yellow. Warm. A kitchen light. The only one in town." },
    { n: "Haechan saw it too. He didn't say anything. He took her hand, on the bench between them, and held it, and they watched the yellow window together until the hour was over, and the whole time, something in it, behind the glass, small and patient, was watching them back." }
  ] },

  { id: 'eqx-1221', date: '12/21', slot: 'evening', consumes: true, title: 'it’s only me', place: 'Iwatodai Dorm · Lounge', time: 'Evening',
    cast: { solar: 'Solar', junpei: 'Junpei', elizabeth: 'Elizabeth', mrsoka: 'Mrs. Oka', ken: 'Ken', yukari: 'Yukari', akihiko: 'Akihiko', haechan: 'Haechan', mitsuru: 'Mitsuru',
      hanni: 'Hanni', hyein: 'Hyein', yunjin: 'Yunjin', fuuka: 'Fuuka', chenle: 'Chenle', 'jaesang-runners': 'Jaesang', 'kim-mom': 'Mrs. Kim' },
    scene: [
    { bg: 'iwatodaidorm-livingroom-christmas', music: 'joy' },
    { n: "The party started at three-thirty. Junpei's banner was up over the kitchen door, FORGET THIS YEAR!!!!, the red gone a little brown as it dried, and nobody said anything about it, and by four the lounge was so full you couldn't see the floor." },
    { n: "Everybody came. That was the thing Solar would hold onto, afterward, for the rest of the year. For one hour on the twenty-first of December, everybody came." },
    { n: "The dorm. The guesthouse, all of it, the trio in a row on the stairs eating chips out of one bag, the Hate Club round the TV arguing about the karaoke machine Junpei had borrowed from Hagakure's owner, Jihoon and Cherry on the windowsill with Cherry's cake between them, the one she'd promised in April for three digits and made at four in the morning in Mr. Bakery's oven. The girls from the guesthouse now, all five, Yunjin with them, cross-legged on the floor in a circle. Mark in his coat by the piano nobody played, playing it, quietly, something long with no name. Danielle on the stairs with her phone up, filming the room for once, the whole room, and not deleting anything." },
    { n: "The six parents on the couches. Solji at the very front edge of the cushion. Mrs. Kim upright in her armchair with a plate on her knees and Mr. Kim on the floor at her feet. Miseon at the kitchen table, where she could see everyone, with Taejoon standing behind her chair, not touching it." },
    { ifFlag: 'dead.shinjiro', then: [
      { n: "By the kitchen door, the plain chair. Nobody sat in it. Somebody had put a plate on it, a full one, with chopsticks laid across the top. Ken had. Ken stood beside it the whole party, eating his own plate standing up." }
    ], else: [
      { n: "By the kitchen door, the plain chair, and Shinjiro in it, with his arms folded, watching the stove where three pots were going, and every so often getting up to stir one and sitting down again and telling Junpei to get out of his kitchen." }
    ] },
    { ifFlag: 'dead.aigis', then: [
      { n: "On the windowsill by the door, where she used to stand at midnight and count, Junpei had put the frog notebook, open, at the grid. Every box ticked for the day. Except one row. He'd left it. He hadn't crossed it out. He'd left the boxes empty." }
    ] },
    { n: "And Elizabeth." },
    { n: "She came at four, through the front door, like a person. She'd never come through a front door in her life, Solar thought. She stood in the genkan in a blue coat over her blue dress with snow in her hair and her gloved hands clasped in front of her and looked at the lounge, at all of it, the noise and the food and the banner and the people, and her whole face lit up from the inside like a lamp coming on." },
    { s: 'elizabeth', f: 'happy', t: "Oh. Oh, this is a party. This is what a party is. Look at it. Look at all of it." },
    { s: 'junpei', f: 'happy', t: "You made it! Velvet-san! Come in, come in, get a plate, you gotta eat a lot, that's the rule, you eat a lot and you forget the year—" },
    { s: 'elizabeth', f: 'happy', t: "I shall forget everything. I've been practicing. Theo is holding the door. I told him I'd bring him a description of the cake." },
    { n: "She ate a lot. She ate everything anyone put in front of her, with enormous concentration, and asked the name of every dish, and wrote some of them down on her wrist under the faded words that were already there. She sang one line of a song on Junpei's karaoke machine, off-key, delighted, and the whole room clapped, and she bowed to it." },
    { n: "At four-thirty Fuuka came down from the command room with her headset round her neck and said, quietly, to Mitsuru, and then to the room: *it's starting. The moon. Come and see.*" },
    { place: 'Iwatodai Dorm · Roof', time: 'Evening', bg: 'iwatodaidorm-roof-evening', music: 'mystery' },
    { n: "They went up to the roof to watch it rise. All of them. Forty people on the dorm roof in coats and blankets with their plates still in their hands, in the cold, at the rail, looking east." },
    { n: "It came up out of the bay at a quarter to five already eaten." },
    { n: "The sun was going down behind them in the west, and the moon came up in front of them over the water in the east, and it was the wrong color. A full moon coming up with a bite out of it, a dark curve across its face like a shadow across a plate, and the part that wasn't dark not white but copper, rust, the color of something left out in the rain. It rose. And as it rose the shadow crossed it, slowly, eating it; and the lit part got smaller and the dark part got redder; and at seventeen minutes past five, with the last of the sun gone and the sky gone the dark blue of a bruise, it was a whole red moon. Hanging over the bay. Huge. The color of the inside of a mouth." },
    { n: "Nobody spoke. Mr. Kim had his camera up and wasn't filming. Akihiko had the stopwatch in his hand and wasn't starting it." },
    { s: 'fuuka', f: 'sad', t: "...It's not the hour. It's not midnight. It's still today. But it's like the bridge. It's like the bridge was in September. Everything's... ajar." },
    { n: "Solar went down for blankets. Somebody had said the old ladies were cold, meaning the mothers, meaning Mrs. Kim, who'd said she wasn't; and Solar was nearest the stairs; and she went down alone through the empty dorm, past the party's plates on every surface and the banner over the kitchen door, to the front hall, where the spare blankets were kept in the closet." },
    { place: 'Iwatodai Dorm · Front Hall', time: 'Evening', bg: 'iwatodaidorm-front-night', music: 'badfeeling' },
    { n: "Koromaru was across the inside of the front door. He hadn't gone up to the roof. He'd lain across that door every night since April and he wasn't going to stop for a moon." },
    { n: "Solar had her arms full of blankets when the knock came." },
    { n: "Twice. On the front door. Politely. A pause. Twice." },
    { n: "Koromaru stood up." },
    { n: "Solar stood in the hall with the blankets against her chest. It was five-twenty in the afternoon. It wasn't the hour. The lamps were on in the street; she could see them through the glass, ordinary lamps, yellow, and a car going past at the bottom of the hill with its headlights on, and somebody's radio. The town was the town. Nobody had gone to coffins. It was a Tuesday evening in December and someone was at the door. That was all. People knocked on doors. Knocking was a thing people did." },
    { n: "*Hanni's rule: nobody opens a door in the red.*" },
    { n: "It wasn't red. It wasn't the red." },
    { n: "*Solar, child*, said a voice through the door. Warm. Small. Kind. *It's only me. I brought the cake you forgot to order. For your party. I knew you'd forget. You always forget something. Let me in, it's so cold.*" },
    { n: "She put the blankets down on the step. She didn't decide to. Her body did it. Her hand went to the latch the way Hyein's hand had gone to it on the twenty-eighth of April, the way it had gone to the latch under the water; and she watched it go, and she thought, very clearly, *it's not the hour. It's daytime. It's only a woman with a cake. It's safe. You've been safe all year in the daytime. It only ever comes at night.*" },
    { n: "She opened the door." },
    { n: "Mrs. Oka was on the step." },
    { n: "On the step. Not at the bottom of the steps; on the top one, the one she'd never come up, not once all year. Small, in her gray kimono and her shawl, with the red moon huge in the sky over her shoulder. There was no cake. Her hands were folded in front of her at her waist, the way a woman folds her hands at a funeral, or at a door, waiting to be asked in." },
    { n: "She wasn't wearing her gloves." },
    { n: "Solar looked at the hands." },
    { n: "She'd thought, all year, that when she saw them she'd scream. She didn't. She looked at them for a long time, quite calmly, with the cold coming in round her and the party going on two floors up, Junpei's karaoke machine faint through the ceiling; the way you look at a thing you've known was there for a long time and are only now being allowed to see." },
    { n: "They were very large. Much too large for the sleeves they came out of. Coarse. The color of dry grass, striped across with black, the stripes going round them like the bars of a cage. Floured. Dusted white all over, fine and pale, the flour worked so deep into the fur that it had gone gray at the knuckles from years of it. And at the end of every finger, folded under, resting, the long curved yellow points." },
    { n: "Folded neatly. One over the other. At a landlady's waist. Patient." },
    { s: 'mrsoka', f: 'happy', t: "There you are." },
    { n: "Her face was Mrs. Oka's face. Kind. Small. Lined. The face that had poured everyone's tea all year and known how each of them took it. But looking at it now, Solar could see where it sat. Where it didn't quite sit. At the jaw, on the left side, at the hinge, a fold. A slip. The way a mask slips when you smile too hard inside it." },
    { s: 'mrsoka', f: 'neutral', t: "Stay, child. Won't you. Stay." },
    { n: "Not loud. Not the way the reflections had said it, or the faces in the tree, or the tide. The old way. The way she'd said it on the sixteenth of April at the kitchen door with two places laid. The way she'd said it on the bridge at dawn with the tea. The way every mother says it at every door. *Stay for supper. Stay till the rain stops. Stay one more day.*" },
    { s: 'mrsoka', f: 'happy', t: "You and all of them. Every one of them. Up on that roof. Stay with me. I'll look after you all. I'll never let anyone go home to an empty house again. I'll never let anyone be the one nobody stopped for. Isn't that what you want? Isn't that what you've always wanted, every one of you? Everyone in one place. Everyone held." },
    { s: 'mrsoka', f: 'neutral', t: "It's only me." },
    { n: "Koromaru went past Solar's legs." },
    { n: "She felt him go. A white streak. Low, silent, all at once, the way he'd gone for Shadows in another year when they came for Ken; past her knees and off the step and up, at the landlady's throat, his jaws open, his whole small body behind it, every night of lying across that door in it." },
    { n: "One of the hands came up. Not fast. It didn't need to be fast. It came up the way you'd brush a moth off your sleeve." },
    // Nov 16 2026 (Kat): no animal is ever hurt. Koromaru goes for her and is caught before the hand lands; the doorframe takes it.
    { n: "It would have caught him across the face. Solar saw that afterwards, every time she shut her eyes: the points coming round, unhurried, at exactly the height of a small dog's head. It didn't, because Ken was already on the step. He'd come down the stairs three at a time without anyone hearing him, and he caught Koromaru round the middle in midair, and the two of them went sideways off the step into the snow together, and the hand went through the place where the dog's head had been and into the doorframe instead." },
    { n: "Four long grooves opened in the old wood, from the height of Solar's shoulder to the height of her knee. Clean and pale and deep enough to lay a finger in. The sound it made was a sound wood shouldn't make, slow, like something being unzipped." },
    { s: 'mrsoka', f: 'sad', t: "...Naughty dog. Dogs never like me. I did tell you." },
    { n: "She looked down at them, the boy and the dog tangled in the snow at the bottom of the steps, Ken's arms locked round Koromaru's chest and Koromaru still straining forward against them without a sound, his lips back off his teeth, with a face full of real regret. Then back up at Solar. And smiled, and the fold at the jaw slipped." },
    { s: 'mrsoka', f: 'happy', t: "Never mind. I'll wait for you at the bottom. Take your time, child. I've waited so long already. I can wait a little longer." },
    { n: "She turned round. She went down the steps, past the dog, unhurried, in her gray kimono, with her terrible hands folded at her waist again, and walked away down the hill toward the river in the light of the red moon, small, kind, and somewhere in the dark she started to hum." },
    // CG: eqx-red-moon-door — seen from inside a dark front hall past a girl's shoulder, an open front door onto snowy steps and a street at dusk under a huge copper-red eclipsed moon, a small figure in a gray kimono standing on the top step with its hands folded at its waist.
    { n: "Somebody screamed on the stairs behind her. Fuuka, with both hands over her mouth, looking at the doorframe." },
    { n: "And somebody else said one word. Very quietly. Elizabeth, on the landing, halfway down, in her blue coat, with snow still in her hair, with her gloved hand pressed flat against her chest as if something had gone through it." },
    { s: 'elizabeth', f: 'surprised', t: "...Theo." },
    { n: "And then she wasn't on the landing anymore." },
    { place: 'The Oka Boarding House · Garden', time: 'The Red Hour', bg: 'eqx-courtyard-well-night', music: 'tension' },
    // BG: oka-garden-red — the walled garden of an old Japanese house in red eclipse light, a bare persimmon tree, a heavy stone well cap thrown aside and cracked in two on the frozen grass, the dark mouth of the well open.
    { n: "Yukari stayed on the front step while they ran. They left her there with Ken, kneeling in the snow, running her hands over the dog twice, three times, nose to tail, because none of them could quite believe it: not a scratch. Not anywhere. Ken had his face in Koromaru's ruff and was saying his name over and over, and Koromaru twisted round in his arms to keep his eyes on the dark at the bottom of the hill where she'd gone, and growled, low, all the way down in his chest, and didn't stop." },
    { n: "The rest of them ran." },
    { n: "Down the hill. Along the river street. The red came over the town as they ran, early, at five-thirty in the evening, the moon pulling it down over everything like a cloth: the streetlights going red, the windows going red, people on the pavement stopping mid-step and going to coffins, standing, upright, in their coats, with their shopping bags, every coffin in the street turned the same way. Toward the river. Toward the boarding house. Akihiko started the stopwatch at five-thirty-one without slowing down." },
    { n: "The gate was open. The house was dark. The front door stood wide. Through it, in the hall, the genkan, the step, and on the step, three pairs of shoes that weren't there anymore; three clean shapes in the dust where they'd stood since September. Somebody had taken them. The rice-cake tin was on the kitchen counter, open." },
    { n: "In the garden, the well was open." },
    { n: "The stone cap lay on the frozen grass, split in two. Thrown. Four men to set it, Mrs. Oka had said in April. It lay four meters from the well's mouth, cracked straight through, as if it had been flipped off from below with one hand like the lid of a pot." },
    { n: "On the edge of the well, folded neatly, a white apron. And on the apron, a pair of white cotton gloves, darned at every fingertip, laid one on top of the other." },
    { n: "Chenle was on the radio. His voice coming small and fast through every headset at once." },
    { s: 'chenle', f: 'surprised', t: "Something big went down that well. Something huge. I heard it go. It went down headfirst. It's at the bottom now. It's the bottom of everything, it's under the Tree, it's under the— there's a *field* down there. It's lying down. It's waiting." },
    { s: 'fuuka', f: 'sad', t: "I can hear it breathing. Solar. I've never been able to hear that house. I can hear it now. It's so big." },
    { n: "Mitsuru stood at the lip of the well with her rapier in her hand and looked down into it, and then round at all of them, the whole household come down the river street behind her in the red: Akihiko with the stopwatch, Haechan, Yunjin and Hanni and Hyein with the new light still in them, Jungwon, Jihoon, Junpei, Minji with her camera, the fathers at the gate holding each other's arms, Jaehyun." },
    { s: 'mitsuru', f: 'serious', t: "...It's never been anyone at the door. It was always the one who opened it." },
    { s: 'mitsuru', f: 'serious', t: "Four of you. Solar. Haechan. Akihiko. Yunjin. The rest of you hold the rope." },
    { place: 'The Well · The Sorghum Field', time: 'The Red Hour', bg: 'eq-well-8', music: 'eerie' },
    { dark: true },
    { n: "The bottom of the Well was a field." },
    { n: "Red sorghum. To the horizon. Tall, taller than a man, the heavy heads of it bowed with grain, red, all of it red, red as the moon; and the moon over it, enormous, and under their feet, under the stalks, not earth. Sky. A night sky, starless, upside down, so that they walked on it and it went down under them forever, and the sorghum grew up out of it, out of nothing, by the roots, toward the red moon overhead." },
    { n: "The rows went away in every direction. Straight. Planted. Somebody had planted this, a long time ago, and tended it, and come back every year to see how it grew." },
    { n: "And in the middle of the field, a long way off, so big that at first Solar took it for a hill, something lay with its chin on its paws among the rows, watching them come." },
    { n: "Striped. The color of dry grass, barred with black. Dusted white. Lying the way a cat lies in the sun, at ease, its huge head on its huge folded forepaws; and on one of the paws, caught on the claws, a scrap of white cloth. An apron string. Its eyes were open. Its eyes were the kindest eyes Solar had ever seen in her life." },
    // CG: eqx-sorghum — an endless field of tall red sorghum under a huge red moon, the night sky reflected beneath the stalks instead of earth, and far off among the rows a vast striped shape lying at rest like a hill.
    { n: "Between it and them, the field stood up." },
    { n: "Not the sorghum. The moon. The red moon came down off the sky into the field, the way a coin comes down into a well, slowly, turning, and stood in the rows in front of them, burning; a black sun with a corona of red blades, the eclipse itself come down to stand guard; and round it, the sorghum pulled up its own roots out of the sky and came walking, tall red shapes with their heavy heads bowed, rustling, rustling, *stay, stay, stay*." },
    { s: 'akihiko', f: 'serious', t: "...It wants a guard. Of course it does. It's lying down. It wants to watch." },
    { s: 'yunjin', f: 'serious', t: "Then let's give it something to watch. *" + PERSONA.yunjin + "!*" },
    { s: 'haechan', f: 'serious', t: "*Dalnim.*" },
    { summon: 'haenim', name: 'Haenim', sub: 'Red moon.' },
    { battle: { id: 'eqx-1221', op: 'eqx-1221', kind: 'operation', title: 'Full Moon · Red Moon', desc: 'The bottom of the Well, a field of red sorghum to the horizon with the sky underfoot, the eclipsed moon come down to stand in the rows, and something enormous lying among them with its chin on its paws, watching.', forced: true } },
    { music: 'night' },
    { n: "The red moon broke like a plate. It went down into the field in pieces, and every piece was dust, white, fine, sweet; and the sorghum that had walked lay down in its rows, and the field was quiet." },
    { n: "The thing among the rows hadn't moved. It was still lying with its chin on its paws. It had watched all of it." },
    { n: "Now it lifted its head." },
    { n: "And spoke. Across the whole field, without raising its voice, so that it was in Solar's ear the way Fuuka was in her ear. In Mrs. Oka's voice. And then in Solji's. And Miseon's. And Mrs. Kim's. All of them at once, a chord of mothers." },
    { n: "*Stay. All of you. It's only me.*" },
    { n: "*Here, nobody goes home to an empty house. Here, nobody's ever the one nobody stopped for. Here, you can be all of them at once, child, all three of you, every one of them, for everyone, forever, and you'll never have to choose. Stay. It's only me. Open the door.*" },
    { n: "And Solar understood that this was it. That this was the question the whole year had been asking her, at every supper and every door and every bridge, and that whatever she said now in this field was what she'd said. The others felt it too; she saw it in their faces. Haechan with his hands in his pockets. Akihiko with his hand open at his side, not closing. Yunjin beside her with her shoulders down. Nobody looked at her. Nobody said anything. They were letting it be hers." },
    anyRank(['hanni', 'hyein', 'minji', 'jaehyun', 'mark', 'danielle', 'haechan'], 7, 'eqx-red-anchor-R'),
    anyRank(['yunjin', 'jungwon', 'haechan', 'trio'], 7, 'eqx-red-anchor-S'),
    anyRank(['jihoon', 'cherry', 'jungwon', 'hateclub', 'trio'], 7, 'eqx-red-anchor-H'),
    anyRank(['akihiko', 'mitsuru', 'yukari', 'junpei', 'aigis', 'ken-koromaru', 'fuuka-chenle', 'shinjiro'], 7, 'eqx-red-sees'),
    all([{ ifCount: { of: ['eqx-home-R1', 'eqx-home-R2', 'eqx-home-R3'], min: 2 } }, { ifFlag: 'eqx-red-anchor-R' }, { ifRank: { 'parents-runners': 9 } }], [{ flag: 'eqx-red-open-R' }]),
    all([{ ifCount: { of: ['eqx-home-S1', 'eqx-home-S2', 'eqx-home-S3'], min: 2 } }, { ifFlag: 'eqx-red-anchor-S' }, { ifRank: { 'parents-strangers': 9 } }], [{ flag: 'eqx-red-open-S' }]),
    all([{ ifCount: { of: ['eqx-home-H1', 'eqx-home-H2', 'eqx-home-H3'], min: 2 } }, { ifFlag: 'eqx-red-anchor-H' }, { ifRank: { 'parents-hoax': 9 } }], [{ flag: 'eqx-red-open-H' }]),
    all([{ ifCount: { of: DEAD, max: 0 } }, { ifCount: { of: ASKED, max: 0 } }, { ifCount: { of: MINE, min: 7 } }, { ifRank: { unknown: 8 } },
      { ifFlag: ['eqx-red-anchor-R', 'eqx-red-anchor-S', 'eqx-red-anchor-H', 'eqx-red-sees'] }], [{ flag: 'eqx-red-open-E' }]),
    { choose: [
      { t: "I have to go home. (The bell.)", when: { ifFlag: 'eqx-red-open-R' }, tally: { red: 'R' }, flag: 'eqx-red-R', then: [
        { n: "She heard it as she said it. Faint, far up, through the whole height of the Well. A bell. A little one, on a red cord, the kind you tie inside a door so you know when somebody's come in." },
        { n: "The thing in the field looked at her for a long time. Then it laid its head back down on its paws." },
        { n: "*Oh, child. The long way round. All right. All right. But you'll come back down to me first. They always do. On the way.*" }
      ] },
      { t: "I have to go home. (The jade ring.)", when: { ifFlag: 'eqx-red-open-S' }, tally: { red: 'S' }, flag: 'eqx-red-S', then: [
        { n: "She felt it on her finger as she said it. Cool. Green. A ring she wasn't wearing, turned once, all the way round, the way a woman turns it in a kitchen at night when the kettle's on." },
        { n: "The thing in the field laid its head back down on its paws." },
        { n: "*Before the tide, then. All right. But the tide comes in, child. It always comes in.*" }
      ] },
      { t: "I have to go home. (The star.)", when: { ifFlag: 'eqx-red-open-H' }, tally: { red: 'H' }, flag: 'eqx-red-H', then: [
        { n: "She felt it in her palm as she said it. Small. Sharp-pointed. A star, the kind you'd pin to a blazer, the points pressing in." },
        { n: "The thing in the field laid its head back down on its paws." },
        { n: "*A life nobody arranged. Is there such a thing. We'll see. We'll see.*" }
      ] },
      { t: "I'm staying. Because I want to.", tally: { red: 'stay' }, flag: 'eqx-red-stay', then: [
        { n: "She said it to the field. Not to the thing in it. To the red, and the rows, and the sky under her feet." },
        { n: "The thing among the rows was quiet for a long time. Then it laughed. Softly. The laugh of a woman who's been handed something she didn't ask for and finds she likes it anyway." },
        { n: "*Because you want to. Well. Well, well. That's not the same thing at all, is it. That's not the same thing as being asked.* It laid its head back on its paws. *We'll see if you still want to in spring.*" }
      ] },
      { t: "(Hold out your hand. Don't take hers.)", when: { ifFlag: 'eqx-red-open-E' }, tally: { red: 'equinox' }, flag: 'eqx-red-equinox', then: [
        { n: "She held out her hand. Open. Palm up. Into the red air of the field. Not toward the thing in the rows. Not toward anything. Just out. The way Yunjin held her hand out to the space on her left on the bridge part. The way you'd hold a hand out flat with nothing in it, to show you weren't taking, and weren't giving, and were here." },
        { n: "Behind her, she felt it. Haechan's hand. Not taking hers. Just coming up beside it, open, palm up, the same. Then Akihiko's. Then Yunjin's." },
        { n: "The thing in the field looked at the four open hands for a long, long time." },
        { n: "It didn't say anything at all. It only lifted its head off its paws, and looked up, past them, at the dark far overhead where the Well went up and up to the courtyard and the sky; where, if you looked hard, if you'd come down it on the first night of the year with someone's hand on your wrist, there was a rope. Gold. Frayed. Hanging." },
        { n: "And for the first time all year, its kind eyes weren't kind. They were afraid." }
      ] },
      { t: "(Open the door.)", tally: { red: 'bad' }, flag: 'eqx-red-bad', then: [
        { n: "There was a door in the sorghum. There'd always been a door. A plain one, standing between two rows, with a latch, the latch turned toward her hand. She hadn't seen it until now." },
        { n: "She went to it. Nobody stopped her. They'd let it be hers. Her hand went out to the latch, and it was warm, warm as skin, and she turned it, a quarter turn, and the thing in the field sighed behind her, very fondly, the way it had sighed behind the dorm's door in April." },
        { n: "*Good girl. Not yet. Not tonight. But soon. I'll set every place.*" },
        { n: "When she looked down her hand was on nothing, and the door was gone, and her palm was white with flour." }
      ] }
    ] },
    { flag: 'eqx-red-answered' },
    { n: "Then it closed its eyes. It lay in the field among the rows with its chin on its paws, the apron string caught on its claws, and breathed, slow and deep, like something asleep after a meal; and the field round it was very quiet; and the four of them turned round and walked back through the red sorghum the way they'd come, and nobody looked back, and nobody said anything, and at the bottom of the rope the others were holding, Solar put her hand on the gold, frayed in places, warm in one place where somebody had once tied a clumsy knot, and climbed." },
    { place: 'The Oka Boarding House · Garden', time: 'Night', bg: 'eqx-courtyard-well-night', music: 'night', soft: true },
    { dark: false },
    { n: "The eclipse was over when they came up. The moon over the river was white again, a full moon, ordinary, with nothing out of it. The red had gone off the town. Akihiko stopped the stopwatch at the lip of the well and looked at it and showed nobody." },
    { n: "The house was dark. Every window. The tin on the counter. The garden. The tree. The apron and the gloves were still folded on the edge of the well." },
    { n: "Solar picked up the gloves. She didn't know why. They were very light. Cotton. Darned at every fingertip, over and over, the darning pushed outward from inside, four small holes on each. They smelled of sugar, and rice, and a coat left in a cupboard all winter, and under it, at the back, something she'd smelled all year and never once let herself name." },
    { n: "She put them down again. On the apron. Folded. The way they'd been left. For whoever came looking." }
  ] },

  { id: 'eqx-held-door', date: '12/21', slot: 'late', consumes: true, title: 'he held it', place: 'The Velvet Room', time: 'Late Night',
    cast: { solar: 'Solar', elizabeth: 'Elizabeth' },
    scene: [
    { bg: 'velvetroom-1', music: 'velvet' },
    { n: "The blue door in the Paulownia passage was open when she got there. It had never been open. It was always shut, and always opened when she put her hand on it; tonight it stood wide on the dark of the closed mall, and the music that always came through it, the low long note under everything, wasn't playing." },
    { n: "The Room was quiet. That was the first thing. The Room had never once been quiet." },
    { n: "Elizabeth was on her knees on the floor." },
    { n: "On the blue velvet, in the middle of the Room, by the little table where the tea things were, overturned now, the cups in pieces, the pot on its side in a dark stain. On her knees with her back to the door, in her blue coat, with the snow from the party still melting in her hair. And in front of her, laid out on the velvet on his back, very straight, his hands folded on his chest, Theodore." },
    { n: "Someone had laid him out. Neatly. With care. The way you'd lay out someone you were fond of." },
    { n: "His face was gone." },
    { n: "Not torn. Taken. Lifted off, clean, from the hairline to the chin and from ear to ear, the way you'd lift the skin off warm milk with the back of a spoon, in one piece; and under it, nothing that had ever been meant to be seen, wet, red, the shape of a face without the face, the teeth bared in it to the roots. His eyes were gone with it. His hair was still neat. His collar was still buttoned. His gloves were still on his folded hands." },
    { n: "On his chest, under his folded hands, open, a book. Elizabeth's book. The one with every guest's page in it. Open at Solar's page." },
    { n: "Her page, with the three handwritings from the people who'd looked for her, and the fourth heavy one in the margin that had written *stay* all year; and across the bottom of it, new, in the heavy hand, pressed so hard the nib had gone through the paper and through the next page and into whatever was under it, into him, three words." },
    { n: "*it's only me*" },
    { n: "Behind them, at the back of the Room, the door. The one with the line of gold light under it that had burned all year." },
    { n: "The line wasn't gold anymore. It was red. And the door was shut. Properly. All the way. For the first time since March of last year." },
    { n: "Elizabeth didn't turn round. Her gloved hands were in her lap. She was looking at her brother." },
    { s: 'elizabeth', f: 'neutral', t: "...He held it." },
    { s: 'elizabeth', f: 'neutral', t: "I told him to hold it. For one night. So I could go to a party. And he held it. He stood in front of it the way I'd shown him, with both his hands flat on it, and it came through, and he didn't let go. He didn't let go." },
    { s: 'elizabeth', f: 'sad', t: "He was terribly heavy-handed with doors. I always said so. I always said so, and I laughed." },
    { n: "Solar knelt down beside her on the velvet. She didn't know what to do with her hands. She put one on Elizabeth's back, between her shoulder blades, and Elizabeth didn't flinch, didn't move at all, as if she hadn't felt it." },
    { s: 'elizabeth', f: 'neutral', t: "It shut the door behind it. When it left. Did you see? It closed it for me. All the way. Very politely. As if to say, there, you don't have to hold it anymore. I've done it for you." },
    { s: 'elizabeth', f: 'sad', t: "I wanted so much to let go of that door. I wanted it every night. I wrote it on my wrist." },
    { n: "She turned her hand over in her lap. Pushed back the cuff. The words were there. *it's just closed.* And under them, in her own handwriting from the party, from four hours ago, the names of three dishes she'd liked, and *cake: white, strawberries, Cherry's, very good, tell Theo.*" },
    { n: "She looked at it for a long time." },
    { s: 'elizabeth', f: 'neutral', t: "...I was going to bring him a description of the cake." },
    { n: "And Elizabeth, who had never in two years made a sound Solar didn't understand, made one. Low. Not a word. It came out of her and kept coming, and she bent forward over her brother on the velvet with her forehead almost touching the open book on his chest, and her shoulders shook, and Solar held on to her back with both hands and didn't say anything, because there wasn't anything; and the Room, around them, for the first time in its existence, was silent, and stayed silent, and didn't hum." },
    // CG: eqx-velvet-quiet — a blue velvet room in dim light, overturned tea things on the floor, an open book lying on the velvet, and a woman in a blue coat kneeling with her head bowed and her gloved hand resting on the edge of its page.
    { flag: ['eqx-theodore-dead', 'eqx-koromaru-stood', 'eqx-oka-revealed'] },
    { n: "At some point Elizabeth stopped. At some point she sat up, and wiped her face with the back of her glove, and looked at Solar, and her face had nothing in it. Not delight. Not curiosity. Not anything Solar had ever seen there. It was a face like a closed door." },
    { s: 'elizabeth', f: 'neutral', t: "Go home, Solar. Go and sit with your dog. He went for her for you tonight. He'll want to know you're home." },
    { s: 'elizabeth', f: 'neutral', t: "I'll see to my brother. That's mine." },
    { n: "Solar went. At the blue door she looked back. Elizabeth was on her knees on the velvet with the book closed now in her lap and her brother's gloved hand in hers, holding it, very lightly, the way you'd hold a hand on a train to wake someone gently; and behind her, at the back of the Room, the line under the shut door burned red." },
    { n: "Up the hill, in the dorm, in the front hall, Koromaru was lying across the inside of the door with Ken asleep against him, under the four pale grooves in the frame. When Solar came in he lifted his head and looked at her, and thumped his tail on the floor, twice, and put his head back down across the threshold." }
  ] }
);
}
